// ────────────────────────────────────────────────────────────────────────
// Heurísticas de importação
// ────────────────────────────────────────────────────────────────────────

const inferPhase = (stage, feedback) => {
  const f = (feedback || "").toLowerCase();
  if (stage === "Conquistado" || stage === "Proposta") return "proposal";
  if (f.includes("analisando proposta") || f.includes("fee r$") || f.includes("escopo enviado")) return "proposal";
  if (stage === "Escopo Enviado") return "proposal";
  if (stage === "Alinhamento" || f.includes("apresentação do escopo") || f.includes("gostaram da proposta")) return "meeting";
  if (stage === "Apresentação") return "started";
  if (f.includes("sem retorno") || f.includes("sem tempo")) return "none";
  return "started";
};

const inferTemperature = (stage, feedback) => {
  const f = (feedback || "").toLowerCase();
  if (stage === "Conquistado") return "hot";
  if (stage === "Perdida") return "cold";
  if (f.includes("analisando proposta") || f.includes("gostaram") || f.includes("aprovou")) return "hot";
  if (f.includes("aguardando decisão") || f.includes("apresentação do escopo") || f.includes("preparar escopo")) return "warm";
  if (f.includes("sem retorno") || f.includes("sem tempo") || f.includes("não vão investir") || f.includes("congelado") || f.includes("internalizaram") || f.includes("fechou com")) return "cold";
  return "warm";
};

