const getPeriodBounds = (period, refDate = new Date()) => {
  const now = new Date(refDate);

  if (period === "month") {
    const start = new Date(now.getFullYear(), now.getMonth(), 1);
    const end = new Date(now.getFullYear(), now.getMonth() + 1, 1);
    return { start, end, key: `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}` };
  }

  if (period === "biweekly") {
    // Quinzena de calendário: dia 1–15 ou 16–fim do mês
    const half = now.getDate() <= 15 ? 1 : 2;
    const start = half === 1 ? new Date(now.getFullYear(), now.getMonth(), 1) : new Date(now.getFullYear(), now.getMonth(), 16);
    const end = half === 1 ? new Date(now.getFullYear(), now.getMonth(), 16) : new Date(now.getFullYear(), now.getMonth() + 1, 1);
    return { start, end, key: `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-Q${half}` };
  }

  if (period === "semester") {
    const half = now.getMonth() < 6 ? 1 : 2;
    const start = new Date(now.getFullYear(), half === 1 ? 0 : 6, 1);
    const end = new Date(now.getFullYear(), half === 1 ? 6 : 12, 1);
    return { start, end, key: `${now.getFullYear()}-S${half}` };
  }

  if (period === "year") {
    const start = new Date(now.getFullYear(), 0, 1);
    const end = new Date(now.getFullYear() + 1, 0, 1);
    return { start, end, key: `${now.getFullYear()}` };
  }

  // semana (segunda a domingo) - padrão
  const dayIdx = (now.getDay() + 6) % 7;
  const start = new Date(now); start.setHours(0, 0, 0, 0); start.setDate(now.getDate() - dayIdx);
  const end = new Date(start); end.setDate(start.getDate() + 7);
  return { start, end, key: `${start.getFullYear()}-W${start.getMonth() + 1}-${start.getDate()}` };
};

// Calcula o valor atual de uma métrica pra um SDR dentro do período configurado
const computeMetricValue = (metricKey, sdrName, bounds, leads, meetings) => {
  const { start, end } = bounds;
  const inRange = (d) => { if (!d) return false; const dt = new Date(d); return dt >= start && dt < end; };
  if (metricKey === "leads") {
    return leads.filter((l) => l.owner === sdrName && inRange(l.createdAt)).length;
  }
  if (metricKey === "proposals") {
    return meetings.filter((m) => m.owner === sdrName && m.type === "proposta" && inRange(m.date)).length;
  }
  if (metricKey === "meetings") {
    return meetings.filter((m) => m.owner === sdrName && m.type !== "proposta" && inRange(m.date) && new Date(m.date) <= new Date()).length;
  }
  if (metricKey === "contracts") {
    return leads.filter((l) => l.owner === sdrName && l.stage === "Conquistado" && inRange(l.wonDate)).length;
  }
  return 0;
};
const storageAvailable = () => typeof window !== "undefined" && window.storage && typeof window.storage.get === "function";

const loadData = async (key, fallback) => {
  if (!storageAvailable()) return fallback;
  try {
    const result = await window.storage.get(key);
    if (result && result.value !== undefined && result.value !== null) {
      const parsed = JSON.parse(result.value);
      if (Array.isArray(parsed)) return parsed.length ? parsed : fallback;
      if (parsed !== null && parsed !== undefined) return parsed;
    }
    return fallback;
  } catch { return fallback; }
};
const saveData = async (key, data) => {
  if (!storageAvailable()) return;
  try { await window.storage.set(key, JSON.stringify(data)); } catch { /* silent */ }
};

