const formatDateFull = (d) => !d ? "-" : new Date(d).toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit", year: "numeric" });
const formatDateShort = (d) => !d ? "-" : new Date(d).toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" });
const daysSince = (iso_) => !iso_ ? null : Math.floor((Date.now() - new Date(iso_).getTime()) / 86400000);
const cleanPhone = (p) => (p || "").replace(/\D/g, "");
const parseFee = (feedback) => {
  if (!feedback) return 0;
  const m = feedback.match(/R\$\s*([\d.,]+)/i);
  if (!m) return 0;
  const n = parseFloat(m[1].replace(/\./g, "").replace(",", "."));
  return isNaN(n) ? 0 : n;
};
// Valor do contrato: usa o campo editável (dealValue) se existir, senão tenta extrair do feedback
const getDealValue = (lead) => (typeof lead.dealValue === "number" && lead.dealValue > 0 ? lead.dealValue : parseFee(lead.feedback));
const formatBRL = (n) => n.toLocaleString("pt-BR", { style: "currency", currency: "BRL", maximumFractionDigits: 0 });

// Mensagens padrão citam o nome do SDR responsável (lead.owner) em vez de "a equipe comercial"
// genérica, porque o cliente já sabe com quem está falando e estranha a formalidade impessoal.
const buildWhatsAppUrl = (lead) => {
  const num = cleanPhone(lead.whatsapp);
  if (!num) return null;
  const firstName = (lead.contactName || "").trim().split(" ")[0];
  const sdrFirstName = (lead.owner || "").trim().split(" ")[0];
  const from = sdrFirstName ? `Aqui é o(a) ${sdrFirstName}` : "Aqui é da equipe comercial";
  const greeting = firstName
    ? `Olá, ${firstName}! Tudo bem? ${from}, sobre a proposta para a ${lead.company}.`
    : `Olá! Tudo bem? ${from}, sobre a proposta para a ${lead.company}.`;
  return `https://wa.me/${num}?text=${encodeURIComponent(greeting)}`;
};
const buildMailUrl = (lead) => {
  if (!lead.email) return null;
  const subject = `Proposta comercial - ${lead.company}`;
  const firstName = (lead.contactName || "").trim().split(" ")[0];
  const sdrFirstName = (lead.owner || "").trim().split(" ")[0];
  const sign = sdrFirstName ? `\n\nAbraço,\n${sdrFirstName}` : "";
  const body = firstName
    ? `Olá, ${firstName},\n\nEspero que esteja bem! Escrevo para dar continuidade à nossa conversa sobre a ${lead.company}.\n${sign}`
    : `Olá,\n\nEspero que esteja bem! Escrevo para dar continuidade à nossa conversa sobre a ${lead.company}.\n${sign}`;
  return `mailto:${lead.email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
};
const dispatchContact = (type, lead, onLogged) => {
  let url = "";
  if (type === "whatsapp" && lead.whatsapp) url = buildWhatsAppUrl(lead);
  else if (type === "email" && lead.email) url = buildMailUrl(lead);
  else if (type === "phone" && lead.phone) url = `tel:${cleanPhone(lead.phone)}`;
  if (url) { window.open(url, "_blank"); onLogged && onLogged(lead.id, type); }
};

const isSameDay = (a, b) => new Date(a).toDateString() === new Date(b).toDateString();
const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x; };
const startOfWeek = (d) => { const x = new Date(d); const day = x.getDay(); const diff = day === 0 ? -6 : 1 - day; return addDays(x, diff); };
const WEEKDAY_LABELS = ["DOM", "SEG", "TER", "QUA", "QUI", "SEX", "SÁB"];
const MONTH_LABELS = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];

