  const firstName = (lead.contactName || "").trim().split(" ")[0];
  return firstName
    ? `Olá, ${firstName}! Tudo bem? Passando aqui sobre a proposta para a ${lead.company}.`
    : `Olá! Tudo bem? Passando aqui sobre a proposta para a ${lead.company}.`;
