// Troca {nome}/{Nome} e {empresa}/{Empresa} pelos dados reais do lead. Se não
// tiver nome de contato cadastrado, remove a saudação com nome com elegância.
const fillScriptTemplate = (template, lead) => {
  const firstName = (lead.contactName || "").trim().split(" ")[0];
  let result = template
    .replace(/\{nome\}/gi, firstName || "")
    .replace(/\{empresa\}/gi, lead.company || "sua empresa");
  if (!firstName) {
    result = result
      .replace(/^Oi, !\s*/i, "Oi! ")
      .replace(/^, tive/i, "Tive")
      .replace(/,\s+!/g, "!");
  }
  return result.replace(/\s{2,}/g, " ").trim();
};

// Tela colorida de escolha de script - abre ao tocar no aviãozinho num lead.
// Mostra os 10 tipos de abordagem já com o texto preenchido pro lead específico,
// pra escolher rapidinho qual mais combina com a situação.
const ScriptPickerModal = ({ lead, initialMessage, onClose, onSelect }) => {
  // Se abrir já com uma mensagem pronta (editando um lead que já está na fila),
  // pula direto pra etapa de edição. Senão, começa mostrando a lista de scripts.
  const [step, setStep] = useState(initialMessage ? "edit" : "pick");
  const [draftMessage, setDraftMessage] = useState(initialMessage || "");
  const [pickedTitle, setPickedTitle] = useState("");

  const pickScript = (s) => {
    setDraftMessage(fillScriptTemplate(s.template, lead));
    setPickedTitle(s.title);
    setStep("edit");
  };

  const confirm = () => {
    if (!draftMessage.trim()) return;
    onSelect(draftMessage.trim());
  };

  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(20,10,40,0.5)", backdropFilter: "blur(6px)", zIndex: 160, display: "flex", alignItems: "flex-end", justifyContent: "center", animation: "fadeIn 0.2s ease" }}>
      <div onClick={(e) => e.stopPropagation()} style={{ width: "100%", maxWidth: 560, maxHeight: "85vh", display: "flex", flexDirection: "column", background: "#f4f5f7", borderRadius: "24px 24px 0 0", overflow: "hidden", animation: "slideUp 0.3s cubic-bezier(0.4,0,0.2,1)" }}>
        <div style={{ background: "linear-gradient(135deg, #6d5ef8, #8b7bfa)", padding: "18px 22px", color: "white", flexShrink: 0 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
            <div>
              <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 17, fontWeight: 800 }}>{step === "pick" ? "Escolha um script" : (initialMessage ? "Editar script da fila" : "Editar mensagem")}</div>
              <div style={{ fontSize: 12, opacity: 0.85, marginTop: 2 }}>Pra {lead.company}{lead.contactName ? ` · ${lead.contactName}` : ""}</div>
            </div>
            <button onClick={onClose} style={{ width: 34, height: 34, borderRadius: 10, border: "none", background: "rgba(255,255,255,0.2)", color: "white", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><X size={17} /></button>
          </div>
        </div>

        {step === "pick" && (
          <div style={{ flex: 1, overflowY: "auto", padding: 16 }}>
            <div style={{ display: "flex", flexDirection: "column", gap: 10, maxWidth: 520, margin: "0 auto" }}>
              {SCRIPT_LIBRARY.map((s) => {
                const filled = fillScriptTemplate(s.template, lead);
                return (
                  <div
                    key={s.key}
                    style={{
                      textAlign: "left", padding: "14px 16px", borderRadius: 16, border: `1.5px solid ${s.color}30`,
                      background: "white", transition: "transform 0.12s ease, box-shadow 0.12s ease",
                      boxShadow: `0 2px 10px -6px ${s.color}40`,
                    }}
                    onMouseEnter={(e) => { e.currentTarget.style.transform = "translateY(-2px)"; e.currentTarget.style.boxShadow = `0 10px 22px -10px ${s.color}70`; }}
                    onMouseLeave={(e) => { e.currentTarget.style.transform = "translateY(0)"; e.currentTarget.style.boxShadow = `0 2px 10px -6px ${s.color}40`; }}
                  >
                    <button
                      onClick={() => onSelect(filled)}
                      title="Usar esse script direto"
                      style={{ width: "100%", textAlign: "left", background: "transparent", border: "none", cursor: "pointer", padding: 0, display: "flex", gap: 12 }}
                    >
                      <div style={{ width: 36, height: 36, borderRadius: 11, background: s.color + "18", color: s.color, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                        <s.icon size={16} />
                      </div>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontSize: 12.5, fontWeight: 800, color: s.color, marginBottom: 3 }}>{s.title}</div>
                        <div style={{ fontSize: 12, color: "#64748b", lineHeight: 1.45 }}>{filled}</div>
                      </div>
                    </button>
                    <button
                      onClick={() => pickScript(s)}
                      style={{ display: "flex", alignItems: "center", gap: 5, marginTop: 10, paddingTop: 10, border: "none", borderTop: `1px solid ${s.color}18`, background: "transparent", color: s.color, fontSize: 11.5, fontWeight: 700, cursor: "pointer", width: "100%" }}
                    >
                      <Pencil size={11} /> Editar antes de usar
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {step === "edit" && (
          <div style={{ flex: 1, overflowY: "auto", padding: 20 }}>
            <div style={{ maxWidth: 520, margin: "0 auto" }}>
              {!initialMessage && (
                <button onClick={() => setStep("pick")} style={{ display: "flex", alignItems: "center", gap: 6, border: "none", background: "transparent", color: "#6d5ef8", fontSize: 12.5, fontWeight: 700, cursor: "pointer", padding: 0, marginBottom: 14 }}>
                  ← {pickedTitle ? `Trocar (era: ${pickedTitle})` : "Escolher outro script"}
                </button>
              )}
              {initialMessage && (
                <div style={{ display: "flex", alignItems: "flex-start", gap: 8, background: "rgba(109,94,248,0.08)", border: "1px solid rgba(109,94,248,0.2)", borderRadius: 12, padding: "10px 12px", marginBottom: 14 }}>
                  <Pencil size={13} color="#6d5ef8" style={{ flexShrink: 0, marginTop: 2 }} />
                  <div style={{ fontSize: 11.5, color: "#4c3fa0", lineHeight: 1.4 }}>
                    Essa é a <strong>mensagem fixa guardada na fila</strong> pra esse lead. O que você salvar aqui fica valendo até você mandar (ou editar de novo). É diferente do <strong>"ajuste de última hora"</strong>, que só existe dentro do modo "Iniciar envio" (a tela que mostra um lead por vez pra confirmar) - lá, qualquer mudança vale só daquele envio, sem alterar o que fica salvo aqui.
                  </div>
                </div>
              )}
              <div style={{ background: "white", borderRadius: 18, padding: 18, border: "1px solid #eef0f3", boxShadow: "0 10px 30px -14px rgba(20,20,26,0.12)" }}>
                <label style={{ ...labelStyle }}><SecIcon icon={Pencil} color="#6d5ef8" />Ajuste o texto à vontade</label>
                <textarea
                  value={draftMessage}
                  onChange={(e) => setDraftMessage(e.target.value)}
                  rows={7}
                  autoFocus
                  style={{ ...inputStyle, resize: "vertical", fontFamily: "inherit", lineHeight: 1.5, fontSize: 13.5 }}
                />
              </div>
              <button
                onClick={confirm}
                disabled={!draftMessage.trim()}
                style={{ width: "100%", marginTop: 14, padding: "13px 0", borderRadius: 14, border: "none", background: draftMessage.trim() ? "linear-gradient(135deg, #6d5ef8, #8b7bfa)" : "rgba(148,163,184,0.3)", color: "white", fontSize: 13.5, fontWeight: 800, cursor: draftMessage.trim() ? "pointer" : "not-allowed" }}
              >
                {initialMessage ? "Salvar na fila" : "Usar essa mensagem"}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

// Histórico de conclusões da Lista da Semana, com filtro de período - pra
// responder "o que eu fiz nas últimas semanas/meses" sem precisar lembrar de cabeça.
const WEEK_HISTORY_RANGES = [
  { key: "7d", label: "7 dias", days: 7 },
  { key: "30d", label: "30 dias", days: 30 },
  { key: "90d", label: "3 meses", days: 90 },
  { key: "all", label: "Tudo", days: null },
];

const WeekHistoryScreen = ({ history, onClose, onOpenLead, leads }) => {
  const [range, setRange] = useState("30d");

  const filtered = useMemo(() => {
    const opt = WEEK_HISTORY_RANGES.find((r) => r.key === range);
    if (!opt || opt.days === null) return history;
    const cutoff = Date.now() - opt.days * 86400000;
    return history.filter((h) => new Date(h.date).getTime() >= cutoff);
  }, [history, range]);

  const grouped = useMemo(() => {
    const groups = {};
    filtered.forEach((h) => {
      const day = new Date(h.date).toLocaleDateString("pt-BR", { day: "2-digit", month: "long" });
      if (!groups[day]) groups[day] = [];
      groups[day].push(h);
    });
    return Object.entries(groups);
  }, [filtered]);

  const byVia = useMemo(() => {
    const counts = {};
    filtered.forEach((h) => { counts[h.via] = (counts[h.via] || 0) + 1; });
    return counts;
  }, [filtered]);

  return (
    <div style={{ position: "fixed", inset: 0, background: "#f4f5f7", zIndex: 200, display: "flex", flexDirection: "column", animation: "fadeIn 0.2s ease" }}>
      <div style={{ background: "linear-gradient(135deg, #6d5ef8, #8b7bfa)", padding: "16px 20px", color: "white", flexShrink: 0 }}>
        <div style={{ maxWidth: 600, margin: "0 auto" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <button onClick={onClose} style={{ width: 36, height: 36, borderRadius: 11, border: "none", background: "rgba(255,255,255,0.2)", color: "white", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                <ArrowLeft size={17} />
              </button>
              <div>
                <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 16.5, fontWeight: 800 }}>Histórico da Lista da Semana</div>
                <div style={{ fontSize: 11.5, opacity: 0.85 }}>{filtered.length} conclusõe{filtered.length === 1 ? "" : "s"} no período</div>
              </div>
            </div>
          </div>
          <div style={{ display: "flex", gap: 4, background: "rgba(0,0,0,0.15)", borderRadius: 12, padding: 4 }}>
            {WEEK_HISTORY_RANGES.map((r) => (
              <button key={r.key} onClick={() => setRange(r.key)} style={{ flex: 1, textAlign: "center", padding: "8px 4px", borderRadius: 9, border: "none", fontSize: 12, fontWeight: 700, cursor: "pointer", background: range === r.key ? "white" : "transparent", color: range === r.key ? "#6d5ef8" : "rgba(255,255,255,0.8)" }}>
                {r.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: 20 }}>
        <div style={{ maxWidth: 600, margin: "0 auto" }}>
          {filtered.length === 0 ? (
            <div style={{ textAlign: "center", padding: "60px 20px", color: "#94a3b8" }}>
              <ClipboardList size={32} color="#cbd5e1" style={{ marginBottom: 10 }} />
              <div style={{ fontSize: 14, fontWeight: 600 }}>Nada nesse período</div>
              <div style={{ fontSize: 12.5, marginTop: 4 }}>Tenta um intervalo maior, ou marque leads como concluídos na Lista da Semana.</div>
            </div>
          ) : (
            <>
              {/* Resumo por canal */}
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 20 }}>
                {Object.entries(byVia).map(([via, count]) => {
                  const cfg = WEEK_VIA_CONFIG[via] || WEEK_VIA_CONFIG.manual;
                  return (
                    <div key={via} style={{ display: "flex", alignItems: "center", gap: 6, padding: "7px 12px", borderRadius: 12, background: cfg.color + "12", border: `1px solid ${cfg.color}30` }}>
                      <cfg.icon size={12} color={cfg.color} />
                      <span style={{ fontSize: 11.5, fontWeight: 700, color: cfg.color }}>{count} {cfg.label.replace("Via ", "").replace("Marcado ", "")}</span>
                    </div>
                  );
                })}
              </div>

              {grouped.map(([day, items]) => (
                <div key={day} style={{ marginBottom: 18 }}>
                  <div style={{ fontSize: 11, fontWeight: 800, color: "#94a3b8", textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 8 }}>{day}</div>
                  <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                    {items.map((h) => {
                      const cfg = WEEK_VIA_CONFIG[h.via] || WEEK_VIA_CONFIG.manual;
                      const lead = leads.find((l) => l.id === h.leadId);
                      return (
                        <div
                          key={h.id}
                          onClick={() => lead && onOpenLead(lead)}
                          style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 14px", borderRadius: 14, background: "white", border: `1px solid ${cfg.color}22`, cursor: lead ? "pointer" : "default" }}
                        >
                          <div style={{ width: 32, height: 32, borderRadius: "50%", background: cfg.color + "18", color: cfg.color, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                            <cfg.icon size={14} />
                          </div>
                          <div style={{ flex: 1, minWidth: 0 }}>
                            <div style={{ fontSize: 13, fontWeight: 700, color: "#0f172a" }}>{h.company}</div>
                            <div style={{ fontSize: 11, color: "#94a3b8" }}>{h.owner} · {cfg.label}</div>
                          </div>
                          <div style={{ fontSize: 10.5, color: "#94a3b8", flexShrink: 0 }}>{new Date(h.date).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}</div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </>
          )}
        </div>
      </div>
    </div>
  );
};

const WaSendListScreen = ({ leadsInList, history, onClose, onRemove, onClear, onLogSent, onEditMessage }) => {
  const [editingLead, setEditingLead] = useState(null);
  const [mode, setMode] = useState("list"); // list | sending | done
  const [tab, setTab] = useState("fila"); // fila | historico (só usado quando mode === "list")
  const [idx, setIdx] = useState(0);
  const [message, setMessage] = useState("");
  const [sentCount, setSentCount] = useState(0);
  const [skippedCount, setSkippedCount] = useState(0);
  const [showCoin, setShowCoin] = useState(false);

  const validLeads = leadsInList.filter((l) => l.whatsapp);
  const withoutPhoneCount = leadsInList.length - validLeads.length;
  const currentLead = validLeads[idx];

  useEffect(() => {
    if (mode === "sending" && currentLead) setMessage(currentLead.waMessage || buildWaListDefaultMessage(currentLead));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [idx, mode]);

  const startSending = (fromIdx = 0) => {
    if (validLeads.length === 0) return;
    setIdx(fromIdx); setSentCount(0); setSkippedCount(0);
    setMode("sending");
  };

  // Abre o WhatsApp direto pra um lead específico sem entrar no modo de fila -
  // usado pelo botão de envio rápido em cada linha da lista.
  const sendDirect = (lead) => {
    const num = cleanPhone(lead.whatsapp);
    const msg = lead.waMessage || buildWaListDefaultMessage(lead);
    window.open(`https://wa.me/${num}?text=${encodeURIComponent(msg)}`, "_blank");
    onLogSent(lead.id, msg);
    triggerCoin();
  };

  const triggerCoin = () => {
    setShowCoin(true);
    setTimeout(() => setShowCoin(false), 900);
  };

  // Só mostra a telinha de "concluído" se pelo menos um envio realmente aconteceu -
  // se a pessoa só pulou todo mundo (ou saiu no meio), volta pra lista sem comemoração,
  // e quem não foi enviado continua na fila etiquetado como pendente.
  const goNext = (justSent) => {
    const isLast = idx + 1 >= validLeads.length;
    if (isLast) {
      if (justSent || sentCount > 0) setMode("done");
      else setMode("list");
    } else {
      setIdx((i) => i + 1);
    }
  };

  const handleSend = () => {
    const num = cleanPhone(currentLead.whatsapp);
    window.open(`https://wa.me/${num}?text=${encodeURIComponent(message)}`, "_blank");
    onLogSent(currentLead.id, message);
    setSentCount((c) => c + 1);
    triggerCoin();
    goNext(true);
  };

  const handleSkip = () => { setSkippedCount((c) => c + 1); goNext(false); };

  return (
    <div style={{ position: "fixed", inset: 0, background: "#f4f5f7", zIndex: 200, display: "flex", flexDirection: "column", animation: "fadeIn 0.2s ease" }}>
      {/* Cabeçalho verde - tema WhatsApp em todas as telas dessa tela. Conteúdo com
          largura máxima e centralizado, senão em tela larga o botão de fechar
          fica "perdido" longe do título. */}
      <div style={{ background: "linear-gradient(135deg, #25d366, #128c4a)", padding: "16px 20px", color: "white", flexShrink: 0 }}>
        <div style={{ maxWidth: 560, margin: "0 auto" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, minWidth: 0 }}>
              <button onClick={onClose} title="Voltar" style={{ width: 36, height: 36, borderRadius: 11, border: "none", background: "rgba(255,255,255,0.2)", color: "white", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                <ArrowLeft size={17} />
              </button>
              <div style={{ minWidth: 0 }}>
                <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 16.5, fontWeight: 800, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>Lista de envio WhatsApp</div>
                <div style={{ fontSize: 11.5, opacity: 0.85 }}>
                  {mode === "list" && `${leadsInList.length} lead${leadsInList.length === 1 ? "" : "s"} na lista`}
                  {mode === "sending" && `Enviando ${idx + 1} de ${validLeads.length}`}
                  {mode === "done" && "Envio concluído"}
                </div>
              </div>
            </div>
            <button onClick={onClose} title="Fechar" style={{ width: 36, height: 36, borderRadius: 11, border: "none", background: "rgba(255,255,255,0.2)", color: "white", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><X size={17} /></button>
          </div>
          {mode === "sending" && (
            <div style={{ height: 6, borderRadius: 4, background: "rgba(255,255,255,0.25)", marginTop: 14, overflow: "hidden" }}>
              <div style={{ height: "100%", borderRadius: 4, width: `${((idx) / validLeads.length) * 100}%`, background: "white", transition: "width 0.4s cubic-bezier(0.4,0,0.2,1)" }} />
            </div>
          )}
        </div>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: 20, position: "relative" }}>
        <div style={{ maxWidth: 560, margin: "0 auto" }}>
          {mode === "list" && (
            <>
              {/* Seletor de abas: fila pendente x histórico de envios já feitos */}
              <div style={{ display: "flex", gap: 4, marginBottom: 16, background: "white", borderRadius: 12, padding: 4, border: "1px solid #eef0f3" }}>
                <button onClick={() => setTab("fila")} style={{ flex: 1, textAlign: "center", padding: "9px 8px", borderRadius: 9, border: "none", fontSize: 12.5, fontWeight: 700, cursor: "pointer", background: tab === "fila" ? "rgba(37,211,102,0.12)" : "transparent", color: tab === "fila" ? "#128c4a" : "#94a3b8" }}>
                  Fila ({leadsInList.length})
                </button>
                <button onClick={() => setTab("historico")} style={{ flex: 1, textAlign: "center", padding: "9px 8px", borderRadius: 9, border: "none", fontSize: 12.5, fontWeight: 700, cursor: "pointer", background: tab === "historico" ? "rgba(37,211,102,0.12)" : "transparent", color: tab === "historico" ? "#128c4a" : "#94a3b8" }}>
                  Histórico ({history.length})
                </button>
              </div>

              {tab === "fila" && (
                leadsInList.length === 0 ? (
                  <div style={{ textAlign: "center", padding: "60px 20px", color: "#94a3b8" }}>
                    <Send size={32} color="#cbd5e1" style={{ marginBottom: 10 }} />
                    <div style={{ fontSize: 14, fontWeight: 600 }}>Fila vazia</div>
                    <div style={{ fontSize: 12.5, marginTop: 4 }}>Toque no ícone de enviar (✈) num lead pra adicionar aqui.</div>
                    <button onClick={onClose} style={{ marginTop: 18, padding: "10px 20px", borderRadius: 12, border: "1.5px solid #eef0f3", background: "white", color: "#64748b", fontSize: 12.5, fontWeight: 700, cursor: "pointer" }}>
                      ← Voltar pros leads
                    </button>
                  </div>
                ) : (
                  <>
                    {withoutPhoneCount > 0 && (
                      <div style={{ background: "rgba(245,158,11,0.1)", border: "1px solid rgba(245,158,11,0.25)", color: "#b45309", padding: "10px 14px", borderRadius: 12, fontSize: 12, fontWeight: 600, marginBottom: 14 }}>
                        ⚠ {withoutPhoneCount} lead{withoutPhoneCount === 1 ? "" : "s"} sem WhatsApp cadastrado - não {withoutPhoneCount === 1 ? "entra" : "entram"} no envio.
                      </div>
                    )}
                    <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 90 }}>
                      {leadsInList.map((lead, i) => (
                        <div key={lead.id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 12px", borderRadius: 14, background: "white", border: `1px solid ${lead.whatsapp ? "#eef0f3" : "rgba(245,158,11,0.3)"}` }}>
                          <OwnerAvatar name={lead.company} size={32} />
                          <div style={{ flex: 1, minWidth: 0 }}>
                            <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                              <div style={{ fontSize: 13.5, fontWeight: 700, color: "#0f172a", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{lead.company}</div>
                              <span style={{ flexShrink: 0, fontSize: 9, fontWeight: 800, color: "#94a3b8", background: "#f1f5f9", padding: "1.5px 6px", borderRadius: 20, letterSpacing: 0.3 }}>NÃO ENVIADO AINDA</span>
                            </div>
                            <div style={{ fontSize: 11, color: lead.whatsapp ? "#94a3b8" : "#b45309" }}>{lead.whatsapp || "sem WhatsApp cadastrado"}</div>
                          </div>
                          {lead.whatsapp && (
                            <button onClick={() => setEditingLead(lead)} title="Editar mensagem" style={{ width: 30, height: 30, borderRadius: 9, border: "none", background: "rgba(109,94,248,0.12)", color: "#6d5ef8", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                              <Pencil size={13} />
                            </button>
                          )}
                          {lead.whatsapp && (
                            <button onClick={() => startSending(i)} title="Abrir na fila de envio, começando por esse" style={{ width: 30, height: 30, borderRadius: 9, border: "none", background: "rgba(37,211,102,0.12)", color: "#128c4a", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                              <Send size={13} />
                            </button>
                          )}
                          <button onClick={() => onRemove(lead.id)} title="Remover da lista" style={{ width: 30, height: 30, borderRadius: 9, border: "none", background: "rgba(239,68,68,0.1)", color: "#dc2626", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                            <X size={13} />
                          </button>
                        </div>
                      ))}
                    </div>
                  </>
                )
              )}

              {tab === "historico" && (
                history.length === 0 ? (
                  <div style={{ textAlign: "center", padding: "60px 20px", color: "#94a3b8" }}>
                    <ClipboardList size={32} color="#cbd5e1" style={{ marginBottom: 10 }} />
                    <div style={{ fontSize: 14, fontWeight: 600 }}>Nenhum envio ainda</div>
                    <div style={{ fontSize: 12.5, marginTop: 4 }}>Toda mensagem enviada pela fila fica registrada aqui.</div>
                  </div>
                ) : (
                  <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 20 }}>
                    {history.map((h) => (
                      <div key={h.id} style={{ display: "flex", gap: 10, padding: "12px 14px", borderRadius: 14, background: "white", border: "1px solid #eef0f3" }}>
                        <div style={{ width: 34, height: 34, borderRadius: "50%", background: "rgba(37,211,102,0.12)", color: "#128c4a", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                          <Check size={15} />
                        </div>
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <div style={{ display: "flex", justifyContent: "space-between", gap: 8, marginBottom: 2 }}>
                            <div style={{ fontSize: 13.5, fontWeight: 700, color: "#0f172a", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{h.company}</div>
                            <div style={{ fontSize: 10.5, color: "#94a3b8", flexShrink: 0 }}>{formatDateFull(h.date)}</div>
                          </div>
                          <div style={{ fontSize: 12, color: "#64748b", lineHeight: 1.4, overflow: "hidden", display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical" }}>{h.message}</div>
                        </div>
                      </div>
                    ))}
                  </div>
                )
              )}
            </>
          )}

          {mode === "sending" && currentLead && (
            <div>
              <div style={{ background: "white", borderRadius: 20, padding: 20, border: "1px solid #eef0f3", boxShadow: "0 10px 30px -12px rgba(20,20,26,0.1)", marginBottom: 16, animation: "popIn 0.25s cubic-bezier(0.34, 1.56, 0.64, 1)" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 14 }}>
                  <OwnerAvatar name={currentLead.company} size={42} />
                  <div>
                    <div style={{ fontSize: 15.5, fontWeight: 800, color: "#0f172a" }}>{currentLead.company}</div>
                    <div style={{ fontSize: 12, color: "#25d366", fontWeight: 600 }}>{currentLead.whatsapp}</div>
                  </div>
                </div>
                <label style={{ ...labelStyle }}><SecIcon icon={Pencil} color="#25d366" />Ajuste de última hora</label>
                <div style={{ fontSize: 10.5, color: "#94a3b8", marginTop: -3, marginBottom: 6 }}>
                  Vale só pra esse envio agora - não altera o script fixo salvo na fila.
                </div>
                <textarea
                  value={message}
                  onChange={(e) => setMessage(e.target.value)}
                  rows={5}
                  style={{ ...inputStyle, resize: "vertical", fontFamily: "inherit", lineHeight: 1.5 }}
                />
              </div>

              <div style={{ display: "flex", gap: 8 }}>
                <button onClick={handleSkip} style={{ flex: 1, padding: "13px 0", borderRadius: 14, border: "1.5px solid #eef0f3", background: "white", color: "#64748b", fontSize: 13.5, fontWeight: 700, cursor: "pointer" }}>
                  Pular
                </button>
                <button onClick={handleSend} style={{ flex: 2, padding: "13px 0", borderRadius: 14, border: "none", background: "linear-gradient(135deg, #25d366, #128c4a)", color: "white", fontSize: 13.5, fontWeight: 800, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", gap: 8, boxShadow: "0 8px 20px -8px rgba(37,211,102,0.6)", position: "relative" }}>
                  <Send size={15} /> Abrir WhatsApp e continuar
                </button>
              </div>
              <div style={{ display: "flex", gap: 12, marginTop: 10, justifyContent: "center" }}>
                {idx > 0 && (
                  <button onClick={() => setIdx((i) => i - 1)} style={{ padding: "8px 0", border: "none", background: "transparent", color: "#94a3b8", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>
                    ← Voltar pro anterior
                  </button>
                )}
                <button onClick={() => setMode("list")} style={{ padding: "8px 0", border: "none", background: "transparent", color: "#94a3b8", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>
                  Sair da fila
                </button>
              </div>
            </div>
          )}

          {mode === "done" && (
            <div style={{ textAlign: "center", padding: "60px 20px", animation: "celebrate 0.6s ease-out" }}>
              <div style={{ fontSize: 46, marginBottom: 12 }}>🎉</div>
              <div style={{ fontSize: 18, fontWeight: 800, color: "#0f172a", marginBottom: 6 }}>Envio concluído!</div>
              <div style={{ fontSize: 13, color: "#64748b", marginBottom: 24 }}>
                {sentCount} mensage{sentCount === 1 ? "m aberta" : "ns abertas"} no WhatsApp{skippedCount > 0 ? `, ${skippedCount} pulada${skippedCount === 1 ? "" : "s"}` : ""}.
              </div>
              <button onClick={onClose} style={{ padding: "12px 28px", borderRadius: 14, border: "none", background: "linear-gradient(135deg, #25d366, #128c4a)", color: "white", fontSize: 13.5, fontWeight: 800, cursor: "pointer" }}>
                Fechar
              </button>
            </div>
          )}
        </div>

        {/* Moedinha dourada que sobe e some a cada envio - reforço positivo rápido */}
        {showCoin && (
          <div style={{ position: "fixed", left: "50%", bottom: "30%", transform: "translateX(-50%)", fontSize: 28, pointerEvents: "none", animation: "coinFloat 0.9s ease-out forwards", zIndex: 210 }}>
            🪙
          </div>
        )}

        {editingLead && (
          <ScriptPickerModal
            lead={editingLead}
            initialMessage={editingLead.waMessage || buildWaListDefaultMessage(editingLead)}
            onClose={() => setEditingLead(null)}
            onSelect={(msg) => { onEditMessage(editingLead.id, msg); setEditingLead(null); }}
          />
        )}
      </div>

      {mode === "list" && tab === "fila" && leadsInList.length > 0 && (
        <div style={{ padding: 16, borderTop: "1px solid #eef0f3", background: "white", display: "flex", gap: 8, flexShrink: 0 }}>
          <div style={{ maxWidth: 560, margin: "0 auto", width: "100%", display: "flex", gap: 8 }}>
            <button onClick={onClear} style={{ padding: "13px 18px", borderRadius: 14, border: "1.5px solid #eef0f3", background: "white", color: "#64748b", fontSize: 13, fontWeight: 700, cursor: "pointer" }}>
              Limpar lista
            </button>
            <button
              onClick={() => startSending(0)}
              disabled={validLeads.length === 0}
              style={{ flex: 1, padding: "13px 0", borderRadius: 14, border: "none", background: validLeads.length > 0 ? "linear-gradient(135deg, #25d366, #128c4a)" : "rgba(148,163,184,0.3)", color: "white", fontSize: 13.5, fontWeight: 800, cursor: validLeads.length > 0 ? "pointer" : "not-allowed", display: "flex", alignItems: "center", justifyContent: "center", gap: 8, boxShadow: validLeads.length > 0 ? "0 8px 20px -8px rgba(37,211,102,0.6)" : "none" }}
            >
              <Send size={15} /> Iniciar envio ({validLeads.length})
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

// ════════════════════════════════════════════════════════════════════════
// DESATENDIDO CARD (tela dedicada)
// ════════════════════════════════════════════════════════════════════════

const DesatendidoCard = ({ lead, onOpen, onQuickContact, onToggleWeekDone, onToggleSuper }) => {
  const cfg = TEMP_CONFIG[lead.temperature];
  const stageColor = STAGE_COLORS[lead.stage] || "#64748b";
  const ownerColor = RESPONSIBLE_COLORS[lead.owner] || "#64748b";
  const phaseCfg = PHASE_BY_KEY[lead.phase] || PHASE_BY_KEY.none;

  return (
    <div style={{
      position: "relative", padding: "18px 20px 18px 22px", borderRadius: 18,
      background: lead.weekDone ? "rgba(240, 253, 244, 0.7)" : "rgba(255, 255, 255, 0.68)",
      backdropFilter: "blur(18px) saturate(150%)", WebkitBackdropFilter: "blur(18px) saturate(150%)",
      border: "1px solid rgba(255, 255, 255, 0.85)",
      borderLeft: `4px solid ${ownerColor}`,
      boxShadow: "0 4px 20px -10px rgba(76, 29, 149, 0.15)",
      marginBottom: 14, transition: "all 0.2s ease",
    }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10, marginBottom: 10, cursor: "pointer" }} onClick={() => onOpen(lead)}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <OwnerAvatar name={lead.owner} size={38} />
          <div>
            <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 19, fontWeight: 500, color: "#0f172a" }}>{lead.company}</div>
            <div style={{ fontSize: 12, color: "#94a3b8", fontWeight: 500 }}>SDR: {lead.owner}</div>
          </div>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 6, flexShrink: 0 }}>
          <button
            onClick={(e) => { e.stopPropagation(); onToggleSuper(lead.id); }}
            title={lead.superAttention ? "Remover marcação de Super lead" : "Marcar como Super lead"}
            style={{ border: "none", background: "transparent", cursor: "pointer", padding: 2, opacity: lead.superAttention ? 1 : 0.3 }}
          >
            <StarImgIcon size={17} />
          </button>
          <span style={{ display: "inline-flex", alignItems: "center", gap: 5, fontSize: 10.5, fontWeight: 700, letterSpacing: 0.4, textTransform: "uppercase", color: "#dc2626", background: "rgba(239, 68, 68, 0.12)", padding: "5px 10px", borderRadius: 8 }}>
            <AlertCircle size={11} /> Negociação antiga
          </span>
          <ChevronRight size={16} style={{ color: "#cbd5e1" }} />
        </div>
      </div>

      <div style={{ display: "flex", gap: 6, marginBottom: 12, flexWrap: "wrap" }}>
        <div style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "4px 9px", borderRadius: 8, background: cfg.bg, color: cfg.color, fontSize: 11, fontWeight: 700 }}>
          <TempDot temp={lead.temperature} size={6} />{cfg.label}
        </div>
        <div style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "4px 9px", borderRadius: 8, background: stageColor + "15", color: stageColor, fontSize: 11, fontWeight: 700 }}>{lead.stage}</div>
        <div style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "4px 9px", borderRadius: 8, background: phaseCfg.color + "15", color: phaseCfg.color, fontSize: 11, fontWeight: 700 }}>{phaseCfg.label}</div>
      </div>

      <div style={{ display: "flex", gap: 8, marginBottom: 14, flexWrap: "wrap" }}>
        {lead.feedback && (
          <div style={{ flex: 1, minWidth: 180, display: "flex", alignItems: "center", gap: 8, fontSize: 12.5, color: "#7f1d1d", background: "rgba(254, 226, 226, 0.55)", padding: "9px 12px", borderRadius: 10 }}>
            <MessageCircle size={13} style={{ flexShrink: 0 }} />{lead.feedback}
          </div>
        )}
        <div style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 12, fontWeight: 600, color: "#15803d", background: "rgba(220, 252, 231, 0.7)", padding: "9px 12px", borderRadius: 10, whiteSpace: "nowrap" }}>
          <CalendarIcon size={13} /> Abordar essa semana
        </div>
      </div>

      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        <button
          onClick={() => onToggleWeekDone(lead.id)}
          style={{
            flex: "1 1 120px", display: "flex", alignItems: "center", justifyContent: "center", gap: 7,
            padding: "10px 16px", borderRadius: 12, border: "none", cursor: "pointer",
            fontSize: 13, fontWeight: 700,
            background: lead.weekDone ? "linear-gradient(135deg, #22c55e, #16a34a)" : "rgba(241, 245, 249, 0.8)",
            color: lead.weekDone ? "white" : "#64748b",
            boxShadow: lead.weekDone ? "0 6px 16px -6px rgba(22, 163, 74, 0.5)" : "none",
            transition: "all 0.2s ease",
          }}
        >
          <CheckCircle2 size={15} /> {lead.weekDone ? "Feito" : "Marcar como feito"}
        </button>
        <ContactPill icon={MessageCircle} color="#25d366" label="WhatsApp" hasData={!!lead.whatsapp} isMarked={lead.hasWhatsapp} onClick={() => (lead.whatsapp ? onQuickContact("whatsapp", lead) : onOpen(lead))} />
        <ContactPill icon={Mail} color="#3b82f6" label="Email" hasData={!!lead.email} isMarked={lead.hasEmail} onClick={() => (lead.email ? onQuickContact("email", lead) : onOpen(lead))} />
        <ContactPill icon={Phone} color="#8b5cf6" label="Ligar" hasData={!!lead.phone} isMarked={lead.hasPhone} onClick={() => (lead.phone ? onQuickContact("phone", lead) : onOpen(lead))} />
      </div>
    </div>
  );
};

// Card compacto (quadrado pequeno) usado na lista "Abordar essa semana" - feita a partir da tag manual
const WeekSquareCard = ({ lead, onOpen, onDone, onToggleSuper }) => {
  const cfg = TEMP_CONFIG[lead.temperature];
  const tagLabel = lead.weekTag === "hoje" ? "Hoje" : "Esta semana";
  const tagColor = lead.weekTag === "hoje" ? "#dc2626" : "#059669";
  return (
    <div style={{ borderRadius: 16, padding: "12px 13px", background: "rgba(255,255,255,0.75)", backdropFilter: "blur(14px)", border: "1px solid rgba(255,255,255,0.85)", boxShadow: "0 6px 18px -8px rgba(15,23,42,0.1)", display: "flex", flexDirection: "column", gap: 8 }}>
      <div onClick={() => onOpen(lead)} style={{ cursor: "pointer" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 6 }}>
          <span style={{ fontSize: 9.5, fontWeight: 800, letterSpacing: 0.4, textTransform: "uppercase", color: tagColor, background: tagColor + "15", padding: "2px 7px", borderRadius: 6 }}>{tagLabel}</span>
          <button
            onClick={(e) => { e.stopPropagation(); onToggleSuper(lead.id); }}
            title={lead.superAttention ? "Remover marcação de Super lead" : "Marcar como Super lead"}
            style={{ border: "none", background: "transparent", cursor: "pointer", padding: 0, opacity: lead.superAttention ? 1 : 0.3 }}
          >
            <StarImgIcon size={13} />
          </button>
        </div>
        {lead.feedback && (
          <div style={{ display: "flex", alignItems: "flex-start", gap: 4, fontSize: 10, color: "#64748b", background: "#f7f8fa", borderRadius: 6, padding: "4px 6px", marginBottom: 5, lineHeight: 1.3 }}>
            <MessageCircle size={9} style={{ flexShrink: 0, marginTop: 1.5, opacity: 0.7 }} />
            <span style={{ overflow: "hidden", textOverflow: "ellipsis", display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical" }}>{lead.feedback}</span>
          </div>
        )}
        <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 14.5, fontWeight: 500, color: "#0f172a", lineHeight: 1.2, marginBottom: 4, overflow: "hidden", textOverflow: "ellipsis", display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical" }}>{lead.company}</div>
        <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
          <OwnerAvatar name={lead.owner} size={16} />
          <span style={{ fontSize: 10.5, color: "#94a3b8" }}>{lead.owner}</span>
          <span style={{ width: 6, height: 6, borderRadius: "50%", background: cfg.color, marginLeft: "auto" }} title={cfg.label} />
        </div>
      </div>
      <button
        onClick={(e) => { e.stopPropagation(); onDone(); }}
        title="Marcar este lead como abordado"
        style={{ padding: "8px 0", borderRadius: 9, cursor: "pointer", fontSize: 11.5, fontWeight: 700, background: "white", color: "#059669", border: "1.5px solid #059669", display: "flex", alignItems: "center", justifyContent: "center", gap: 5, transition: "all 0.15s ease" }}
      >
        <CheckCircle2 size={13} /> Marcar como feito
      </button>
    </div>
  );
};

// ════════════════════════════════════════════════════════════════════════
// LEAD DETAIL MODAL
// ════════════════════════════════════════════════════════════════════════

const LeadDetail = ({ lead, onClose, onSave, onDelete, onQuickContact, sdrs, onSetWeekTag, onToggleSuper }) => {
  const [draft, setDraft] = useState(lead);
  const [newNote, setNewNote] = useState("");
  const [confirmDelete, setConfirmDelete] = useState(false);

  useEffect(() => { setDraft(lead); setNewNote(""); setConfirmDelete(false); }, [lead]);
  if (!lead) return null;

  const update = (patch) => setDraft((d) => ({ ...d, ...patch }));
  const addNote = () => {
    if (!newNote.trim()) return;
    const note = { id: "n_" + Date.now(), date: new Date().toISOString(), text: newNote.trim() };
    const updated = { ...draft, notes: [note, ...(draft.notes || [])], lastContact: new Date().toISOString() };
    setDraft(updated); setNewNote(""); onSave(updated);
  };
  const handleSave = () => { onSave(draft); onClose(); };
  // Fechar (X ou clicar fora) descartava qualquer edição sem avisar. Agora só fecha direto
  // se não há mudanças; havendo, confirma antes de perder o que foi digitado.
  const isDirty = JSON.stringify(draft) !== JSON.stringify(lead);
  const handleClose = () => {
    if (isDirty && !window.confirm("Você tem alterações não salvas neste lead. Sair sem salvar?")) return;
    onClose();
  };

  return (
    <div onClick={handleClose} style={{ position: "fixed", inset: 0, background: "rgba(30, 20, 60, 0.4)", backdropFilter: "blur(8px)", WebkitBackdropFilter: "blur(8px)", zIndex: 100, display: "flex", alignItems: "flex-start", justifyContent: "center", padding: "5vh 20px", overflowY: "auto", animation: "fadeIn 0.22s ease" }}>
      <div onClick={(e) => e.stopPropagation()} style={{ width: "100%", maxWidth: 660, background: "rgba(255, 255, 255, 0.9)", backdropFilter: "blur(40px) saturate(160%)", WebkitBackdropFilter: "blur(40px) saturate(160%)", borderRadius: 24, border: "1px solid rgba(255, 255, 255, 0.9)", boxShadow: "0 30px 90px -20px rgba(76, 29, 149, 0.35)", overflow: "hidden", animation: "slideUp 0.3s cubic-bezier(0.4, 0, 0.2, 1)" }}>
        <div style={{ padding: "24px 28px 18px", borderBottom: "1px solid rgba(148, 163, 184, 0.15)", position: "relative", overflow: "hidden" }}>
          {/* Brilho de fundo que muda de cor com a temperatura do lead - dá vida ao topo do painel */}
          <div style={{
            position: "absolute", top: -60, right: -60, width: 220, height: 220, borderRadius: "50%",
            background: `radial-gradient(circle, ${TEMP_CONFIG[draft.temperature]?.color || "#6d5ef8"}30, transparent 70%)`,
            filter: "blur(10px)", pointerEvents: "none", animation: "glowPulse 3.5s ease-in-out infinite", transition: "background 0.4s ease",
          }} />
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 16, position: "relative" }}>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: 0.8, textTransform: "uppercase", color: "#94a3b8", marginBottom: 4 }}>Empresa</div>
              <input value={draft.company} onChange={(e) => update({ company: e.target.value })} style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 26, fontWeight: 500, color: "#0f172a", border: "none", background: "transparent", outline: "none", width: "100%", letterSpacing: -0.5, padding: 0, marginBottom: 6 }} />
              <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 7 }}>
                  <OwnerAvatar name={draft.owner} size={22} />
                  <select value={draft.owner} onChange={(e) => update({ owner: e.target.value })} style={{ fontSize: 13, color: "#475569", border: "none", background: "transparent", outline: "none", fontWeight: 500, cursor: "pointer" }}>
                    {sdrs.map((s) => <option key={s.name}>{s.name}</option>)}
                  </select>
                </div>
                <span style={{ color: "#cbd5e1" }}>·</span>
                <div onClick={() => update({ status: draft.status === "Atendido" ? "Desatendido" : "Atendido" })} title="Clique para alternar" style={{ cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 5, fontSize: 11, fontWeight: 700, padding: "3px 9px", borderRadius: 7, color: draft.status === "Atendido" ? "#16a34a" : "#dc2626", background: draft.status === "Atendido" ? "rgba(34, 197, 94, 0.12)" : "rgba(239, 68, 68, 0.12)", border: `1px solid ${draft.status === "Atendido" ? "rgba(34, 197, 94, 0.25)" : "rgba(239, 68, 68, 0.25)"}` }}>
                  {draft.status === "Atendido" ? <CheckCircle2 size={12} /> : <XCircle size={12} />}{draft.status === "Atendido" ? "Em atendimento" : "Negociação antiga"}
                </div>
                <button
                  onClick={() => { const updated = { ...draft, superAttention: !draft.superAttention }; setDraft(updated); onToggleSuper(draft.id); }}
                  title="Marcar como lead grande / super atenção"
                  style={{ cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 5, fontSize: 11, fontWeight: 700, padding: "3px 9px", borderRadius: 7, color: draft.superAttention ? "#b45309" : "#94a3b8", background: draft.superAttention ? "rgba(245, 158, 11, 0.15)" : "rgba(148,163,184,0.12)", border: `1px solid ${draft.superAttention ? "rgba(245, 158, 11, 0.35)" : "rgba(148,163,184,0.25)"}` }}
                >
                  ⭐ {draft.superAttention ? "Super lead" : "Marcar super lead"}
                </button>
              </div>
            </div>
            <button onClick={handleClose} style={{ width: 36, height: 36, borderRadius: 12, border: "1px solid rgba(148, 163, 184, 0.25)", background: "rgba(255,255,255,0.6)", color: "#64748b", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><X size={18} /></button>
          </div>

          <div style={{ display: "flex", gap: 8, marginTop: 14, alignItems: "center", flexWrap: "wrap" }}>
            <span style={{ fontSize: 10.5, fontWeight: 700, color: "#94a3b8", textTransform: "uppercase", letterSpacing: 0.5 }}>Lista da semana</span>
            {[{ key: "hoje", label: "Hoje" }, { key: "semana", label: "Esta semana" }].map((t) => {
              const active = draft.weekTag === t.key;
              return (
                <button
                  key={t.key}
                  onClick={() => { const tag = active ? null : t.key; const updated = { ...draft, weekTag: tag, weekDone: tag ? false : draft.weekDone }; setDraft(updated); onSetWeekTag(draft.id, tag); }}
                  style={{ padding: "5px 11px", borderRadius: 8, border: `1px solid ${active ? "#059669" : "rgba(148,163,184,0.3)"}`, background: active ? "rgba(16,185,129,0.14)" : "white", color: active ? "#059669" : "#64748b", fontSize: 11.5, fontWeight: 700, cursor: "pointer" }}
                >
                  {active ? "✓ " : ""}{t.label}
                </button>
              );
            })}
            {draft.weekTag && (
              <button onClick={() => { const updated = { ...draft, weekTag: null }; setDraft(updated); onSetWeekTag(draft.id, null); }} style={{ padding: "5px 9px", borderRadius: 8, border: "none", background: "transparent", color: "#94a3b8", fontSize: 11, fontWeight: 600, cursor: "pointer" }}>
                remover
              </button>
            )}
          </div>

          <div style={{ display: "flex", gap: 8, marginTop: 18, position: "relative" }}>
            <button
              onClick={() => onQuickContact("whatsapp", draft)} disabled={!draft.whatsapp}
              onMouseEnter={(e) => { if (draft.whatsapp) e.currentTarget.style.transform = "translateY(-2px) scale(1.02)"; }}
              onMouseLeave={(e) => { e.currentTarget.style.transform = "translateY(0) scale(1)"; }}
              style={{ flex: 1, padding: "10px 14px", borderRadius: 12, border: `1px solid ${draft.whatsapp ? "rgba(37, 211, 102, 0.3)" : "rgba(148,163,184,0.2)"}`, background: draft.whatsapp ? "rgba(37, 211, 102, 0.1)" : "rgba(241,245,249,0.5)", color: draft.whatsapp ? "#16a34a" : "#94a3b8", cursor: draft.whatsapp ? "pointer" : "not-allowed", display: "flex", alignItems: "center", justifyContent: "center", gap: 8, fontSize: 13, fontWeight: 600, transition: "transform 0.15s ease, box-shadow 0.15s ease", boxShadow: draft.whatsapp ? "0 4px 14px -8px rgba(37,211,102,0.5)" : "none" }}
            ><MessageCircle size={15} /> WhatsApp</button>
            <button
              onClick={() => onQuickContact("email", draft)} disabled={!draft.email}
              onMouseEnter={(e) => { if (draft.email) e.currentTarget.style.transform = "translateY(-2px) scale(1.02)"; }}
              onMouseLeave={(e) => { e.currentTarget.style.transform = "translateY(0) scale(1)"; }}
              style={{ flex: 1, padding: "10px 14px", borderRadius: 12, border: `1px solid ${draft.email ? "rgba(59, 130, 246, 0.3)" : "rgba(148,163,184,0.2)"}`, background: draft.email ? "rgba(59, 130, 246, 0.1)" : "rgba(241,245,249,0.5)", color: draft.email ? "#2563eb" : "#94a3b8", cursor: draft.email ? "pointer" : "not-allowed", display: "flex", alignItems: "center", justifyContent: "center", gap: 8, fontSize: 13, fontWeight: 600, transition: "transform 0.15s ease, box-shadow 0.15s ease", boxShadow: draft.email ? "0 4px 14px -8px rgba(59,130,246,0.5)" : "none" }}
            ><Mail size={15} /> Email</button>
            <button
              onClick={() => onQuickContact("phone", draft)} disabled={!draft.phone}
              onMouseEnter={(e) => { if (draft.phone) e.currentTarget.style.transform = "translateY(-2px) scale(1.02)"; }}
              onMouseLeave={(e) => { e.currentTarget.style.transform = "translateY(0) scale(1)"; }}
              style={{ flex: 1, padding: "10px 14px", borderRadius: 12, border: `1px solid ${draft.phone ? "rgba(139, 92, 246, 0.3)" : "rgba(148,163,184,0.2)"}`, background: draft.phone ? "rgba(139, 92, 246, 0.1)" : "rgba(241,245,249,0.5)", color: draft.phone ? "#7c3aed" : "#94a3b8", cursor: draft.phone ? "pointer" : "not-allowed", display: "flex", alignItems: "center", justifyContent: "center", gap: 8, fontSize: 13, fontWeight: 600, transition: "transform 0.15s ease, box-shadow 0.15s ease", boxShadow: draft.phone ? "0 4px 14px -8px rgba(139,92,246,0.5)" : "none" }}
            ><Phone size={15} /> Ligar</button>
          </div>
        </div>

        <div style={{ padding: "20px 28px", maxHeight: "55vh", overflowY: "auto", background: "linear-gradient(180deg, rgba(109,94,248,0.025), transparent 200px)" }}>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 18 }}>
            <div>
              <label style={labelStyle}><SecIcon icon={Flame} color="#f0431f" />Temperatura</label>
              <div style={{ display: "flex", gap: 6 }}>
                {Object.entries(TEMP_CONFIG).map(([key, cfg]) => {
                  const active = draft.temperature === key;
                  return (
                    <button
                      key={key}
                      onClick={() => update({ temperature: key })}
                      style={{
                        flex: 1, padding: "8px 6px", borderRadius: 10, border: `1px solid ${active ? cfg.color : "rgba(148,163,184,0.25)"}`,
                        background: active ? cfg.bg : "rgba(255,255,255,0.6)", color: active ? cfg.color : "#64748b", cursor: "pointer",
                        fontSize: 12, fontWeight: active ? 700 : 500, display: "flex", alignItems: "center", justifyContent: "center", gap: 5,
                        boxShadow: active ? `0 0 0 3px ${cfg.ring}` : "none",
                        transform: active ? "scale(1.03)" : "scale(1)",
                        animation: active ? "popIn 0.25s cubic-bezier(0.34, 1.56, 0.64, 1)" : "none",
                        transition: "transform 0.15s ease, box-shadow 0.2s ease",
                      }}
                    >
                      <TempDot temp={key} size={8} />{cfg.label}
                    </button>
                  );
                })}
              </div>
            </div>
            <div>
              <label style={{ ...labelStyle, marginBottom: 2 }}><SecIcon icon={Target} color="#6d5ef8" />Estágio</label><span style={hintStyle}>Etapa do processo comercial</span>
              <select
                value={draft.stage}
                onChange={(e) => {
                  const stage = e.target.value;
                  const patch = { stage };
                  if (stage === "Conquistado" && !draft.wonDate) patch.wonDate = new Date().toISOString();
                  update(patch);
                }}
                style={selectStyle}
              >
                {STAGE_OPTIONS.map((s) => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>
          </div>

          {draft.stage !== "Perdida" && (() => {
            const HAPPY_PATH = STAGE_OPTIONS.filter((s) => s !== "Perdida");
            const currentIdx = HAPPY_PATH.indexOf(draft.stage);
            const pct = HAPPY_PATH.length > 1 ? (currentIdx / (HAPPY_PATH.length - 1)) * 100 : 0;
            return (
              <div style={{ marginBottom: 18 }}>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
                  <span style={{ fontSize: 10.5, fontWeight: 700, color: "#94a3b8", textTransform: "uppercase", letterSpacing: 0.5 }}>Progresso no funil</span>
                  <span style={{ fontSize: 10.5, fontWeight: 700, color: "#6d5ef8" }}>{currentIdx + 1} / {HAPPY_PATH.length}</span>
                </div>
                <div style={{ height: 8, borderRadius: 6, background: "rgba(148,163,184,0.15)", overflow: "hidden", position: "relative" }}>
                  <div style={{
                    height: "100%", borderRadius: 6, width: `${pct}%`,
                    background: draft.stage === "Conquistado" ? "linear-gradient(90deg, #22c55e, #16a34a)" : "linear-gradient(90deg, #a3e635, #6d5ef8)",
                    transition: "width 0.5s cubic-bezier(0.4, 0, 0.2, 1)", animation: "stageBarFill 0.6s ease-out",
                    boxShadow: "0 0 10px rgba(109,94,248,0.4)",
                  }} />
                </div>
              </div>
            );
          })()}
          {draft.stage === "Perdida" && (
            <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 18, fontSize: 11.5, fontWeight: 700, color: "#dc2626" }}>
              <XCircle size={13} /> Negociação perdida
            </div>
          )}

          {draft.stage === "Conquistado" && (
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 18, padding: "12px 14px", borderRadius: 12, background: "rgba(16,185,129,0.06)", border: "1px solid rgba(16,185,129,0.2)" }}>
              <div>
                <label style={{ ...labelStyle, marginBottom: 4 }}>Data de fechamento</label>
                <input
                  type="date"
                  value={draft.wonDate ? draft.wonDate.slice(0, 10) : ""}
                  onChange={(e) => update({ wonDate: e.target.value ? new Date(e.target.value).toISOString() : null })}
                  style={inputStyle}
                />
              </div>
              <div>
                <label style={{ ...labelStyle, marginBottom: 4 }}>Valor do contrato (R$)</label>
                <input
                  type="number"
                  min={0}
                  placeholder={parseFee(draft.feedback) > 0 ? String(parseFee(draft.feedback)) : "0"}
                  value={draft.dealValue ?? ""}
                  onChange={(e) => update({ dealValue: e.target.value ? parseFloat(e.target.value) : null })}
                  style={inputStyle}
                />
              </div>
              <div style={{ gridColumn: "1 / -1" }}>
                <label style={{ ...labelStyle, marginBottom: 4 }}>Modelo de pagamento</label>
                <div style={{ display: "flex", gap: 6 }}>
                  {[
                    { key: "unico", label: "Pagamento único" },
                    { key: "mensal", label: "Fee mensal" },
                  ].map((t) => {
                    const active = (draft.dealType || "unico") === t.key;
                    return (
                      <button
                        key={t.key}
                        onClick={() => update({ dealType: t.key })}
                        style={{
                          flex: 1, padding: "8px 10px", borderRadius: 9,
                          border: `1.5px solid ${active ? "#1fa971" : "rgba(148,163,184,0.3)"}`,
                          background: active ? "rgba(31,169,113,0.12)" : "white",
                          color: active ? "#1fa971" : "#64748b",
                          fontSize: 12.5, fontWeight: active ? 700 : 500, cursor: "pointer",
                        }}
                      >
                        {t.label}
                      </button>
                    );
                  })}
                </div>
              </div>
              <div style={{ gridColumn: "1 / -1" }}>
                <label style={{ ...labelStyle, marginBottom: 4 }}>Duração do contrato</label>
                <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                  {CONTRACT_PERIOD_OPTIONS.map((p) => {
                    const active = (draft.contractPeriod || "mensal") === p.key;
                    return (
                      <button
                        key={p.key}
                        onClick={() => update({ contractPeriod: p.key })}
                        style={{
                          flex: 1, minWidth: 90, padding: "8px 10px", borderRadius: 9,
                          border: `1.5px solid ${active ? "#6d5ef8" : "rgba(148,163,184,0.3)"}`,
                          background: active ? "rgba(109,94,248,0.1)" : "white",
                          color: active ? "#6d5ef8" : "#64748b",
                          fontSize: 12.5, fontWeight: active ? 700 : 500, cursor: "pointer",
                        }}
                      >
                        {p.label}
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>
          )}

          <div style={{ marginBottom: 18 }}>
            <label style={{ ...labelStyle, marginBottom: 2 }}><SecIcon icon={Users} color="#ec4899" />Fase da conversa</label>
            <span style={hintStyle}>Em que ponto está a comunicação (não muda o estágio comercial acima)</span>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              {CONVERSATION_PHASES.map((p) => {
                const active = (draft.phase || "none") === p.key;
                return (
                  <button key={p.key} onClick={() => update({ phase: p.key })} style={{ flex: 1, minWidth: 130, padding: "8px 10px", borderRadius: 10, border: `1px solid ${active ? p.color : "rgba(148,163,184,0.25)"}`, background: active ? p.color + "15" : "rgba(255,255,255,0.6)", color: active ? p.color : "#64748b", cursor: "pointer", fontSize: 12, fontWeight: active ? 700 : 500, display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
                    <span style={{ width: 6, height: 6, borderRadius: "50%", background: p.color }} />{p.label}
                  </button>
                );
              })}
            </div>
          </div>

          <div style={{ marginBottom: 12 }}>
            <label style={labelStyle}>Contato (pessoa)</label>
            <input value={draft.contactName || ""} onChange={(e) => update({ contactName: e.target.value })} placeholder="Nome do contato na empresa" style={inputStyle} />
          </div>

          <div style={{ marginBottom: 18 }}>
            <label style={labelStyle}>Origem do lead</label>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              {ORIGIN_OPTIONS.map((o) => {
                const active = draft.origin === o.key;
                return (
                  <button
                    key={o.key}
                    onClick={() => update({ origin: active ? null : o.key })}
                    title={active ? "Clique para remover" : `Marcar origem: ${o.label}`}
                    style={{
                      display: "inline-flex", alignItems: "center", gap: 5, padding: "6px 11px", borderRadius: 9,
                      border: `1.5px solid ${active ? o.color : "rgba(148,163,184,0.3)"}`,
                      background: active ? o.color + "15" : "white",
                      color: active ? o.color : "#64748b",
                      fontSize: 12, fontWeight: active ? 700 : 500, cursor: "pointer",
                    }}
                  >
                    <o.icon size={13} /> {o.label}
                  </button>
                );
              })}
            </div>
            {draft.origin === "outro" && (
              <input
                value={draft.originOther || ""}
                onChange={(e) => update({ originOther: e.target.value })}
                placeholder="Qual canal? (ex: TikTok, panfleto, parceiro...)"
                style={{ ...inputStyle, marginTop: 8 }}
              />
            )}
          </div>

          <div style={{ marginBottom: 8 }}>
            <label style={{ ...labelStyle, marginBottom: 2 }}>Canais de contato</label>
            <span style={hintStyle}>Marque "Disponível" se você sabe que o lead tem o canal, mesmo antes de ter o número/email em mãos.</span>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 18 }}>
            <div>
              <ChannelLabel label="Email" checked={!!(draft.hasEmail || draft.email)} disabled={!!draft.email} onToggle={() => update({ hasEmail: !draft.hasEmail })} />
              <div style={{ display: "flex", gap: 6 }}>
                <input value={draft.email || ""} onChange={(e) => update({ email: e.target.value, hasEmail: e.target.value ? true : draft.hasEmail })} placeholder="email@empresa.com" style={{ ...inputStyle, flex: 1 }} />
                <CopyButton value={draft.email} />
              </div>
            </div>
            <div>
              <ChannelLabel label="Telefone" checked={!!(draft.hasPhone || draft.phone)} disabled={!!draft.phone} onToggle={() => update({ hasPhone: !draft.hasPhone })} />
              <div style={{ display: "flex", gap: 6 }}>
                <input value={draft.phone || ""} onChange={(e) => update({ phone: e.target.value, hasPhone: e.target.value ? true : draft.hasPhone })} placeholder="+55 11 9..." style={{ ...inputStyle, flex: 1 }} />
                <CopyButton value={draft.phone} />
              </div>
            </div>
            <div style={{ gridColumn: "1 / -1" }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                <ChannelLabel label="WhatsApp" checked={!!(draft.hasWhatsapp || draft.whatsapp)} disabled={!!draft.whatsapp} onToggle={() => update({ hasWhatsapp: !draft.hasWhatsapp })} />
                {!draft.whatsapp && draft.phone && <button onClick={() => update({ whatsapp: draft.phone, hasWhatsapp: true })} style={{ marginBottom: 6, fontSize: 11, color: "#16a34a", border: "none", background: "transparent", cursor: "pointer", fontWeight: 700 }}>usar o mesmo número do telefone</button>}
              </div>
              <div style={{ display: "flex", gap: 6 }}>
                <input value={draft.whatsapp || ""} onChange={(e) => update({ whatsapp: e.target.value, hasWhatsapp: e.target.value ? true : draft.hasWhatsapp })} placeholder="+55 11 9... (com DDD e código do país)" style={{ ...inputStyle, flex: 1 }} />
                <CopyButton value={draft.whatsapp} />
              </div>
            </div>
          </div>

          <div style={{ marginBottom: 18 }}>
            <label style={labelStyle}><SecIcon icon={MessageCircle} color="#f59e0b" />Resumo (aparece no card da lista)</label>
            <div style={{ fontSize: 11, color: "#94a3b8", marginBottom: 6, marginTop: -4 }}>
              Um resumo curto pra bater o olho na lista. Pra registrar cada conversa com data, use o histórico mais abaixo.
            </div>
            <textarea value={draft.feedback || ""} onChange={(e) => update({ feedback: e.target.value })} placeholder="Ex: esperando aprovação do orçamento..." style={{ ...inputStyle, minHeight: 60, resize: "vertical", fontFamily: "inherit" }} />
          </div>

          <div style={{ marginBottom: 18 }}>
            <label style={labelStyle}><SecIcon icon={Clock} color="#0ea5e9" />Último contato</label>
            <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
              <input
                type="date"
                value={draft.lastContact ? draft.lastContact.slice(0, 10) : ""}
                onChange={(e) => update({ lastContact: e.target.value ? new Date(e.target.value).toISOString() : null })}
                style={{ ...inputStyle, flex: 1 }}
              />
              <button
                onClick={() => update({ lastContact: new Date().toISOString() })}
                title="Marcar como contatado hoje"
                style={{ padding: "9px 14px", borderRadius: 10, border: "1.5px solid rgba(31,169,113,0.35)", background: "rgba(31,169,113,0.08)", color: "#1fa971", fontSize: 12.5, fontWeight: 700, cursor: "pointer", whiteSpace: "nowrap", display: "flex", alignItems: "center", gap: 6 }}
              >
                <CheckCircle2 size={14} /> Marcar hoje
              </button>
              {draft.lastContact && (
                <button onClick={() => update({ lastContact: null })} title="Remover data" style={{ border: "none", background: "rgba(148,163,184,0.15)", color: "#64748b", width: 32, height: 32, borderRadius: 9, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                  <X size={13} />
                </button>
              )}
            </div>
          </div>

          <div style={{ marginBottom: 18 }}>
            <label style={labelStyle}><SecIcon icon={CalendarIcon} color="#22c55e" />Próxima ação</label>
            <div style={{ display: "grid", gridTemplateColumns: "140px 1fr", gap: 8 }}>
              <div>
                <span style={{ fontSize: 10, color: "#94a3b8", marginBottom: 3, display: "block" }}>Quando</span>
                <input type="date" value={draft.nextAction?.date ? draft.nextAction.date.slice(0, 10) : ""} onChange={(e) => { const date = e.target.value ? new Date(e.target.value).toISOString() : null; update({ nextAction: date ? { date, description: draft.nextAction?.description || "" } : null }); }} style={inputStyle} />
              </div>
              <div>
                <span style={{ fontSize: 10, color: "#94a3b8", marginBottom: 3, display: "block" }}>O que fazer</span>
                <input value={draft.nextAction?.description || ""} onChange={(e) => update({ nextAction: { date: draft.nextAction?.date || new Date().toISOString(), description: e.target.value } })} placeholder="Ex: ligar para confirmar reunião" style={inputStyle} />
              </div>
            </div>
          </div>

          <div style={{ marginBottom: 18, display: "flex", alignItems: "center", justifyContent: "space-between", padding: "12px 14px", borderRadius: 12, background: draft.weekDone ? "rgba(220, 252, 231, 0.6)" : "rgba(241, 245, 249, 0.6)" }}>
            <div>
              <div style={{ fontSize: 12.5, fontWeight: 700, color: draft.weekDone ? "#16a34a" : "#64748b" }}>Ação desta semana</div>
              <div style={{ fontSize: 11, color: "#94a3b8" }}>Marcado como feito conta na meta semanal do time</div>
            </div>
            <button onClick={() => update({ weekDone: !draft.weekDone })} style={{ display: "flex", alignItems: "center", gap: 6, padding: "8px 14px", borderRadius: 10, border: "none", cursor: "pointer", fontWeight: 700, fontSize: 12, background: draft.weekDone ? "linear-gradient(135deg, #22c55e, #16a34a)" : "rgba(203, 213, 225, 0.5)", color: draft.weekDone ? "white" : "#64748b" }}>
              <CheckCircle2 size={14} /> {draft.weekDone ? "Feito" : "Marcar"}
            </button>
          </div>

          <div>
            <label style={{ ...labelStyle, marginBottom: 2 }}><SecIcon icon={ClipboardList} color="#8b5cf6" />Histórico de conversas (linha do tempo)</label>
            <span style={hintStyle}>Cada conversa fica registrada aqui com data - diferente do resumo acima, que é só um texto curto. Usar os botões de WhatsApp/Email/Ligar já adiciona um registro automaticamente.</span>
            <div style={{ display: "flex", gap: 8, marginBottom: 12, marginTop: 6 }}>
              <input value={newNote} onChange={(e) => setNewNote(e.target.value)} onKeyDown={(e) => e.key === "Enter" && addNote()} placeholder="Registrar manualmente uma conversa ou anotação..." style={inputStyle} />
              <button onClick={addNote} disabled={!newNote.trim()} style={{ padding: "0 18px", borderRadius: 10, border: "none", background: newNote.trim() ? "#0f172a" : "rgba(148,163,184,0.3)", color: "white", fontSize: 13, fontWeight: 600, cursor: newNote.trim() ? "pointer" : "not-allowed", whiteSpace: "nowrap" }}>Adicionar</button>
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 0, position: "relative" }}>
              {(draft.notes || []).length === 0 && <div style={{ fontSize: 13, color: "#94a3b8", padding: "16px 0", textAlign: "center" }}>Nenhuma anotação ainda.</div>}
              {(draft.notes || []).map((note, idx) => {
                const isAuto = /^Contato via/.test(note.text);
                const dotColor = isAuto ? "#6d5ef8" : "#f59e0b";
                const isLast = idx === (draft.notes || []).length - 1;
                return (
                  <div key={note.id} style={{ display: "flex", gap: 10, paddingBottom: isLast ? 0 : 14, position: "relative" }}>
                    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", flexShrink: 0 }}>
                      <div style={{ width: 10, height: 10, borderRadius: "50%", background: dotColor, boxShadow: `0 0 0 3px ${dotColor}22`, marginTop: 4, flexShrink: 0 }} />
                      {!isLast && <div style={{ width: 2, flex: 1, background: "linear-gradient(180deg, " + dotColor + "55, rgba(148,163,184,0.15))", marginTop: 2 }} />}
                    </div>
                    <div style={{ flex: 1, minWidth: 0, padding: "10px 14px", borderRadius: 12, background: isAuto ? "rgba(109,94,248,0.06)" : "rgba(245,158,11,0.06)", border: `1px solid ${isAuto ? "rgba(109,94,248,0.15)" : "rgba(245,158,11,0.18)"}`, marginBottom: 2 }}>
                      <div style={{ fontSize: 11, color: dotColor, marginBottom: 4, fontWeight: 700 }}>{formatDateFull(note.date)}</div>
                      <div style={{ fontSize: 13, color: "#334155", lineHeight: 1.5 }}>{note.text}</div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>

        <div style={{ padding: "16px 28px", borderTop: "1px solid rgba(148, 163, 184, 0.15)", background: "rgba(248, 250, 252, 0.5)", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          {confirmDelete ? (
            <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
              <span style={{ fontSize: 13, color: "#64748b" }}>Confirmar exclusão?</span>
              <button onClick={() => onDelete(draft.id)} style={{ padding: "6px 12px", borderRadius: 8, border: "none", background: "#ef4444", color: "white", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>Sim, excluir</button>
              <button onClick={() => setConfirmDelete(false)} style={{ padding: "6px 12px", borderRadius: 8, border: "1px solid rgba(148,163,184,0.25)", background: "transparent", color: "#64748b", fontSize: 12, cursor: "pointer" }}>Cancelar</button>
            </div>
          ) : (
            <button onClick={() => setConfirmDelete(true)} style={{ padding: "8px 12px", borderRadius: 10, border: "none", background: "transparent", color: "#94a3b8", fontSize: 13, cursor: "pointer", display: "flex", alignItems: "center", gap: 6 }}><Trash2 size={14} /> Excluir lead</button>
          )}
          <button
            onClick={handleSave}
            style={{
              padding: "11px 24px", borderRadius: 12, border: "none",
              background: draft.stage === "Conquistado" ? "linear-gradient(135deg, #22c55e, #16a34a)" : "linear-gradient(135deg, #6366f1, #8b5cf6)",
              color: "white", fontSize: 13, fontWeight: 700, cursor: "pointer",
              boxShadow: draft.stage === "Conquistado" ? "0 8px 22px -8px rgba(34, 197, 94, 0.55)" : "0 8px 22px -8px rgba(99, 102, 241, 0.5)",
              animation: draft.stage === "Conquistado" && draft.stage !== lead.stage ? "celebrate 0.5s ease-out" : "none",
              transition: "background 0.3s ease, box-shadow 0.3s ease",
            }}
          >
            {draft.stage === "Conquistado" ? "🎉 Salvar alterações" : "Salvar alterações"}
          </button>
        </div>
      </div>
    </div>
  );
};

// ════════════════════════════════════════════════════════════════════════
// AGENDA: componentes auxiliares
// ════════════════════════════════════════════════════════════════════════

const DayStrip = ({ selectedDate, onSelect, meetings }) => {
  const week = Array.from({ length: 7 }).map((_, i) => addDays(startOfWeek(selectedDate), i));
  return (
    <div style={{ display: "flex", gap: 8, overflowX: "auto", paddingBottom: 4 }}>
      {week.map((d) => {
        const active = isSameDay(d, selectedDate);
        const dayMeetings = meetings.filter((m) => isSameDay(m.date, d));
        const types = [...new Set(dayMeetings.map((m) => m.type))].slice(0, 2);
        return (
          <button key={d.toISOString()} onClick={() => onSelect(d)} style={{
            flex: "0 0 auto", width: 62, padding: "10px 0", borderRadius: 14, border: "none", cursor: "pointer",
            background: active ? "linear-gradient(135deg, #6366f1, #8b5cf6)" : "rgba(255,255,255,0.6)",
            color: active ? "white" : "#334155", boxShadow: active ? "0 8px 20px -6px rgba(99,102,241,0.5)" : "none",
            display: "flex", flexDirection: "column", alignItems: "center", gap: 4, transition: "all 0.2s ease",
          }}>
            <span style={{ fontSize: 10, fontWeight: 700, opacity: 0.8 }}>{WEEKDAY_LABELS[d.getDay()]}</span>
            <span style={{ fontSize: 17, fontWeight: 700 }}>{d.getDate()}</span>
            <div style={{ display: "flex", gap: 3, height: 6 }}>
              {types.map((t) => <span key={t} style={{ width: 5, height: 5, borderRadius: "50%", background: active ? "white" : MEETING_TYPES[t].color }} />)}
            </div>
          </button>
        );
      })}
    </div>
  );
};

const MonthGrid = ({ selectedDate, onSelect, meetings }) => {
  const [viewMonth, setViewMonth] = useState(new Date(selectedDate.getFullYear(), selectedDate.getMonth(), 1));
  const firstDay = new Date(viewMonth.getFullYear(), viewMonth.getMonth(), 1);
  const startOffset = (firstDay.getDay() + 6) % 7; // segunda como início
  const daysInMonth = new Date(viewMonth.getFullYear(), viewMonth.getMonth() + 1, 0).getDate();
  const cells = [...Array(startOffset).fill(null), ...Array.from({ length: daysInMonth }, (_, i) => i + 1)];

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
        <span style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 17, fontWeight: 500, color: "#0f172a" }}>{MONTH_LABELS[viewMonth.getMonth()]} {viewMonth.getFullYear()}</span>
        <div style={{ display: "flex", gap: 6 }}>
          <button onClick={() => setViewMonth(new Date(viewMonth.getFullYear(), viewMonth.getMonth() - 1, 1))} style={navBtnStyle}><ChevronLeft size={15} /></button>
          <button onClick={() => setViewMonth(new Date(viewMonth.getFullYear(), viewMonth.getMonth() + 1, 1))} style={navBtnStyle}><ChevronRight size={15} /></button>
        </div>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 4, marginBottom: 6 }}>
        {WEEKDAY_LABELS.slice(1).concat(WEEKDAY_LABELS[0]).map((d) => <div key={d} style={{ textAlign: "center", fontSize: 10, fontWeight: 700, color: "#94a3b8" }}>{d}</div>)}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 4 }}>
        {cells.map((day, i) => {
          if (!day) return <div key={i} />;
          const d = new Date(viewMonth.getFullYear(), viewMonth.getMonth(), day);
          const active = isSameDay(d, selectedDate);
          const dayMeetings = meetings.filter((m) => isSameDay(m.date, d));
          const types = [...new Set(dayMeetings.map((m) => m.type))].slice(0, 3);
          return (
            <button key={i} onClick={() => onSelect(d)} style={{
              aspectRatio: "1", borderRadius: 10, border: "none", cursor: "pointer",
              background: active ? "linear-gradient(135deg, #6366f1, #8b5cf6)" : "transparent",
              color: active ? "white" : "#334155", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 3,
              fontSize: 12.5, fontWeight: active ? 700 : 500,
            }}>
              {day}
              <div style={{ display: "flex", gap: 2 }}>
                {types.map((t) => <span key={t} style={{ width: 4, height: 4, borderRadius: "50%", background: active ? "white" : MEETING_TYPES[t].color }} />)}
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
};

const navBtnStyle = { width: 28, height: 28, borderRadius: 8, border: "1px solid rgba(148,163,184,0.25)", background: "rgba(255,255,255,0.6)", color: "#64748b", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" };

// Modal para criar/editar/remover SDRs (Giovani, Pedro, +)
// Pop-up animado que aparece quando um SDR conquista uma badge nova
// Selo hexagonal de badge - imagens reais recortadas do conjunto enviado (uma por métrica × nível)
const BADGE_IMAGES = {
  leads_b50: BADGE_IMG_LEADS_B50, leads_super: BADGE_IMG_LEADS_SUPER, leads_lendaria: BADGE_IMG_LEADS_LENDARIA,
  proposals_b50: BADGE_IMG_PROPOSALS_B50, proposals_super: BADGE_IMG_PROPOSALS_SUPER, proposals_lendaria: BADGE_IMG_PROPOSALS_LENDARIA,
  meetings_b50: BADGE_IMG_MEETINGS_B50, meetings_super: BADGE_IMG_MEETINGS_SUPER, meetings_lendaria: BADGE_IMG_MEETINGS_LENDARIA,
  contracts_b50: BADGE_IMG_CONTRACTS_B50, contracts_super: BADGE_IMG_CONTRACTS_SUPER, contracts_lendaria: BADGE_IMG_CONTRACTS_LENDARIA,
};

const AchievementHex = ({ tier, metric, active, size = 84 }) => {
  const src = BADGE_IMAGES[`${metric.key}_${tier.key}`];
  return (
    <div style={{ width: size, height: size, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, filter: active ? "none" : "grayscale(1) opacity(0.55)" }}>
      <img src={src} alt={`${metric.label} - ${tier.label}`} style={{ width: "100%", height: "100%", objectFit: "contain" }} />
    </div>
  );
};

// Gera as moedinhas de ouro que caem no pop-up de badge conquistada - posição/tempo/tamanho
// aleatórios, mas fixados no primeiro render (useMemo) pra não "pular" a cada re-render.
const CoinRain = ({ zIndex = 199 }) => {
  const coins = useMemo(() => Array.from({ length: 16 }, (_, i) => {
    const gold = Math.random() > 0.35;
    return {
      id: i,
      left: Math.random() * 100,
      size: 4 + Math.random() * 5,
      duration: 2.4 + Math.random() * 1.8,
      delay: Math.random() * 1.8,
      rotateDir: Math.random() > 0.5 ? 1 : -1,
      color: gold ? "#f5c518" : "#ffffff",
      glow: gold ? "rgba(245,197,24,0.9)" : "rgba(255,255,255,0.9)",
    };
  }), []);
  return (
    <div style={{ position: "fixed", inset: 0, overflow: "hidden", pointerEvents: "none", zIndex }}>
      {coins.map((c) => (
        <span
          key={c.id}
          style={{
            position: "absolute", top: -20, left: `${c.left}%`,
            width: c.size, height: c.size, borderRadius: "50%",
            background: c.color,
            boxShadow: `0 0 6px 2px ${c.glow}`,
            animation: `coinFall ${c.duration}s linear ${c.delay}s infinite`,
            "--rot": `${360 * c.rotateDir}deg`,
          }}
        />
      ))}
    </div>
  );
};

