const SdrManager = ({ sdrs, leads, meetings, onAdd, onRemove, onUpdateAvatar, onClose, authMembers = [], onSync }) => {
  const [name, setName] = useState("");
  // SDR que o usuário pediu pra remover e que tem leads/reuniões, aguardando escolha de pra quem reatribuir
  const [pendingRemoval, setPendingRemoval] = useState(null);
  const [reassignTo, setReassignTo] = useState("");
  const [uploadingFor, setUploadingFor] = useState(null);
  const fileInputRef = useRef(null);

  const countFor = (sdrName) =>
    leads.filter((l) => l.owner === sdrName).length + meetings.filter((m) => m.owner === sdrName).length;

  const handleRemoveClick = (sdrName) => {
    const count = countFor(sdrName);
    if (count === 0) { onRemove(sdrName); return; }
    const nextTarget = sdrs.find((s) => s.name !== sdrName)?.name || "";
    setPendingRemoval(sdrName);
    setReassignTo(nextTarget);
  };

  const handlePickPhoto = (sdrName) => {
    setUploadingFor(sdrName);
    fileInputRef.current?.click();
  };

  const handleFileChange = async (e) => {
    const file = e.target.files?.[0];
    e.target.value = ""; // permite escolher o mesmo arquivo de novo depois
    if (!file || !uploadingFor) return;
    await onUpdateAvatar(uploadingFor, file);
    setUploadingFor(null);
  };

  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(30, 20, 60, 0.4)", backdropFilter: "blur(8px)", zIndex: 110, display: "flex", alignItems: "center", justifyContent: "center", padding: 20, animation: "fadeIn 0.2s ease" }}>
      <div onClick={(e) => e.stopPropagation()} style={{ width: "100%", maxWidth: 380, background: "rgba(255,255,255,0.95)", backdropFilter: "blur(30px)", borderRadius: 20, border: "1px solid rgba(255,255,255,0.9)", boxShadow: "0 30px 80px -20px rgba(76,29,149,0.35)", overflow: "hidden" }}>
        <input ref={fileInputRef} type="file" accept="image/*" onChange={handleFileChange} style={{ display: "none" }} />
        <div style={{ padding: "18px 22px", borderBottom: "1px solid rgba(148,163,184,0.15)" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 19, fontWeight: 500, color: "#0f172a" }}>Gerenciar SDRs</span>
            <button onClick={onClose} style={{ width: 30, height: 30, borderRadius: 9, border: "1px solid rgba(148,163,184,0.25)", background: "white", color: "#64748b", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}><X size={15} /></button>
          </div>
          <div style={{ fontSize: 11.5, color: "#9a9aa3", marginTop: 4 }}>
            Nomes usados pra atribuir leads. O selo verde mostra quem também tem login de verdade no funil.
          </div>
        </div>
        <div style={{ padding: "18px 22px" }}>
          {authMembers.length > 0 && (
            <button
              onClick={onSync}
              style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 6, width: "100%", padding: "8px 12px", borderRadius: 10, border: "1px dashed rgba(99,102,241,0.4)", background: "rgba(99,102,241,0.06)", color: "#6366f1", fontSize: 12, fontWeight: 700, cursor: "pointer", marginBottom: 12 }}
            >
              <Users2 size={13} /> Sincronizar com quem tem login no funil
            </button>
          )}
          <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 16 }}>
            {sdrs.map((s) => {
              const hasLogin = authMembers.some((m) => m.display_name.toLowerCase() === s.name.toLowerCase());
              return (
              <div key={s.name}>
                <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 10px", borderRadius: 11, background: "rgba(241,245,249,0.6)" }}>
                  <button
                    onClick={() => handlePickPhoto(s.name)}
                    title="Trocar foto"
                    style={{ position: "relative", border: "none", background: "transparent", padding: 0, cursor: "pointer", flexShrink: 0 }}
                  >
                    <OwnerAvatar name={s.name} size={30} avatarUrl={s.avatarUrl} />
                    <div style={{ position: "absolute", bottom: -2, right: -2, width: 15, height: 15, borderRadius: "50%", background: "#6366f1", border: "2px solid white", display: "flex", alignItems: "center", justifyContent: "center" }}>
                      {uploadingFor === s.name ? <Loader2 size={8} color="white" style={{ animation: "spin 1s linear infinite" }} /> : <Pencil size={8} color="white" />}
                    </div>
                  </button>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
                      <span style={{ fontSize: 13.5, fontWeight: 600, color: "#0f172a" }}>{s.name}</span>
                      {hasLogin && (
                        <span title="Tem login de verdade no funil" style={{ display: "inline-flex", alignItems: "center", gap: 3, fontSize: 9.5, fontWeight: 700, color: "#059669", background: "rgba(5,150,105,0.1)", padding: "1px 6px", borderRadius: 20 }}>
                          <CheckCircle2 size={9} /> login
                        </span>
                      )}
                    </div>
                    {!hasLogin && <div style={{ fontSize: 10.5, color: "#b4b6bc" }}>apenas nome, sem acesso ao funil</div>}
                  </div>
                  <button
                    onClick={() => handleRemoveClick(s.name)}
                    disabled={sdrs.length <= 1}
                    title={sdrs.length <= 1 ? "Precisa ter ao menos 1 SDR" : "Remover"}
                    style={{ width: 28, height: 28, borderRadius: 8, border: "none", background: sdrs.length <= 1 ? "transparent" : "rgba(239,68,68,0.1)", color: sdrs.length <= 1 ? "#cbd5e1" : "#dc2626", cursor: sdrs.length <= 1 ? "not-allowed" : "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}
                  >
                    <Trash2 size={13} />
                  </button>
                </div>
                {pendingRemoval === s.name && (
                  <div style={{ marginTop: 6, padding: "10px 12px", borderRadius: 10, background: "rgba(239,68,68,0.06)", border: "1px solid rgba(239,68,68,0.2)" }}>
                    <div style={{ fontSize: 12, color: "#7f1d1d", marginBottom: 8 }}>
                      {s.name} tem {countFor(s.name)} lead(s)/reunião(ões). Reatribuir para:
                    </div>
                    <div style={{ display: "flex", gap: 6 }}>
                      <select value={reassignTo} onChange={(e) => setReassignTo(e.target.value)} style={{ ...selectStyle, flex: 1, padding: "7px 10px", fontSize: 12.5 }}>
                        {sdrs.filter((o) => o.name !== s.name).map((o) => <option key={o.name} value={o.name}>{o.name}</option>)}
                      </select>
                      <button onClick={() => { onRemove(s.name, reassignTo); setPendingRemoval(null); }} style={{ padding: "0 12px", borderRadius: 8, border: "none", background: "#dc2626", color: "white", fontSize: 12, fontWeight: 700, cursor: "pointer" }}>Confirmar</button>
                      <button onClick={() => setPendingRemoval(null)} style={{ padding: "0 12px", borderRadius: 8, border: "1px solid rgba(148,163,184,0.3)", background: "white", color: "#64748b", fontSize: 12, cursor: "pointer" }}>Cancelar</button>
                    </div>
                  </div>
                )}
              </div>
              );
            })}
          </div>
          <div style={{ display: "flex", gap: 8 }}>
            <input
              value={name}
              onChange={(e) => setName(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter" && name.trim()) { onAdd(name); setName(""); } }}
              placeholder="Nome do novo SDR"
              style={{ flex: 1, padding: "9px 12px", borderRadius: 10, border: "1px solid rgba(148,163,184,0.3)", background: "white", fontSize: 13, color: "#0f172a", outline: "none" }}
            />
            <button
              onClick={() => { if (name.trim()) { onAdd(name); setName(""); } }}
              disabled={!name.trim()}
              style={{ padding: "0 16px", borderRadius: 10, border: "none", background: name.trim() ? "linear-gradient(135deg, #6366f1, #8b5cf6)" : "rgba(148,163,184,0.3)", color: "white", fontSize: 13, fontWeight: 700, cursor: name.trim() ? "pointer" : "not-allowed" }}
            >
              <Plus size={15} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

// ════════════════════════════════════════════════════════════════════════
// IMPORTAÇÃO DE LEADS COM IA - Excel/CSV (parse real) ou texto colado (PDF/outros)
// ════════════════════════════════════════════════════════════════════════

// Lê um arquivo .xlsx/.xls/.csv no navegador e devolve um texto tabular (CSV) pra mandar pra IA
// Lê um arquivo .xlsx/.xls/.csv no navegador e devolve um texto tabular (CSV) pra mandar pra IA.
// CSV é lido como texto (respeita acentuação/UTF-8); xlsx/xls como binário (formato real de planilha).
// Corta em até ~50.000 caracteres SEM quebrar uma linha no meio (evita mandar uma linha cortada pra IA).
const readSpreadsheetAsText = (file) =>
  new Promise((resolve, reject) => {
    const ext = (file.name.split(".").pop() || "").toLowerCase();
    const isCsv = ext === "csv";
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const wb = XLSX.read(e.target.result, { type: isCsv ? "string" : "array" });
        if (!wb.SheetNames || wb.SheetNames.length === 0) { reject(new Error("empty")); return; }
        const sheet = wb.Sheets[wb.SheetNames[0]];
        let csv = XLSX.utils.sheet_to_csv(sheet);
        if (!csv || !csv.trim()) { reject(new Error("empty")); return; }
        if (csv.length > 50000) {
          const cut = csv.lastIndexOf("\n", 50000);
          csv = csv.slice(0, cut > 0 ? cut : 50000);
        }
        resolve(csv);
      } catch (err) { reject(err); }
    };
    reader.onerror = () => reject(new Error("read failed"));
    if (isCsv) reader.readAsText(file, "utf-8");
    else reader.readAsArrayBuffer(file);
  });

// Divide um texto tabular em lotes de linhas - evita que a IA trunque a resposta em listas grandes.
// Repete a 1ª linha (cabeçalho) em cada lote quando parece ser CSV, pra IA não perder o contexto das colunas.
const chunkRowsForAI = (rawText, linesPerChunk = 25) => {
  const lines = rawText.split(/\r?\n/).filter((l) => l.trim().length > 0);
  if (lines.length === 0) return [];
  const looksLikeCsv = lines[0].includes(",") || lines[0].includes(";") || lines[0].includes("\t");
  const header = looksLikeCsv ? lines[0] : null;
  const body = header ? lines.slice(1) : lines;
  if (body.length === 0) return [lines.join("\n")];
  const chunks = [];
  for (let i = 0; i < body.length; i += linesPerChunk) {
    const slice = body.slice(i, i + linesPerChunk);
    chunks.push(header ? [header, ...slice].join("\n") : slice.join("\n"));
  }
  return chunks;
};

// Cria um erro "conhecido", com texto já pensado pra aparecer pro usuário.
// Qualquer outro erro (exceções nativas do navegador, tipo "The string did not
// match the expected pattern") nunca deve vazar direto pra tela, só esses aqui.
const friendlyError = (msg) => Object.assign(new Error(msg), { friendly: true });

// Lê a resposta da API de forma defensiva: pega o texto cru primeiro (nunca
// response.json() direto, que quebra se vier algo fora do formato esperado) e só
// depois tenta interpretar como JSON. Se der ruim, quem chamou decide se tenta de novo.
const parseClaudeResponseText = async (response) => {
  let raw;
  try {
    raw = await response.text();
  } catch {
    throw friendlyError("Não consegui ler a resposta da IA. Tente novamente.");
  }
  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    console.error("Resposta da IA não é um JSON válido:", raw);
    return null; // sinaliza pra quem chamou tentar de novo, sem já mostrar erro na tela
  }
  const textBlock = (data.content || []).find((b) => b.type === "text");
  return textBlock && textBlock.text ? textBlock.text : null;
};

// Chama a API da Claude de forma robusta: uma nova tentativa automática e silenciosa
// se a resposta vier corrompida ou vazia (bem raro, mas acontece por causa de rede
// instável), e só mostra erro pro usuário se as duas tentativas falharem.
// Chama a IA através da Edge Function do Supabase (ai-proxy), que guarda a chave
// da Anthropic em segredo no servidor - o navegador nunca vê essa chave, só o token
// de sessão do próprio usuário logado, que a função exige pra funcionar.
const callClaudeAPI = async ({ system, messages, maxTokens }) => {
  const doRequest = async () => {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) throw friendlyError("Sua sessão expirou. Atualize a página e entre novamente.");

    let response;
    try {
      response = await fetch("https://spdqghchvimjytycdmjk.supabase.co/functions/v1/ai-proxy", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${session.access_token}` },
        body: JSON.stringify({ max_tokens: maxTokens, system, messages }),
      });
    } catch {
      throw friendlyError("Não consegui conectar à IA. Verifique sua internet e tente de novo.");
    }
    if (!response.ok) {
      if (response.status === 429) throw friendlyError("Muitas requisições à IA em pouco tempo. Aguarde alguns segundos e tente de novo.");
      throw friendlyError("Falha ao chamar a IA (código " + response.status + "). Tente novamente.");
    }
    return parseClaudeResponseText(response);
  };

  let text = await doRequest();
  if (text === null) text = await doRequest(); // uma segunda chance antes de desistir
  if (text === null) throw friendlyError("A IA devolveu uma resposta incompleta. Tente novamente em alguns segundos.");
  return text;
};

// Extrai o array JSON de uma resposta de IA de forma tolerante - a IA às vezes
// escreve um comentário antes/depois do array mesmo quando instruída a não fazer isso.
const extractJsonArray = (text) => {
  const trimmed = text.replace(/```json|```/gi, "").trim();
  try { return JSON.parse(trimmed); } catch { /* tenta abaixo */ }
  const match = trimmed.match(/\[[\s\S]*\]/);
  if (match) {
    try { return JSON.parse(match[0]); } catch { /* segue pro erro final */ }
  }
  throw friendlyError("A IA devolveu uma resposta que não pôde ser lida. Tente importar menos linhas de cada vez.");
};

// Chama a IA (Claude) pra extrair leads estruturados de UM lote de texto bruto
const extractLeadsWithAI = async (rawText, sdrNames) => {
  const stageList = STAGE_OPTIONS.join(", ");
  const sdrList = sdrNames.join(", ") || "nenhum cadastrado";
  const systemPrompt = `Você extrai leads comerciais de dados brutos (planilha ou texto solto) e devolve APENAS um array JSON válido, sem markdown, sem explicação, sem crases.
Cada item do array deve ter exatamente estes campos:
{
  "company": string (nome da empresa/lead - obrigatório, nunca vazio),
  "contactName": string ou "" (nome da pessoa de contato, se houver),
  "phone": string ou "" (telefone, mantenha como veio),
  "email": string ou "" (email, se houver),
  "whatsapp": string ou "" (se identificar que é whatsapp, senão vazio),
  "owner": string ou "" (responsável/SDR, tente casar com um destes se possível: ${sdrList}; senão deixe vazio),
  "stage": string (escolha o mais parecido entre: ${stageList}; se não identificar, use "Apresentação"),
  "feedback": string ou "" (qualquer observação, status, contexto extra da linha)
}
Regras: ignore linhas de cabeçalho/vazias. Se uma coluna parecer telefone com "whatsapp" no texto ou contexto, preencha "whatsapp" também. Nunca invente dados que não existem - deixe "" se não tiver certeza. Se não houver NENHUM lead identificável no texto, devolva um array vazio []. Responda SOMENTE o array JSON, começando com [ e terminando com ].`;

  const text = await callClaudeAPI({
    system: systemPrompt,
    messages: [{ role: "user", content: `Dados brutos para extrair:\n\n${rawText}` }],
    maxTokens: 8000,
  });
  const parsed = extractJsonArray(text);
  if (!Array.isArray(parsed)) throw friendlyError("A IA devolveu um formato inesperado. Tente novamente.");
  return parsed;
};

// ════════════════════════════════════════════════════════════════════════
// ASSISTENTE DE IA - chat que conhece o estado real do funil e sugere ações
// ════════════════════════════════════════════════════════════════════════

// Formata uma data com segurança, sem nunca lançar exceção (mesmo se vier corrompida)
const safeDate = (value, fmt) => {
  try {
    const d = new Date(value);
    if (isNaN(d.getTime())) return "data inválida";
    return fmt(d);
  } catch {
    return "data inválida";
  }
};

// Monta um resumo compacto e objetivo do funil (leads parados, quentes sem contato,
// reuniões da semana, etc.) pra mandar como contexto pra IA - sem despejar o JSON inteiro.
const buildFunnelContext = (leads, meetings, sdrs, weeklyGoal) => {
  const activeLeads = leads.filter((l) => l.stage !== "Conquistado" && l.stage !== "Perdida");
  const stale = activeLeads
    .filter((l) => { const d = daysSince(l.lastContact); return d === null || d > 14; })
    .sort((a, b) => (daysSince(b.lastContact) ?? 9999) - (daysSince(a.lastContact) ?? 9999))
    .slice(0, 15);
  const hotNoContact = activeLeads.filter((l) => l.temperature === "hot" && (daysSince(l.lastContact) === null || daysSince(l.lastContact) > 3)).slice(0, 10);
  const desatendidos = activeLeads.filter((l) => l.status === "Desatendido").slice(0, 15);
  const superLeads = activeLeads.filter((l) => l.superAttention).slice(0, 10);
  const now = new Date();
  const in7d = new Date(now.getTime() + 7 * 86400000);
  const upcomingMeetings = meetings.filter((m) => { try { const d = new Date(m.date); return d >= now && d <= in7d; } catch { return false; } });
  const weekTagged = activeLeads.filter((l) => l.weekTag && !l.weekDone);

  const fmt = (l) => `- ${l.company} (SDR: ${l.owner || "?"}, temperatura: ${TEMP_CONFIG[l.temperature]?.label || l.temperature}, estágio: ${l.stage}${l.lastContact ? `, último contato há ${daysSince(l.lastContact)}d` : ", sem contato registrado"}${l.feedback ? `, obs: "${l.feedback}"` : ""})`;

  return `ESTADO ATUAL DO FUNIL DE VENDAS (${safeDate(new Date(), (d) => d.toLocaleDateString("pt-BR"))}):

SDRs da equipe: ${sdrs.map((s) => s.name).join(", ") || "nenhum"}
Meta semanal de leads abordados: ${weeklyGoal}
Total de leads ativos (não conquistados/perdidos): ${activeLeads.length}

LEADS PARADOS HÁ MAIS DE 14 DIAS OU NUNCA CONTATADOS (até 15 listados):
${stale.length ? stale.map(fmt).join("\n") : "Nenhum - funil em dia."}

LEADS QUENTES SEM CONTATO RECENTE (até 10 listados):
${hotNoContact.length ? hotNoContact.map(fmt).join("\n") : "Nenhum."}

NEGOCIAÇÕES ANTIGAS marcadas como desatendidas (até 15 listadas):
${desatendidos.length ? desatendidos.map(fmt).join("\n") : "Nenhuma."}

SUPER LEADS (alta prioridade, até 10 listados):
${superLeads.length ? superLeads.map(fmt).join("\n") : "Nenhum marcado."}

LEADS JÁ MARCADOS PRA ABORDAR ESSA SEMANA (tag manual, ainda pendentes): ${weekTagged.length}

REUNIÕES NOS PRÓXIMOS 7 DIAS: ${upcomingMeetings.length}
${upcomingMeetings.slice(0, 10).map((m) => `- ${safeDate(m.date, (d) => d.toLocaleDateString("pt-BR"))} ${safeDate(m.date, (d) => d.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" }))}: ${m.company} (${MEETING_TYPES[m.type]?.label || m.type}, SDR: ${m.owner})`).join("\n")}`;
};

// Chama a IA com o contexto do funil + histórico da conversa
const askFunnelAssistant = async (context, chatHistory, userMessage) => {
  const systemPrompt = `Você é um assistente de vendas dentro de um CRM B2B, especialista em priorização de funil e cadência de follow-up. Você tem acesso ao estado real e atualizado do funil da equipe (leads parados, quentes sem contato, negociações antigas, reuniões marcadas). Seu trabalho é dar sugestões PRÁTICAS e ESPECÍFICAS - sempre cite nomes reais de empresas quando fizer sentido, nunca fale em genérico tipo "entre em contato com seus leads". Seja direto, use listas curtas quando ajudar, fale em português do Brasil, tom de colega experiente de vendas - não robótico. Não invente dados que não estão no contexto fornecido. Se o usuário pedir algo fora do funil (ex: perguntas gerais), responda normalmente mas volte o foco pro trabalho comercial quando possível.

${context}`;

  const messages = [
    ...chatHistory.map((m) => ({ role: m.role, content: m.content })),
    { role: "user", content: userMessage },
  ];

  return callClaudeAPI({ system: systemPrompt, messages, maxTokens: 1500 });
};

// Normaliza nome de empresa pra comparar (minúsculo, sem acento, sem pontuação) -
// evita que "Açaí Amazonas" e "acai amazonas" sejam tratados como empresas diferentes.
const normalizeCompanyName = (s) =>
  (s || "")
    .toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // remove acentos
    .replace(/[^a-z0-9]+/g, " ")
    .trim();

// Interpreta texto colado (ou CSV/Excel convertido pra texto) como pares de
// "empresa, telefone" - aceita separador por tab, ponto e vírgula, vírgula ou hífen.
const parseCompanyPhoneRows = (text) => {
  const lines = text.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
  const rows = [];
  for (const line of lines) {
    let parts = line.split("\t");
    if (parts.length < 2) parts = line.split(";");
    if (parts.length < 2) parts = line.split(",");
    if (parts.length < 2) parts = line.split(/\s+-\s+/);
    if (parts.length < 2) continue;
    const company = parts[0].trim();
    const phoneRaw = parts.slice(1).join(" ").trim();
    const phoneDigits = phoneRaw.replace(/\D/g, "");
    if (!company || phoneDigits.length < 8) continue; // ignora cabeçalho / linhas sem telefone válido
    if (/telefone|whatsapp|phone|celular/i.test(company) && phoneDigits.length < 8) continue; // ignora linha de cabeçalho
    rows.push({ company, phoneRaw: phoneRaw, phoneDigits });
  }
  return rows;
};

// ════════════════════════════════════════════════════════════════════════
// ATUALIZAR TELEFONES EM MASSA - cola "empresa + whatsapp" ou sobe um Excel,
// o app casa pelo nome da empresa com os leads já existentes e atualiza o telefone.
// ════════════════════════════════════════════════════════════════════════
const BulkPhoneModal = ({ leads, onClose, onApply }) => {
  const [rawText, setRawText] = useState("");
  const [fileLoading, setFileLoading] = useState(false);
  const [fileError, setFileError] = useState("");
  const fileInputRef = useRef(null);

  const parsedRows = useMemo(() => parseCompanyPhoneRows(rawText), [rawText]);

  const matches = useMemo(() => {
    return parsedRows.map((row) => {
      const norm = normalizeCompanyName(row.company);
      const lead = leads.find((l) => normalizeCompanyName(l.company) === norm);
      return { ...row, lead };
    });
  }, [parsedRows, leads]);

  const matchedCount = matches.filter((m) => m.lead).length;
  const unmatchedCount = matches.length - matchedCount;

  const handleFile = async (e) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    setFileLoading(true);
    setFileError("");
    try {
      const csv = await readSpreadsheetAsText(file);
      setRawText(csv);
    } catch {
      setFileError("Não consegui ler esse arquivo. Tenta colar o texto direto, ou confirma que é um .xlsx/.xls/.csv válido.");
    } finally {
      setFileLoading(false);
    }
  };

  const handleApply = () => {
    const toApply = matches.filter((m) => m.lead).map((m) => ({ leadId: m.lead.id, phoneDigits: m.phoneDigits }));
    onApply(toApply);
    onClose();
  };

  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(30, 20, 60, 0.4)", backdropFilter: "blur(8px)", zIndex: 130, display: "flex", alignItems: "center", justifyContent: "center", padding: 20, animation: "fadeIn 0.2s ease" }}>
      <div onClick={(e) => e.stopPropagation()} style={{ width: "100%", maxWidth: 560, maxHeight: "88vh", display: "flex", flexDirection: "column", background: "rgba(255,255,255,0.96)", backdropFilter: "blur(30px)", borderRadius: 22, border: "1px solid rgba(255,255,255,0.9)", boxShadow: "0 30px 90px -20px rgba(76,29,149,0.35)", overflow: "hidden" }}>
        <div style={{ padding: "20px 24px 14px", borderBottom: "1px solid rgba(148,163,184,0.15)", display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
          <div>
            <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 18, fontWeight: 700, color: "#0f172a" }}>Atualizar telefones em massa</div>
            <div style={{ fontSize: 12, color: "#64748b", marginTop: 2 }}>Cole uma lista de "empresa + WhatsApp", ou suba um Excel/CSV com essas duas colunas. O app casa pelo nome da empresa com os leads que já existem.</div>
          </div>
          <button onClick={onClose} style={{ width: 32, height: 32, borderRadius: 10, border: "1px solid rgba(148,163,184,0.25)", background: "white", color: "#64748b", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><X size={16} /></button>
        </div>

        <div style={{ padding: "18px 24px", overflowY: "auto", flex: 1 }}>
          <input ref={fileInputRef} type="file" accept=".xlsx,.xls,.csv" onChange={handleFile} style={{ display: "none" }} />
          <button
            onClick={() => fileInputRef.current?.click()}
            disabled={fileLoading}
            style={{ width: "100%", padding: "12px 14px", borderRadius: 12, border: "1.5px dashed rgba(109,94,248,0.4)", background: "rgba(109,94,248,0.05)", color: "#6d5ef8", fontSize: 13, fontWeight: 700, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", gap: 8, marginBottom: 12 }}
          >
            {fileLoading ? <Loader2 size={15} style={{ animation: "spin 1s linear infinite" }} /> : <FileUp size={15} />}
            {fileLoading ? "Lendo arquivo..." : "Subir Excel/CSV (Empresa | WhatsApp)"}
          </button>
          {fileError && <div style={{ fontSize: 12, color: "#dc2626", marginBottom: 10 }}>{fileError}</div>}

          <div style={{ fontSize: 11, fontWeight: 700, color: "#94a3b8", textTransform: "uppercase", marginBottom: 6 }}>Ou cole aqui (uma empresa por linha)</div>
          <textarea
            value={rawText}
            onChange={(e) => setRawText(e.target.value)}
            placeholder={"Açaí Amazonas, 11987654321\nBFB Foods; (11) 99887-7665\nMarkal\t11912345678"}
            style={{ ...inputStyle, minHeight: 110, resize: "vertical", fontFamily: "monospace", fontSize: 12.5 }}
          />

          {matches.length > 0 && (
            <div style={{ marginTop: 16 }}>
              <div style={{ display: "flex", gap: 8, marginBottom: 10 }}>
                <span style={{ fontSize: 11.5, fontWeight: 700, color: "#16a34a", background: "rgba(34,197,94,0.1)", padding: "4px 10px", borderRadius: 8 }}>✓ {matchedCount} encontrado{matchedCount === 1 ? "" : "s"}</span>
                {unmatchedCount > 0 && <span style={{ fontSize: 11.5, fontWeight: 700, color: "#dc2626", background: "rgba(239,68,68,0.1)", padding: "4px 10px", borderRadius: 8 }}>✗ {unmatchedCount} não encontrado{unmatchedCount === 1 ? "" : "s"}</span>}
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 6, maxHeight: 220, overflowY: "auto" }}>
                {matches.map((m, i) => (
                  <div key={i} style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 10px", borderRadius: 10, background: m.lead ? "rgba(34,197,94,0.06)" : "rgba(239,68,68,0.06)", border: `1px solid ${m.lead ? "rgba(34,197,94,0.2)" : "rgba(239,68,68,0.2)"}` }}>
                    {m.lead ? <CheckCircle2 size={14} color="#16a34a" style={{ flexShrink: 0 }} /> : <XCircle size={14} color="#dc2626" style={{ flexShrink: 0 }} />}
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 12.5, fontWeight: 700, color: "#0f172a", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{m.company}</div>
                      {!m.lead && <div style={{ fontSize: 10.5, color: "#dc2626" }}>nenhum lead com esse nome</div>}
                    </div>
                    <div style={{ fontSize: 11.5, color: "#64748b", flexShrink: 0 }}>{m.phoneDigits}</div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <div style={{ padding: "14px 24px", borderTop: "1px solid rgba(148,163,184,0.15)", display: "flex", justifyContent: "flex-end", gap: 8 }}>
          <button onClick={onClose} style={{ padding: "10px 18px", borderRadius: 10, border: "1px solid rgba(148,163,184,0.3)", background: "white", color: "#64748b", fontSize: 13, fontWeight: 600, cursor: "pointer" }}>Cancelar</button>
          <button
            onClick={handleApply}
            disabled={matchedCount === 0}
            style={{ padding: "10px 20px", borderRadius: 10, border: "none", background: matchedCount > 0 ? "linear-gradient(135deg, #22c55e, #16a34a)" : "rgba(148,163,184,0.3)", color: "white", fontSize: 13, fontWeight: 700, cursor: matchedCount > 0 ? "pointer" : "not-allowed" }}
          >
            Atualizar {matchedCount > 0 ? `${matchedCount} telefone${matchedCount === 1 ? "" : "s"}` : ""}
          </button>
        </div>
      </div>
    </div>
  );
};

const ImportModal = ({ sdrs, existingLeads, onClose, onConfirm }) => {
  const [step, setStep] = useState("input"); // input | loading | review  (erro agora é um banner dentro de "input", não um passo separado)
  const [pastedText, setPastedText] = useState("");
  const [fileName, setFileName] = useState("");
  const [errorMsg, setErrorMsg] = useState("");
  const [progress, setProgress] = useState(null); // { done, total } durante processamento em lotes
  const [draftLeads, setDraftLeads] = useState([]);
  const [isDragging, setIsDragging] = useState(false);

  // Evita atualizar estado depois que o modal foi fechado/desmontado no meio de uma chamada assíncrona
  const mountedRef = useRef(true);
  useEffect(() => () => { mountedRef.current = false; }, []);
  const safeSet = (fn) => { if (mountedRef.current) fn(); };

  // Fecha com Esc, exceto durante o carregamento (evita perder o processamento em andamento sem perceber)
  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape" && step !== "loading") onClose(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [step, onClose]);

  const requestClose = () => { if (step !== "loading") onClose(); };

  const existingNames = useMemo(
    () => new Set((existingLeads || []).map((l) => (l.company || "").trim().toLowerCase())),
    [existingLeads]
  );

  const MAX_CHUNKS = 12; // trava de segurança: evita dezenas de chamadas de IA numa importação gigante

  const runImport = async (rawText) => {
    setStep("loading");
    setErrorMsg("");
    setProgress(null);
    try {
      const allChunks = chunkRowsForAI(rawText);
      if (allChunks.length === 0) {
        safeSet(() => { setErrorMsg("Não encontrei nenhuma linha de dados pra processar."); setStep("input"); });
        return;
      }
      const chunks = allChunks.slice(0, MAX_CHUNKS);
      let truncatedWarning = allChunks.length > MAX_CHUNKS
        ? ` Só processei as primeiras ${MAX_CHUNKS * 25} linhas aproximadamente - importe o restante em uma segunda vez.`
        : "";

      let allExtracted = [];
      let failedChunks = 0;
      for (let i = 0; i < chunks.length; i++) {
        if (!mountedRef.current) return; // usuário fechou o modal no meio do processamento
        safeSet(() => setProgress({ done: i, total: chunks.length }));
        try {
          const extracted = await extractLeadsWithAI(chunks[i], sdrs.map((s) => s.name));
          allExtracted = allExtracted.concat(extracted);
        } catch {
          // Não perde o que já foi processado com sucesso - só marca esse lote como falho e segue pros próximos
          failedChunks++;
        }
      }
      if (!mountedRef.current) return;
      setProgress({ done: chunks.length, total: chunks.length });

      if (failedChunks > 0) {
        truncatedWarning += ` ${failedChunks} de ${chunks.length} lote${chunks.length === 1 ? "" : "s"} falhou/falharam ao processar (rede instável ou resposta da IA incompleta) - os leads desses lotes não aparecem abaixo. Você pode tentar importar de novo.`;
      }
      if (allExtracted.length === 0 && failedChunks === chunks.length) {
        safeSet(() => { setErrorMsg("Não consegui processar nenhum lote com a IA. Verifique sua conexão e tente novamente."); setStep("input"); });
        return;
      }

      const withDefaults = allExtracted
        .filter((l) => l && l.company && String(l.company).trim())
        .map((l, i) => {
          const companyTrim = String(l.company).trim();
          return {
            _include: true,
            _tmpId: "imp_" + Date.now() + "_" + i,
            _duplicate: existingNames.has(companyTrim.toLowerCase()),
            company: companyTrim,
            contactName: l.contactName || "",
            phone: l.phone || "",
            email: l.email || "",
            whatsapp: l.whatsapp || "",
            owner: sdrs.some((s) => s.name === l.owner) ? l.owner : (sdrs[0]?.name || ""),
            stage: STAGE_OPTIONS.includes(l.stage) ? l.stage : "Apresentação",
            feedback: l.feedback || "",
          };
        });

      if (withDefaults.length === 0) {
        safeSet(() => {
          setErrorMsg("Não encontrei nenhum lead reconhecível nos dados enviados. Verifique se o arquivo/texto tem nomes de empresas ou contatos identificáveis." + truncatedWarning);
          setStep("input");
        });
        return;
      }
      safeSet(() => {
        setDraftLeads(withDefaults);
        setErrorMsg(truncatedWarning ? truncatedWarning.trim() : "");
        setStep("review");
      });
    } catch (err) {
      if (err && err.friendly) safeSet(() => { setErrorMsg(err.message); setStep("input"); });
      else { console.error("Erro inesperado na importação:", err); safeSet(() => { setErrorMsg("Algo deu errado ao processar com IA. Tente novamente."); setStep("input"); }); }
    } finally {
      safeSet(() => setProgress(null));
    }
  };

  const handleFile = async (file) => {
    if (!file) return;
    setFileName(file.name);
    setErrorMsg("");
    const ext = (file.name.split(".").pop() || "").toLowerCase();
    if (!["xlsx", "xls", "csv"].includes(ext)) {
      setErrorMsg('Esse formato de arquivo não pode ser lido direto no navegador. Para PDF ou Word: abra o arquivo, copie o texto e cole no campo abaixo.');
      return;
    }
    try {
      const csvText = await readSpreadsheetAsText(file);
      runImport(csvText);
    } catch {
      safeSet(() => setErrorMsg("Não consegui ler essa planilha - verifique se o arquivo não está corrompido ou vazio, ou tente exportar novamente como .xlsx ou .csv."));
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files && e.dataTransfer.files[0];
    if (file) handleFile(file);
  };

  const updateDraft = (tmpId, patch) => setDraftLeads((prev) => prev.map((l) => (l._tmpId === tmpId ? { ...l, ...patch } : l)));
  const removeDraft = (tmpId) => setDraftLeads((prev) => prev.filter((l) => l._tmpId !== tmpId));
  const toggleAll = (value) => setDraftLeads((prev) => prev.map((l) => ({ ...l, _include: value })));

  const includedCount = draftLeads.filter((l) => l._include).length;
  const validIncludedCount = draftLeads.filter((l) => l._include && l.company.trim()).length;
  const emptyNameIncludedCount = includedCount - validIncludedCount;
  const duplicateCount = draftLeads.filter((l) => l._duplicate).length;

  return (
    <div onClick={requestClose} style={{ position: "fixed", inset: 0, background: "rgba(30, 20, 60, 0.45)", backdropFilter: "blur(8px)", zIndex: 120, display: "flex", alignItems: "flex-start", justifyContent: "center", padding: "4vh 16px", overflowY: "auto", animation: "fadeIn 0.2s ease" }}>
      <div onClick={(e) => e.stopPropagation()} style={{ width: "100%", maxWidth: 720, background: "white", borderRadius: 22, border: "1px solid rgba(255,255,255,0.9)", boxShadow: "0 30px 80px -20px rgba(20,20,26,0.4)", overflow: "hidden" }}>
        <div style={{ padding: "18px 22px", borderBottom: "1px solid #f1f2f5", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 19, fontWeight: 800, color: "#14141a" }}>Importar leads com IA</div>
            <div style={{ fontSize: 12, color: "#9a9aa3" }}>Excel, CSV ou texto colado - a IA organiza tudo pra você conferir</div>
          </div>
          <button
            onClick={requestClose}
            disabled={step === "loading"}
            title={step === "loading" ? "Aguarde o processamento terminar" : "Fechar"}
            style={{ width: 32, height: 32, borderRadius: 9, border: "1px solid #eef0f3", background: "white", color: step === "loading" ? "#d4d6db" : "#64748b", cursor: step === "loading" ? "not-allowed" : "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}
          ><X size={16} /></button>
        </div>

        <div style={{ padding: "20px 22px", maxHeight: "70vh", overflowY: "auto" }}>
          {step === "input" && (
            <>
              {errorMsg && (
                <div style={{ display: "flex", alignItems: "flex-start", gap: 10, padding: "12px 14px", borderRadius: 12, background: "rgba(226,72,63,0.08)", border: "1px solid rgba(226,72,63,0.25)", marginBottom: 16 }}>
                  <AlertCircle size={16} color="#e2483f" style={{ flexShrink: 0, marginTop: 1 }} />
                  <div style={{ fontSize: 12.5, color: "#7f1d1d", lineHeight: 1.5 }}>{errorMsg}</div>
                </div>
              )}

              <label
                htmlFor="import-file-input"
                onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                onDragLeave={() => setIsDragging(false)}
                onDrop={handleDrop}
                style={{
                  display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 8,
                  padding: "28px 20px", borderRadius: 16,
                  border: `2px dashed ${isDragging ? "#6d5ef8" : "#d7d9de"}`,
                  background: isDragging ? "rgba(109,94,248,0.06)" : "#fafbfc",
                  cursor: "pointer", marginBottom: 16, textAlign: "center", transition: "all 0.15s ease",
                }}
              >
                <FileUp size={26} color="#6d5ef8" />
                <div style={{ fontSize: 14, fontWeight: 700, color: "#14141a" }}>{isDragging ? "Solte o arquivo aqui" : (fileName || "Clique ou arraste um arquivo aqui")}</div>
                <div style={{ fontSize: 11.5, color: "#9a9aa3" }}>.xlsx, .xls ou .csv - lido direto, sem depender da IA pra extrair a tabela</div>
                <input
                  id="import-file-input"
                  type="file"
                  accept=".xlsx,.xls,.csv"
                  style={{ display: "none" }}
                  onChange={(e) => handleFile(e.target.files[0])}
                  onClick={(e) => { e.target.value = null; }}
                />
              </label>

              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
                <div style={{ flex: 1, height: 1, background: "#f1f2f5" }} />
                <span style={{ fontSize: 11, color: "#9a9aa3", fontWeight: 700 }}>OU COLE TEXTO</span>
                <div style={{ flex: 1, height: 1, background: "#f1f2f5" }} />
              </div>

              <div style={{ marginBottom: 6, fontSize: 12, color: "#6b6b75", display: "flex", alignItems: "center", gap: 6 }}>
                <ClipboardPaste size={13} /> Copie o texto de um PDF, email ou lista qualquer e cole aqui:
              </div>
              <textarea
                value={pastedText}
                onChange={(e) => setPastedText(e.target.value)}
                placeholder={"Ex:\nEmpresa X - João - (11) 99999-0000 - aguardando retorno\nEmpresa Y - proposta enviada - Maria - maria@empresa.com"}
                style={{ width: "100%", minHeight: 130, padding: 12, borderRadius: 12, border: "1.5px solid #e2e4e9", fontSize: 13, color: "#14141a", outline: "none", fontFamily: "inherit", resize: "vertical", boxSizing: "border-box" }}
              />
              <button
                onClick={() => pastedText.trim() && runImport(pastedText)}
                disabled={!pastedText.trim()}
                style={{ marginTop: 12, width: "100%", padding: "12px 0", borderRadius: 12, border: "none", cursor: pastedText.trim() ? "pointer" : "not-allowed", fontSize: 14, fontWeight: 700, background: pastedText.trim() ? "linear-gradient(135deg, #6d5ef8, #8b7bfa)" : "#eef0f3", color: pastedText.trim() ? "white" : "#b4b6bc", display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}
              >
                <Sparkles size={15} /> Processar texto colado com IA
              </button>
            </>
          )}

          {step === "loading" && (
            <div style={{ padding: "50px 20px", textAlign: "center" }}>
              <Loader2 size={30} color="#6d5ef8" style={{ animation: "spin 1s linear infinite" }} />
              <div style={{ fontSize: 15, fontWeight: 700, color: "#14141a", marginTop: 14 }}>Lendo e organizando seus leads...</div>
              <div style={{ fontSize: 12.5, color: "#9a9aa3", marginTop: 4 }}>
                {progress && progress.total > 1
                  ? `Processando lote ${Math.min(progress.done + 1, progress.total)} de ${progress.total}`
                  : "A IA está identificando empresa, contato e estágio de cada linha"}
              </div>
              {progress && progress.total > 1 && (
                <div style={{ height: 6, borderRadius: 3, background: "#eef0f3", marginTop: 14, maxWidth: 240, marginLeft: "auto", marginRight: "auto" }}>
                  <div style={{ height: "100%", borderRadius: 3, background: "#6d5ef8", width: `${Math.round((progress.done / progress.total) * 100)}%`, transition: "width 0.2s ease" }} />
                </div>
              )}
            </div>
          )}

          {step === "review" && (
            <>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10, padding: "10px 14px", borderRadius: 10, background: "rgba(31,169,113,0.08)", border: "1px solid rgba(31,169,113,0.25)" }}>
                <CheckCircle2 size={16} color="#1fa971" />
                <span style={{ fontSize: 13, color: "#14532d", fontWeight: 600 }}>Confira e ajuste cada lead antes de importar - desmarque quem não quiser trazer.</span>
              </div>

              {errorMsg && (
                <div style={{ display: "flex", alignItems: "flex-start", gap: 10, padding: "10px 14px", borderRadius: 10, background: "rgba(245,166,35,0.1)", border: "1px solid rgba(245,166,35,0.3)", marginBottom: 10 }}>
                  <AlertCircle size={15} color="#b45309" style={{ flexShrink: 0, marginTop: 1 }} />
                  <div style={{ fontSize: 12, color: "#78350f" }}>{errorMsg}</div>
                </div>
              )}

              {duplicateCount > 0 && (
                <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12, padding: "9px 14px", borderRadius: 10, background: "rgba(245,166,35,0.08)", border: "1px solid rgba(245,166,35,0.25)" }}>
                  <AlertCircle size={14} color="#b45309" />
                  <span style={{ fontSize: 12, color: "#78350f" }}>{duplicateCount} lead{duplicateCount === 1 ? "" : "s"} com nome parecido a um que já existe no sistema - marcados abaixo, confira antes de importar.</span>
                </div>
              )}

              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
                <span style={{ fontSize: 12, color: "#64748b", fontWeight: 600 }}>{draftLeads.length} lead{draftLeads.length === 1 ? "" : "s"} encontrado{draftLeads.length === 1 ? "" : "s"}</span>
                <div style={{ display: "flex", gap: 10 }}>
                  <button onClick={() => toggleAll(true)} style={{ border: "none", background: "transparent", color: "#6d5ef8", fontSize: 12, fontWeight: 700, cursor: "pointer" }}>Marcar todos</button>
                  <button onClick={() => toggleAll(false)} style={{ border: "none", background: "transparent", color: "#94a3b8", fontSize: 12, fontWeight: 700, cursor: "pointer" }}>Desmarcar todos</button>
                </div>
              </div>

              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {draftLeads.map((l) => (
                  <div key={l._tmpId} style={{ display: "flex", gap: 10, padding: "12px 14px", borderRadius: 12, background: l._include ? "#fafbfc" : "#f4f4f6", border: `1px solid ${l._duplicate ? "rgba(245,166,35,0.4)" : "#eef0f3"}`, opacity: l._include ? 1 : 0.55 }}>
                    <input type="checkbox" checked={l._include} onChange={(e) => updateDraft(l._tmpId, { _include: e.target.checked })} style={{ marginTop: 6, width: 16, height: 16, flexShrink: 0, cursor: "pointer" }} />
                    <div style={{ flex: 1, display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
                      <div style={{ gridColumn: "1 / -1", display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                        <input value={l.company} onChange={(e) => updateDraft(l._tmpId, { company: e.target.value })} placeholder="Empresa" style={{ ...inputStyle, fontWeight: 700, flex: 1, minWidth: 140 }} />
                        {l._duplicate && <span title="Já existe um lead com esse nome" style={{ fontSize: 10, fontWeight: 700, color: "#b45309", background: "rgba(245,166,35,0.15)", padding: "3px 8px", borderRadius: 6, whiteSpace: "nowrap" }}>Já existe</span>}
                        {!l.company.trim() && <span style={{ fontSize: 10, fontWeight: 700, color: "#e2483f", background: "rgba(226,72,63,0.1)", padding: "3px 8px", borderRadius: 6, whiteSpace: "nowrap" }}>Nome obrigatório</span>}
                      </div>
                      <input value={l.contactName} onChange={(e) => updateDraft(l._tmpId, { contactName: e.target.value })} placeholder="Contato" style={inputStyle} />
                      <select value={l.owner} onChange={(e) => updateDraft(l._tmpId, { owner: e.target.value })} style={selectStyle}>
                        <option value="">Sem responsável</option>
                        {sdrs.map((s) => <option key={s.name} value={s.name}>{s.name}</option>)}
                      </select>
                      <input value={l.phone} onChange={(e) => updateDraft(l._tmpId, { phone: e.target.value })} placeholder="Telefone" style={inputStyle} />
                      <input value={l.email} onChange={(e) => updateDraft(l._tmpId, { email: e.target.value })} placeholder="Email" style={inputStyle} />
                      <input value={l.whatsapp} onChange={(e) => updateDraft(l._tmpId, { whatsapp: e.target.value })} placeholder="WhatsApp" style={inputStyle} />
                      <select value={l.stage} onChange={(e) => updateDraft(l._tmpId, { stage: e.target.value })} style={selectStyle}>
                        {STAGE_OPTIONS.map((s) => <option key={s} value={s}>{s}</option>)}
                      </select>
                      {l.feedback && <div style={{ gridColumn: "1 / -1", fontSize: 11.5, color: "#9a9aa3", fontStyle: "italic" }}>"{l.feedback}"</div>}
                    </div>
                    <button onClick={() => removeDraft(l._tmpId)} title="Remover da lista" style={{ border: "none", background: "transparent", color: "#c4c4cc", cursor: "pointer", flexShrink: 0 }}>
                      <Trash size={15} />
                    </button>
                  </div>
                ))}
              </div>
            </>
          )}
        </div>

        {step === "review" && (
          <div style={{ padding: "14px 22px", borderTop: "1px solid #f1f2f5", background: "#fafbfc" }}>
            {emptyNameIncludedCount > 0 && (
              <div style={{ fontSize: 11.5, color: "#e2483f", marginBottom: 8, textAlign: "right" }}>
                {emptyNameIncludedCount} lead{emptyNameIncludedCount === 1 ? "" : "s"} marcado{emptyNameIncludedCount === 1 ? "" : "s"} sem nome de empresa - preencha ou desmarque antes de importar.
              </div>
            )}
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <button onClick={() => setStep("input")} style={{ padding: "9px 14px", borderRadius: 10, border: "1px solid #e2e4e9", background: "white", color: "#64748b", fontSize: 12.5, fontWeight: 600, cursor: "pointer" }}>
                Voltar
              </button>
              <button
                onClick={() => { onConfirm(draftLeads.filter((l) => l._include && l.company.trim())); onClose(); }}
                disabled={validIncludedCount === 0}
                style={{ padding: "11px 22px", borderRadius: 11, border: "none", cursor: validIncludedCount ? "pointer" : "not-allowed", fontSize: 13.5, fontWeight: 800, background: validIncludedCount ? "linear-gradient(135deg, #1fa971, #059669)" : "#eef0f3", color: validIncludedCount ? "white" : "#b4b6bc", display: "flex", alignItems: "center", gap: 8 }}
              >
                <Upload size={14} /> Importar {validIncludedCount} lead{validIncludedCount === 1 ? "" : "s"}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

const MeetingListItem = ({ meeting, onOpen }) => {
  const cfg = MEETING_TYPES[meeting.type];
  const Icon = cfg.icon;
  const time = new Date(meeting.date).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });
  const endTime = new Date(new Date(meeting.date).getTime() + meeting.duration * 60000).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });

  // A ação do botão tem apenas 3 opções possíveis, definidas pela tag da reunião:
  // Ligação (tipos de chamada) · Meet (online) · Presencial (endereço)
  const isCallType = meeting.type === "followup" || meeting.type === "ligacao";
  const actionMeta = isCallType
    ? { label: "Ligação", icon: Phone }
    : meeting.locationType === "presencial"
    ? { label: "Presencial", icon: Users2 }
    : { label: "Meet", icon: Video };

  const handleAction = (e) => {
    e.stopPropagation();
    if (isCallType) { onOpen(meeting); return; }
    if (meeting.locationType === "online" && meeting.link) { window.open(meeting.link, "_blank"); return; }
    onOpen(meeting);
  };

  return (
    <div style={{ display: "flex", alignItems: "stretch", gap: 12, marginBottom: 10 }}>
      <div style={{ width: 4, borderRadius: 4, background: cfg.color, flexShrink: 0 }} />
      <Glass style={{ flex: 1, borderRadius: 14, padding: "12px 16px", display: "flex", alignItems: "center", gap: 12, cursor: "pointer" }} onClick={() => onOpen(meeting)}>
        <div style={{ minWidth: 62 }}>
          <div style={{ fontSize: 13, fontWeight: 700, color: "#0f172a" }}>{time}</div>
          <div style={{ fontSize: 10.5, color: "#94a3b8" }}>– {endTime}</div>
        </div>
        <div style={{ width: 34, height: 34, borderRadius: 10, background: cfg.color + "18", color: cfg.color, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          <Icon size={16} />
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 13.5, fontWeight: 700, color: cfg.color }}>{cfg.label}</div>
          <div style={{ fontSize: 13, color: "#334155", fontWeight: 600, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{meeting.company}</div>
          <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
            <span style={{ fontSize: 11, color: "#94a3b8" }}>SDR: {meeting.owner}</span>
            <span style={{ fontSize: 10, color: "#cbd5e1" }}>·</span>
            <span style={{ fontSize: 10.5, fontWeight: 700, color: meeting.locationType === "presencial" ? "#b45309" : "#4f46e5", display: "inline-flex", alignItems: "center", gap: 3 }}>
              {meeting.locationType === "presencial" ? <><Users2 size={10} /> Presencial</> : <><Video size={10} /> Online</>}
            </span>
          </div>
        </div>
        <button
          onClick={handleAction}
          style={{ padding: "8px 14px", borderRadius: 10, border: "none", background: cfg.color + "18", color: cfg.color, fontSize: 12, fontWeight: 700, cursor: "pointer", display: "flex", alignItems: "center", gap: 6, whiteSpace: "nowrap" }}
        >
          <actionMeta.icon size={13} /> {actionMeta.label}
        </button>
      </Glass>
    </div>
  );
};

// Modal de detalhe/edição de reunião - data/hora, o que levar, quem participa dos dois lados
const MeetingDetail = ({ meeting, leads, onClose, onSave, onDelete, sdrs }) => {
  const [draft, setDraft] = useState(meeting);
  const [confirmDelete, setConfirmDelete] = useState(false);
  useEffect(() => { setDraft(meeting); setConfirmDelete(false); }, [meeting]);
  if (!draft) return null;
  const update = (patch) => setDraft((d) => ({ ...d, ...patch }));
  const cfg = MEETING_TYPES[draft.type];
  // Mesmo cuidado do modal de lead: não descartar edições em silêncio.
  const isDirty = JSON.stringify(draft) !== JSON.stringify(meeting);
  const handleClose = () => {
    if (isDirty && !window.confirm("Você tem alterações não salvas nesta reunião. Sair sem salvar?")) return;
    onClose();
  };

  return (
    <div onClick={handleClose} style={{ position: "fixed", inset: 0, background: "rgba(30, 20, 60, 0.4)", backdropFilter: "blur(8px)", zIndex: 100, display: "flex", alignItems: "flex-start", justifyContent: "center", padding: "5vh 20px", overflowY: "auto", animation: "fadeIn 0.22s ease" }}>
      <div onClick={(e) => e.stopPropagation()} style={{ width: "100%", maxWidth: 560, background: "rgba(255,255,255,0.92)", backdropFilter: "blur(40px) saturate(160%)", borderRadius: 24, border: "1px solid rgba(255,255,255,0.9)", boxShadow: "0 30px 90px -20px rgba(76,29,149,0.35)", overflow: "hidden", animation: "slideUp 0.3s cubic-bezier(0.4,0,0.2,1)" }}>
        <div style={{ padding: "22px 26px", borderBottom: "1px solid rgba(148,163,184,0.15)", display: "flex", justifyContent: "space-between", alignItems: "center", background: `linear-gradient(135deg, ${cfg.color}18, transparent)` }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <div style={{ width: 36, height: 36, borderRadius: 10, background: cfg.color + "22", color: cfg.color, display: "flex", alignItems: "center", justifyContent: "center" }}><cfg.icon size={18} /></div>
            <div>
              <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 18, fontWeight: 500, color: "#0f172a" }}>{draft.company}</div>
              <div style={{ fontSize: 11.5, color: "#94a3b8" }}>{cfg.label}</div>
            </div>
          </div>
          <button onClick={handleClose} style={{ width: 32, height: 32, borderRadius: 10, border: "1px solid rgba(148,163,184,0.25)", background: "white", color: "#64748b", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}><X size={16} /></button>
        </div>

        <div style={{ padding: "20px 26px", maxHeight: "60vh", overflowY: "auto" }}>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 16 }}>
            <div>
              <span style={{ fontSize: 10, color: "#94a3b8", marginBottom: 3, display: "block", fontWeight: 700, textTransform: "uppercase" }}>Data</span>
              <input type="date" value={draft.date.slice(0, 10)} onChange={(e) => { const time = draft.date.slice(11, 16); update({ date: new Date(`${e.target.value}T${time}`).toISOString() }); }} style={inputStyle} />
            </div>
            <div>
              <span style={{ fontSize: 10, color: "#94a3b8", marginBottom: 3, display: "block", fontWeight: 700, textTransform: "uppercase" }}>Horário</span>
              <input type="time" value={draft.date.slice(11, 16)} onChange={(e) => { const day = draft.date.slice(0, 10); update({ date: new Date(`${day}T${e.target.value}`).toISOString() }); }} style={inputStyle} />
            </div>
          </div>

          <div style={{ marginBottom: 16 }}>
            <LabelWithHint hint="Escolha uma das duas opções - o campo certo aparece conforme a escolha">Local da reunião</LabelWithHint>
            <div style={{ display: "flex", gap: 6, marginBottom: 10 }}>
              <button onClick={() => update({ locationType: "online" })} style={{ flex: 1, padding: "8px 10px", borderRadius: 10, border: `1px solid ${draft.locationType !== "presencial" ? "#6366f1" : "rgba(148,163,184,0.25)"}`, background: draft.locationType !== "presencial" ? "rgba(99,102,241,0.1)" : "white", color: draft.locationType !== "presencial" ? "#4f46e5" : "#64748b", fontSize: 12, fontWeight: 700, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
                <Video size={13} /> Online
              </button>
              <button onClick={() => update({ locationType: "presencial" })} style={{ flex: 1, padding: "8px 10px", borderRadius: 10, border: `1px solid ${draft.locationType === "presencial" ? "#f59e0b" : "rgba(148,163,184,0.25)"}`, background: draft.locationType === "presencial" ? "rgba(245,158,11,0.1)" : "white", color: draft.locationType === "presencial" ? "#b45309" : "#64748b", fontSize: 12, fontWeight: 700, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
                <Users2 size={13} /> Presencial
              </button>
            </div>
            {draft.locationType === "presencial" ? (
              <input value={draft.address || ""} onChange={(e) => update({ address: e.target.value })} placeholder="Endereço completo - rua, número, cidade" style={inputStyle} />
            ) : (
              <input value={draft.link || ""} onChange={(e) => update({ link: e.target.value })} placeholder="https://meet.google.com/xxx-xxxx-xxx" style={inputStyle} />
            )}
          </div>

          <div style={{ marginBottom: 16 }}>
            <label style={labelStyle}>Tipo</label>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              {Object.entries(MEETING_TYPES).map(([key, t]) => {
                const active = draft.type === key;
                return (
                  <button key={key} onClick={() => update({ type: key })} style={{ padding: "7px 11px", borderRadius: 9, border: `1px solid ${active ? t.color : "rgba(148,163,184,0.25)"}`, background: active ? t.color + "18" : "white", color: active ? t.color : "#64748b", fontSize: 11.5, fontWeight: active ? 700 : 500, cursor: "pointer", display: "flex", alignItems: "center", gap: 5 }}>
                    <t.icon size={12} /> {t.label}
                  </button>
                );
              })}
            </div>
          </div>

          <div style={{ marginBottom: 16 }}>
            <label style={labelStyle}>Empresa (lead)</label>
            <select value={draft.company} onChange={(e) => update({ company: e.target.value })} style={selectStyle}>
              {leads.map((l) => <option key={l.id} value={l.company}>{l.company}</option>)}
            </select>
          </div>

          <div style={{ marginBottom: 16 }}>
            <LabelWithHint hint="Materiais, documentos ou informações para preparar antes da reunião">O que levar</LabelWithHint>
            <textarea value={draft.materials || ""} onChange={(e) => update({ materials: e.target.value })} placeholder="Ex: proposta comercial, case de sucesso, tabela de preços..." style={{ ...inputStyle, minHeight: 56, resize: "vertical", fontFamily: "inherit" }} />
          </div>

          <div>
            <label style={labelStyle}>Participantes</label>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
              <div style={{ padding: "10px 12px", borderRadius: 12, background: "rgba(99, 102, 241, 0.08)", border: "1px solid rgba(99, 102, 241, 0.2)" }}>
                <span style={{ fontSize: 10.5, fontWeight: 700, color: "#6366f1", textTransform: "uppercase", letterSpacing: 0.5 }}>Nosso lado</span>
                <select value={draft.ourAttendee} onChange={(e) => update({ ourAttendee: e.target.value })} style={{ ...selectStyle, marginTop: 6, background: "white" }}>
                  {sdrs.map((s) => <option key={s.name}>{s.name}</option>)}
                </select>
              </div>
              <div style={{ padding: "10px 12px", borderRadius: 12, background: "rgba(245, 158, 11, 0.08)", border: "1px solid rgba(245, 158, 11, 0.2)" }}>
                <span style={{ fontSize: 10.5, fontWeight: 700, color: "#b45309", textTransform: "uppercase", letterSpacing: 0.5 }}>Lado do cliente</span>
                <input value={draft.theirAttendee || ""} onChange={(e) => update({ theirAttendee: e.target.value })} placeholder="Nome / cargo" style={{ ...inputStyle, marginTop: 6, background: "white" }} />
              </div>
            </div>
          </div>
        </div>

        <div style={{ padding: "16px 26px", borderTop: "1px solid rgba(148,163,184,0.15)", background: "rgba(248,250,252,0.6)", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          {confirmDelete ? (
            <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
              <span style={{ fontSize: 13, color: "#64748b" }}>Confirmar exclusão?</span>
              <button onClick={() => onDelete(draft.id)} style={{ padding: "6px 12px", borderRadius: 8, border: "none", background: "#ef4444", color: "white", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>Sim, excluir</button>
              <button onClick={() => setConfirmDelete(false)} style={{ padding: "6px 12px", borderRadius: 8, border: "1px solid rgba(148,163,184,0.25)", background: "transparent", color: "#64748b", fontSize: 12, cursor: "pointer" }}>Cancelar</button>
            </div>
          ) : (
            <button onClick={() => setConfirmDelete(true)} style={{ padding: "8px 12px", borderRadius: 10, border: "none", background: "transparent", color: "#94a3b8", fontSize: 13, cursor: "pointer", display: "flex", alignItems: "center", gap: 6 }}><Trash2 size={14} /> Excluir</button>
          )}
          <button onClick={() => { onSave(draft); onClose(); }} style={{ padding: "10px 22px", borderRadius: 12, border: "none", background: "linear-gradient(135deg, #6366f1, #8b5cf6)", color: "white", fontSize: 13, fontWeight: 700, cursor: "pointer", boxShadow: "0 8px 22px -8px rgba(99,102,241,0.5)" }}>Salvar reunião</button>
        </div>
      </div>
    </div>
  );
};

// Central de notificações: junta tudo que precisa de atenção (negociações antigas,
// leads quentes esfriando, reuniões próximas e a lista da semana ainda pendente),
// cada bloco levando direto pra tela certa.
const NotificationsPanel = ({ stats, onClose, onNavigate }) => {
  const meetingsSoon = stats.upcomingMeetings.filter((m) => {
    const d = new Date(m.date);
    const in48h = new Date(Date.now() + 48 * 3600 * 1000);
    return d <= in48h;
  }).slice(0, 3);

  const items = [
    {
      key: "desatendidos", count: stats.desatendidos.length, icon: Clock, color: "#e2483f",
      title: "Negociações antigas", desc: "leads parados há muito tempo sem contato", view: "desatendidos",
    },
    {
      key: "hot", count: stats.hotNoContact.length, icon: Flame, color: "#f0431f",
      title: "Leads quentes esfriando", desc: "sem contato há 3+ dias, risco de perder", view: "dashboard",
    },
    {
      key: "week", count: stats.weekList.length, icon: Target, color: "#6d5ef8",
      title: "Marcados pra essa semana", desc: "ainda não foram abordados", view: "semana",
    },
    {
      key: "meetings", count: meetingsSoon.length, icon: CalendarIcon, color: "#3b82f6",
      title: "Reuniões nas próximas 48h", desc: meetingsSoon.map((m) => m.company).join(", ") || "nenhuma agendada", view: "agenda",
    },
  ];
  const totalPending = items.reduce((sum, it) => sum + it.count, 0);

  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(20,10,40,0.4)", backdropFilter: "blur(6px)", zIndex: 300, display: "flex", alignItems: "flex-end", justifyContent: "center", animation: "fadeIn 0.2s ease" }}>
      <div onClick={(e) => e.stopPropagation()} style={{ width: "100%", maxWidth: 480, maxHeight: "82vh", overflowY: "auto", background: "white", borderRadius: "24px 24px 0 0", padding: 22, animation: "slideUp 0.25s cubic-bezier(0.4,0,0.2,1)" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 4 }}>
          <h2 style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 19, fontWeight: 800, margin: 0, color: "#14141a" }}>Notificações</h2>
          <button onClick={onClose} style={{ width: 32, height: 32, borderRadius: 10, border: "1px solid #eef0f3", background: "white", color: "#64748b", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}><X size={16} /></button>
        </div>
        <div style={{ fontSize: 12.5, color: "#9a9aa3", marginBottom: 18 }}>
          {totalPending === 0 ? "Tudo em dia por aqui." : `${totalPending} coisa${totalPending === 1 ? "" : "s"} pedindo atenção`}
        </div>

        {items.filter((it) => it.count > 0).length === 0 ? (
          <div style={{ textAlign: "center", padding: "30px 10px", color: "#9a9aa3", fontSize: 13 }}>
            🎉 Sem pendências agora. Funil em dia!
          </div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {items.filter((it) => it.count > 0).map((it) => (
              <div
                key={it.key}
                onClick={() => onNavigate(it.view)}
                style={{ display: "flex", alignItems: "center", gap: 12, padding: "13px 14px", borderRadius: 16, background: "#f8fafc", border: "1px solid #eef0f3", cursor: "pointer" }}
              >
                <div style={{ width: 40, height: 40, borderRadius: 12, background: it.color + "18", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                  <it.icon size={18} color={it.color} />
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 7 }}>
                    <span style={{ fontSize: 13.5, fontWeight: 700, color: "#14141a" }}>{it.title}</span>
                    <span style={{ fontSize: 10.5, fontWeight: 800, color: "white", background: it.color, padding: "1px 7px", borderRadius: 10 }}>{it.count}</span>
                  </div>
                  <div style={{ fontSize: 11.5, color: "#9a9aa3", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{it.desc}</div>
                </div>
                <ChevronRight size={16} color="#c4c4cc" style={{ flexShrink: 0 }} />
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

// ════════════════════════════════════════════════════════════════════════
// APP
// ════════════════════════════════════════════════════════════════════════

export default function CRM({ authMembers = [], onSyncMemberAvatar, currentUserId, workspaceName, onSwitchWorkspace } = {}) {
  const [view, setView] = useState("dashboard"); // dashboard | desatendidos | semana | agenda
  const [leads, setLeads] = useState([]);
  const [meetings, setMeetings] = useState([]);
  const [sdrs, setSdrs] = useState(seedSDRs);
  const [weeklyGoal, setWeeklyGoal] = useState(DEFAULT_WEEKLY_GOAL);
  const [editingGoal, setEditingGoal] = useState(false);
  const [revenueGoal, setRevenueGoal] = useState(DEFAULT_REVENUE_GOAL);
  const [editingRevenueGoal, setEditingRevenueGoal] = useState(false);
  const [reportPeriod, setReportPeriod] = useState("all"); // all | 7 | 30 | 90
  const [wonPeriod, setWonPeriod] = useState("all"); // all | 30 | 90 | 365
  const [goalsConfig, setGoalsConfig] = useState(DEFAULT_GOALS_CONFIG);
  const [earnedBadges, setEarnedBadges] = useState([]); // [{id, sdrName, metric, tier, periodKey, earnedAt}]
  const [badgeQueue, setBadgeQueue] = useState([]); // fila de pop-ups de badge pra mostrar um de cada vez
  const [achievementsFilterSdr, setAchievementsFilterSdr] = useState("all");
  const [expandedHistoryMetric, setExpandedHistoryMetric] = useState(null);
  const [loaded, setLoaded] = useState(false);

  const [search, setSearch] = useState("");
  const [tempFilter, setTempFilter] = useState("all");
  const [whatsappOnly, setWhatsappOnly] = useState(false);
  const [ownerFilter, setOwnerFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [phaseFilter, setPhaseFilter] = useState("all");
  const [quickStage, setQuickStage] = useState(null); // null | "ativo" - filtro rápido no dashboard
  const [superOnly, setSuperOnly] = useState(false);
  const [originFilter, setOriginFilter] = useState("all");
  const [originDropdownOpen, setOriginDropdownOpen] = useState(false);
  const [chatMessages, setChatMessages] = useState([]); // [{role:'user'|'assistant', content}]
  const [chatInput, setChatInput] = useState("");
  const [chatLoading, setChatLoading] = useState(false);
  const [chatError, setChatError] = useState("");
  const [showSdrManager, setShowSdrManager] = useState(false);
  const [showImportModal, setShowImportModal] = useState(false);
  const [showBulkPhoneModal, setShowBulkPhoneModal] = useState(false);
  const [showMenu, setShowMenu] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);

  const [selected, setSelected] = useState(null);
  const [quickContactLead, setQuickContactLead] = useState(null);
  const [waSendList, setWaSendList] = useState([]); // { leadId, message }[]
  const [scriptPickerLead, setScriptPickerLead] = useState(null);
  const [waSendHistory, setWaSendHistory] = useState([]);
  const [weekHistory, setWeekHistory] = useState([]);
  const [showWeekHistory, setShowWeekHistory] = useState(false);
  const [showWaSendScreen, setShowWaSendScreen] = useState(false);
  const [selectedMeeting, setSelectedMeeting] = useState(null);
  const [toast, setToast] = useState("");

  const [agendaDate, setAgendaDate] = useState(new Date());
  const [monthExpanded, setMonthExpanded] = useState(false);

  // Sincroniza as cores dos SDRs (usadas por OwnerAvatar/cards) com a lista editável
  RESPONSIBLE_COLORS = Object.fromEntries(sdrs.map((s) => [s.name, s.color]));

  // Cada pessoa tem sua própria conversa com o assistente - antes era uma só compartilhada
  // por todo o funil, o que fazia mensagens de gente diferente se misturarem/sobrescreverem.
  const chatHistoryKey = currentUserId ? `${CHAT_HISTORY_KEY}:${currentUserId}` : CHAT_HISTORY_KEY;

  useEffect(() => {
    let mounted = true;
    Promise.all([
      loadData(LEADS_KEY, seedLeads), loadData(MEETINGS_KEY, seedMeetings), loadData(SDRS_KEY, seedSDRs),
      loadData(WEEKLY_GOAL_KEY, DEFAULT_WEEKLY_GOAL), loadData(REVENUE_GOAL_KEY, DEFAULT_REVENUE_GOAL),
      loadData(GOALS_CONFIG_KEY, DEFAULT_GOALS_CONFIG), loadData(BADGES_KEY, []), loadData(chatHistoryKey, []),
      loadData(WA_SEND_HISTORY_KEY, []), loadData(WEEK_HISTORY_KEY, []),
    ]).then(([l, m, s, g, rg, gc, badges, chatHistory, waHistory, weekHist]) => {
      if (mounted) {
        setLeads(l); setMeetings(m); setSdrs(s && s.length ? s : seedSDRs);
        setWeeklyGoal(typeof g === "number" && g > 0 ? g : DEFAULT_WEEKLY_GOAL);
        setRevenueGoal(typeof rg === "number" && rg > 0 ? rg : DEFAULT_REVENUE_GOAL);
        setGoalsConfig(gc && typeof gc === "object" ? { ...DEFAULT_GOALS_CONFIG, ...gc } : DEFAULT_GOALS_CONFIG);
        setEarnedBadges(Array.isArray(badges) ? badges : []);
        setChatMessages(Array.isArray(chatHistory) ? chatHistory : []);
        setWaSendHistory(Array.isArray(waHistory) ? waHistory : []);
        setWeekHistory(Array.isArray(weekHist) ? weekHist : []);
        setLoaded(true);
      }
    });
    return () => { mounted = false; };
  }, []);
  useEffect(() => { if (loaded) saveData(LEADS_KEY, leads); }, [leads, loaded]);
  useEffect(() => { if (loaded) saveData(MEETINGS_KEY, meetings); }, [meetings, loaded]);
  useEffect(() => { if (loaded) saveData(SDRS_KEY, sdrs); }, [sdrs, loaded]);
  useEffect(() => { if (loaded) saveData(WEEKLY_GOAL_KEY, weeklyGoal); }, [weeklyGoal, loaded]);
  useEffect(() => { if (loaded) saveData(REVENUE_GOAL_KEY, revenueGoal); }, [revenueGoal, loaded]);
  useEffect(() => { if (loaded) saveData(GOALS_CONFIG_KEY, goalsConfig); }, [goalsConfig, loaded]);
  useEffect(() => { if (loaded) saveData(BADGES_KEY, earnedBadges); }, [earnedBadges, loaded]);
  useEffect(() => { if (loaded) saveData(chatHistoryKey, chatMessages); }, [chatMessages, loaded]);
  useEffect(() => { if (loaded) saveData(WA_SEND_HISTORY_KEY, waSendHistory); }, [waSendHistory, loaded]);
  useEffect(() => { if (loaded) saveData(WEEK_HISTORY_KEY, weekHistory); }, [weekHistory, loaded]);
  useEffect(() => { if (toast) { const t = setTimeout(() => setToast(""), 2400); return () => clearTimeout(t); } }, [toast]);

  // Registra no histórico persistente (dura semanas/meses, não só a semana atual)
  // toda vez que uma tarefa da semana é marcada como concluída, e por qual canal.
  const logWeekHistory = (lead, via) => {
    setWeekHistory((prev) => [{ id: "wk_" + Date.now() + "_" + lead.id, leadId: lead.id, company: lead.company, owner: lead.owner, via, date: new Date().toISOString() }, ...prev].slice(0, 500));
  };

  // Detecta automaticamente quando um SDR bate um nível de meta (bronze/prata/ouro) e credita a badge.
  // Roda sempre que leads/reuniões/config de metas/SDRs mudam.
  useEffect(() => {
    if (!loaded) return;
    const newlyEarned = [];
    METRIC_KEYS.forEach((metricKey) => {
      const cfg = goalsConfig[metricKey];
      if (!cfg || !cfg.enabled || !cfg.target) return;
      const bounds = getPeriodBounds(cfg.period);
      sdrs.forEach((sdr) => {
        const value = computeMetricValue(metricKey, sdr.name, bounds, leads, meetings);
        BADGE_TIERS.forEach((tier) => {
          const threshold = cfg.target * tier.pct;
          if (value < threshold) return;
          const badgeId = `${sdr.name}__${metricKey}__${tier.key}__${bounds.key}`;
          const already = earnedBadges.some((b) => b.id === badgeId);
          if (!already) {
            newlyEarned.push({ id: badgeId, sdrName: sdr.name, metric: metricKey, tier: tier.key, periodKey: bounds.key, period: cfg.period, earnedAt: new Date().toISOString(), value: Math.round(value), target: cfg.target });
          }
        });
      });
    });
    if (newlyEarned.length > 0) {
      setEarnedBadges((prev) => [...prev, ...newlyEarned]);
      setBadgeQueue((prev) => [...prev, ...newlyEarned]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loaded, leads, meetings, goalsConfig, sdrs]);

  // Quem está perto de bater alguma meta ativa (>=85% e ainda não bateu) - usado pra dar um empurrãozinho
  // no dashboard, já que hoje as metas só aparecem se o usuário for até a página delas.
  const almostThereGoals = useMemo(() => {
    const found = [];
    METRIC_KEYS.forEach((metricKey) => {
      const cfg = goalsConfig[metricKey];
      if (!cfg || !cfg.enabled || !cfg.target) return;
      const bounds = getPeriodBounds(cfg.period);
      sdrs.forEach((sdr) => {
        const value = computeMetricValue(metricKey, sdr.name, bounds, leads, meetings);
        const pct = value / cfg.target;
        if (pct >= 0.85 && pct < 1) {
          found.push({ sdrName: sdr.name, metricLabel: METRIC_DEFS[metricKey].shortLabel, value, target: cfg.target, pct });
        }
      });
    });
    return found.sort((a, b) => b.pct - a.pct);
  }, [leads, meetings, goalsConfig, sdrs]);

  const addSdr = (name) => {
    const trimmed = name.trim();
    if (!trimmed || sdrs.some((s) => s.name.toLowerCase() === trimmed.toLowerCase())) return;
    const color = SDR_PALETTE[sdrs.length % SDR_PALETTE.length];
    setSdrs((prev) => [...prev, { name: trimmed, color }]);
  };
  // Remover um SDR não pode deixar leads/reuniões "órfãos" apontando pra um nome que não existe
  // mais. Se reassignTo for passado, tudo que era dele passa pro novo SDR antes de remover.
  const removeSdr = (name, reassignTo) => {
    if (sdrs.length <= 1) return; // sempre precisa sobrar ao menos 1
    if (reassignTo) {
      setLeads((prev) => prev.map((l) => (l.owner === name ? { ...l, owner: reassignTo } : l)));
      setMeetings((prev) => prev.map((m) => (m.owner === name ? { ...m, owner: reassignTo } : m)));
    }
    setSdrs((prev) => prev.filter((s) => s.name !== name));
  };

  // Envia a foto pro Supabase Storage e guarda a URL pública no registro do SDR
  const updateSdrAvatar = async (name, file) => {
    try {
      const ext = file.name.split(".").pop() || "jpg";
      const path = `${Date.now()}_${name.replace(/[^a-zA-Z0-9]/g, "")}.${ext}`;
      const { error: uploadError } = await supabase.storage.from("avatars").upload(path, file, { upsert: true });
      if (uploadError) { setToast("Não consegui enviar a foto. Tente outro arquivo."); return; }
      const { data } = supabase.storage.from("avatars").getPublicUrl(path);
      setSdrs((prev) => prev.map((s) => (s.name === name ? { ...s, avatarUrl: data.publicUrl } : s)));
      // Se esse nome bater com alguém que tem login de verdade no funil, a foto
      // já fica sincronizada lá também - não fica presa só nessa lista local.
      if (onSyncMemberAvatar && authMembers.some((m) => m.display_name.toLowerCase() === name.toLowerCase())) {
        onSyncMemberAvatar(name, data.publicUrl);
      }
      setToast("Foto atualizada!");
    } catch {
      setToast("Não consegui enviar a foto. Tente de novo.");
    }
  };

  // Adiciona de uma vez qualquer pessoa que já tem login no funil mas ainda não
  // está na lista de SDRs (então não consegue receber leads atribuídos a ela).
  const syncSdrsWithAuthMembers = () => {
    const missing = authMembers.filter((m) => !sdrs.some((s) => s.name.toLowerCase() === m.display_name.toLowerCase()));
    if (missing.length === 0) { setToast("Já está tudo sincronizado."); return; }
    setSdrs((prev) => [
      ...prev,
      ...missing.map((m, i) => ({ name: m.display_name, color: m.color || SDR_PALETTE[(prev.length + i) % SDR_PALETTE.length], avatarUrl: m.avatar_url || undefined })),
    ]);
    setToast(`${missing.length} pessoa${missing.length === 1 ? "" : "s"} adicionada${missing.length === 1 ? "" : "s"}.`);
  };

  const updateLead = (updated) => setLeads((prev) => prev.map((l) => (l.id === updated.id ? updated : l)));
  const markContactedToday = (id) => setLeads((prev) => prev.map((l) => (l.id === id ? { ...l, lastContact: new Date().toISOString() } : l)));

  const sendChatMessage = async (text) => {
    const trimmed = text.trim();
    if (!trimmed || chatLoading) return;
    setChatError("");
    const userMsg = { role: "user", content: trimmed, ts: new Date().toISOString() };
    const historyForApi = chatMessages.map((m) => ({ role: m.role, content: m.content }));
    setChatMessages((prev) => [...prev, userMsg]);
    setChatInput("");
    setChatLoading(true);
    try {
      const context = buildFunnelContext(leads, meetings, sdrs, weeklyGoal);
      const reply = await askFunnelAssistant(context, historyForApi, trimmed);
      setChatMessages((prev) => [...prev, { role: "assistant", content: reply, ts: new Date().toISOString() }]);
    } catch (err) {
      // Só mostramos na tela mensagens de erro que a gente mesmo escreveu (err.friendly).
      // Qualquer outra coisa (exceção crua do navegador, tipo "The string did not match
      // the expected pattern") fica só no console, o usuário vê uma mensagem normal.
      if (err && err.friendly) setChatError(err.message);
      else { console.error("Erro inesperado no assistente:", err); setChatError("Algo deu errado por aqui. Tente novamente em alguns instantes."); }
    } finally {
      setChatLoading(false);
    }
  };
  const deleteLead = (id) => { setLeads((prev) => prev.filter((l) => l.id !== id)); setSelected(null); };
  const toggleWeekDone = (id) => {
    const lead = leads.find((l) => l.id === id);
    const willBeDone = lead && !lead.weekDone;
    setLeads((prev) => prev.map((l) => (l.id === id ? { ...l, weekDone: !l.weekDone, weekDoneVia: !l.weekDone ? "manual" : l.weekDoneVia } : l)));
    if (willBeDone) logWeekHistory(lead, "manual");
  };
  const toggleSuperAttention = (id) => setLeads((prev) => prev.map((l) => (l.id === id ? { ...l, superAttention: !l.superAttention } : l)));
  const setWeekTag = (id, tag) => setLeads((prev) => prev.map((l) => (l.id === id ? { ...l, weekTag: tag, weekDone: tag ? false : l.weekDone } : l)));
  const toggleWeekFlag = (id) => setLeads((prev) => prev.map((l) => (l.id === id ? { ...l, weekTag: l.weekTag && !l.weekDone ? null : "semana", weekDone: false } : l)));

  const createLead = () => {
    const newLead = { id: "l_" + Date.now(), company: "Nova Empresa", owner: sdrs[0]?.name || "", stage: "Apresentação", feedback: "", status: "Atendido", contactName: "", email: "", phone: "", whatsapp: "", hasWhatsapp: false, hasEmail: false, hasPhone: false, phase: "none", temperature: "warm", lastContact: null, nextAction: null, weekDone: false, weekTag: null, superAttention: false, wonDate: null, dealValue: null, dealType: "unico", contractPeriod: "mensal", origin: null, createdAt: new Date().toISOString(), notes: [] };
    setLeads((prev) => [newLead, ...prev]);
    setSelected(newLead);
  };

  // Confirma a importação: transforma os leads revisados/editados em leads reais do sistema
  const confirmImport = (importedDrafts) => {
    const now = new Date().toISOString();
    const batchStamp = Date.now();
    const newLeads = importedDrafts.map((d, i) => ({
      id: "l_imp_" + batchStamp + "_" + i,
      company: d.company,
      owner: d.owner || sdrs[0]?.name || "",
      stage: d.stage,
      feedback: d.feedback || "",
      status: "Atendido",
      contactName: d.contactName || "",
      email: d.email || "",
      phone: d.phone || "",
      whatsapp: d.whatsapp || "",
      hasWhatsapp: !!d.whatsapp,
      hasEmail: !!d.email,
      hasPhone: !!d.phone,
      phase: inferPhase(d.stage, d.feedback),
      temperature: inferTemperature(d.stage, d.feedback),
      lastContact: null,
      nextAction: null,
      weekDone: false,
      weekTag: null,
      superAttention: false,
      wonDate: d.stage === "Conquistado" ? now : null,
      dealValue: null,
      dealType: "unico",
      contractPeriod: "mensal",
      origin: null,
      createdAt: now,
      notes: d.feedback ? [{ id: "n_imp_" + batchStamp + "_" + i, date: now, text: `[Importado] ${d.feedback}` }] : [],
    }));
    setLeads((prev) => [...newLeads, ...prev]);
    setToast(`${newLeads.length} lead${newLeads.length === 1 ? "" : "s"} importado${newLeads.length === 1 ? "" : "s"} com sucesso`);
  };

  // Aplica telefones em massa: cada item já vem casado com o lead certo (feito no
  // modal), aqui é só gravar o whatsapp/telefone e registrar uma nota no histórico.
  const applyBulkPhones = (items) => {
    if (items.length === 0) return;
    const byId = Object.fromEntries(items.map((i) => [i.leadId, i.phoneDigits]));
    const now = new Date().toISOString();
    setLeads((prev) => prev.map((l) => {
      const newPhone = byId[l.id];
      if (!newPhone) return l;
      return {
        ...l,
        whatsapp: newPhone,
        hasWhatsapp: true,
        notes: [{ id: "n_bulk_" + Date.now() + "_" + l.id, date: now, text: `[Atualização em massa] WhatsApp definido para ${newPhone}` }, ...(l.notes || [])],
      };
    }));
    setToast(`${items.length} telefone${items.length === 1 ? "" : "s"} atualizado${items.length === 1 ? "" : "s"}`);
  };

  const handleQuickContact = (type, lead) => {
    dispatchContact(type, lead, (id) => {
      setLeads((prev) => prev.map((l) => l.id === id ? {
        ...l,
        lastContact: new Date().toISOString(),
        // Falar com o lead por qualquer canal já resolve a tarefa da semana automaticamente -
        // antes ficava esquisito: você conversava, mas a Lista da Semana continuava mostrando pendente.
        weekDone: l.weekTag ? true : l.weekDone,
        weekDoneVia: (l.weekTag && !l.weekDone) ? type : l.weekDoneVia,
        notes: [{ id: "n_" + Date.now(), date: new Date().toISOString(), text: `Contato via ${type === "whatsapp" ? "WhatsApp" : type === "email" ? "Email" : "Telefone"}` }, ...(l.notes || [])],
      } : l));
      if (lead.weekTag && !lead.weekDone) { setToast("Marcado como feito na Lista da Semana também!"); logWeekHistory(lead, type); }
    });
  };

  // Toca no aviãozinho: se o lead já está na fila, remove direto. Se não está,
  // abre a tela de escolha de script em vez de adicionar com mensagem genérica.
  const handlePaperPlaneClick = (lead) => {
    if (waSendList.some((x) => x.leadId === lead.id)) {
      setWaSendList((prev) => prev.filter((x) => x.leadId !== lead.id));
    } else {
      setScriptPickerLead(lead);
    }
  };

  const addToWaListWithScript = (message) => {
    if (!scriptPickerLead) return;
    setWaSendList((prev) => [...prev.filter((x) => x.leadId !== scriptPickerLead.id), { leadId: scriptPickerLead.id, message }]);
    setScriptPickerLead(null);
    setToast("Adicionado à lista de envio!");
  };

  const editWaListMessage = (leadId, message) => {
    setWaSendList((prev) => prev.map((x) => (x.leadId === leadId ? { ...x, message } : x)));
    setToast("Mensagem atualizada!");
  };

  const logWaListSend = (leadId, message) => {
    const now = new Date().toISOString();
    const lead = leads.find((l) => l.id === leadId);
    setLeads((prev) => prev.map((l) => l.id === leadId ? {
      ...l,
      lastContact: now,
      weekDone: l.weekTag ? true : l.weekDone,
      weekDoneVia: (l.weekTag && !l.weekDone) ? "whatsapp-lista" : l.weekDoneVia,
      notes: [{ id: "n_wa_" + Date.now(), date: now, text: `Contato via WhatsApp (lista de envio): "${message}"` }, ...(l.notes || [])],
    } : l));
    setWaSendList((prev) => prev.filter((x) => x.leadId !== leadId));
    setWaSendHistory((prev) => [{ id: "wh_" + Date.now() + "_" + leadId, leadId, company: lead?.company || "Lead removido", whatsapp: lead?.whatsapp || "", message, date: now, by: currentUserId }, ...prev].slice(0, 300));
    if (lead?.weekTag && !lead?.weekDone) { setToast(`${lead.company}: marcado como feito na Lista da Semana também!`); logWeekHistory(lead, "whatsapp-lista"); }
  };

  const saveMeeting = (m) => setMeetings((prev) => prev.map((x) => (x.id === m.id ? m : x)));
  const deleteMeeting = (id) => { setMeetings((prev) => prev.filter((m) => m.id !== id)); setSelectedMeeting(null); };
  const createMeeting = () => {
    const firstSdr = sdrs[0]?.name || "";
    const nm = { id: "m_" + Date.now(), date: iso(agendaDate, 9, 0), duration: 30, type: "reuniao", company: leads[0]?.company || "", owner: firstSdr, materials: "", ourAttendee: firstSdr, theirAttendee: "", locationType: "online", link: "", address: "" };
    setMeetings((prev) => [...prev, nm]);
    setSelectedMeeting(nm);
  };

  const shareAgenda = () => {
    const dayMeetings = meetings.filter((m) => isSameDay(m.date, agendaDate)).sort((a, b) => new Date(a.date) - new Date(b.date));
    const text = `Agenda comercial - ${agendaDate.toLocaleDateString("pt-BR")}\n\n` + dayMeetings.map((m) => {
      const t = new Date(m.date).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });
      return `${t} · ${MEETING_TYPES[m.type].label} - ${m.company} (SDR: ${m.owner})`;
    }).join("\n");
    if (navigator.clipboard) { navigator.clipboard.writeText(text); setToast("Agenda copiada para a área de transferência"); }
    else setToast("Não foi possível copiar automaticamente");
  };

  const stats = useMemo(() => {
    const total = leads.length;
    const desatendidos = leads.filter((l) => l.status === "Desatendido");
    const vendidas = leads.filter((l) => l.stage === "Conquistado").length;
    const ativos = leads.filter((l) => l.stage !== "Conquistado" && l.stage !== "Perdida").length;
    const withWhatsapp = leads.filter((l) => l.whatsapp || l.hasWhatsapp).length;
    const receita = leads.filter((l) => l.stage === "Conquistado").reduce((s, l) => s + getDealValue(l), 0);
    // Lista da semana agora é montada pela tag manual (weekTag), não mais pelo status
    const weekList = leads.filter((l) => l.weekTag && !l.weekDone);
    const weekCompleted = leads.filter((l) => l.weekTag && l.weekDone);
    const weekDoneCount = leads.filter((l) => l.weekTag && l.weekDone).length;
    const weekTotalTagged = leads.filter((l) => l.weekTag).length;
    const superLeads = leads.filter((l) => l.superAttention);
    const upcomingMeetings = meetings.filter((m) => new Date(m.date) >= new Date(new Date().setHours(0, 0, 0, 0)));
    // Cálculo automático da semana corrente (segunda a domingo) para o box "Ações desta semana"
    const now = new Date();
    const dayIdx = (now.getDay() + 6) % 7; // 0 = segunda
    const weekStart = new Date(now); weekStart.setHours(0, 0, 0, 0); weekStart.setDate(now.getDate() - dayIdx);
    const weekEnd = new Date(weekStart); weekEnd.setDate(weekStart.getDate() + 7);
    const meetingsThisWeek = meetings.filter((m) => { const d = new Date(m.date); return d >= weekStart && d < weekEnd; }).length;
    const contactedThisWeek = leads.filter((l) => l.lastContact && new Date(l.lastContact) >= weekStart && new Date(l.lastContact) < weekEnd).length;
    // Leads quentes sem contato recente - usado pra puxar atenção pro assistente de IA no dashboard
    const hotNoContact = leads.filter((l) => l.stage !== "Conquistado" && l.stage !== "Perdida" && l.temperature === "hot" && (daysSince(l.lastContact) === null || daysSince(l.lastContact) > 3));
    return { total, desatendidos, vendidas, ativos, withWhatsapp, receita, weekList, weekCompleted, weekDoneCount, weekTotalTagged, superLeads, upcomingMeetings, meetingsThisWeek, contactedThisWeek, hotNoContact };
  }, [leads, meetings]);

  // Dados filtrados por período - usados só na página de Relatórios
  const reportStats = useMemo(() => {
    if (reportPeriod === "all") {
      return {
        meetingsInPeriod: meetings.length,
        contactedInPeriod: leads.filter((l) => l.lastContact).length,
        label: "todo o período",
      };
    }
    const days = parseInt(reportPeriod, 10);
    const cutoff = new Date(); cutoff.setHours(0, 0, 0, 0); cutoff.setDate(cutoff.getDate() - days);
    const meetingsInPeriod = meetings.filter((m) => new Date(m.date) >= cutoff).length;
    const contactedInPeriod = leads.filter((l) => l.lastContact && new Date(l.lastContact) >= cutoff).length;
    return { meetingsInPeriod, contactedInPeriod, label: `últimos ${days} dias` };
  }, [leads, meetings, reportPeriod]);

  // Leads conquistados (Vendida), filtrados por data de fechamento - usados na página dedicada
  const wonLeads = useMemo(() => {
    let arr = leads.filter((l) => l.stage === "Conquistado");
    if (wonPeriod !== "all") {
      const days = parseInt(wonPeriod, 10);
      const cutoff = new Date(); cutoff.setHours(0, 0, 0, 0); cutoff.setDate(cutoff.getDate() - days);
      arr = arr.filter((l) => !l.wonDate || new Date(l.wonDate) >= cutoff);
    }
    arr.sort((a, b) => {
      const da = a.wonDate ? new Date(a.wonDate).getTime() : 0;
      const db = b.wonDate ? new Date(b.wonDate).getTime() : 0;
      return db - da;
    });
    return arr;
  }, [leads, wonPeriod]);
  const wonTotalValue = useMemo(() => wonLeads.reduce((s, l) => s + getDealValue(l), 0), [wonLeads]);
  const wonTotalOnce = useMemo(() => wonLeads.filter((l) => l.dealType !== "mensal").reduce((s, l) => s + getDealValue(l), 0), [wonLeads]);
  const wonTotalMonthly = useMemo(() => wonLeads.filter((l) => l.dealType === "mensal").reduce((s, l) => s + getDealValue(l), 0), [wonLeads]);

  const filtered = useMemo(() => {
    const q = search.toLowerCase().trim();
    let arr = leads.filter((l) => {
      if (l.stage === "Conquistado") return false; // conquistados saem da lista principal e só aparecem na página "Conquistados"
      if (tempFilter !== "all" && l.temperature !== tempFilter) return false;
      if (whatsappOnly && !l.whatsapp && !l.hasWhatsapp) return false;
      if (ownerFilter !== "all" && l.owner !== ownerFilter) return false;
      if (statusFilter !== "all" && l.status !== statusFilter) return false;
      if (phaseFilter !== "all" && (l.phase || "none") !== phaseFilter) return false;
      if (originFilter !== "all" && l.origin !== originFilter) return false;
      if (quickStage === "ativo" && l.stage === "Perdida") return false;
      if (superOnly && !l.superAttention) return false;
      if (!q) return true;
      // Além do nome da empresa, busca por telefone/whatsapp (ignorando formatação) e email,
      // porque às vezes o SDR só lembra o número ou o email de quem está tentando achar.
      const qDigits = q.replace(/\D/g, "");
      const phoneMatch = qDigits.length >= 4 && (cleanPhone(l.phone).includes(qDigits) || cleanPhone(l.whatsapp).includes(qDigits));
      return (
        l.company.toLowerCase().includes(q) ||
        (l.feedback || "").toLowerCase().includes(q) ||
        (l.owner || "").toLowerCase().includes(q) ||
        (l.contactName || "").toLowerCase().includes(q) ||
        (l.email || "").toLowerCase().includes(q) ||
        phoneMatch
      );
    });
    const tempRank = { hot: 0, warm: 1, cold: 2 };
    arr.sort((a, b) => {
      const sa = a.status === "Desatendido" ? 0 : 1, sb = b.status === "Desatendido" ? 0 : 1;
      if (sa !== sb) return sa - sb;
      const t = tempRank[a.temperature] - tempRank[b.temperature];
      if (t !== 0) return t;
      return a.company.localeCompare(b.company);
    });
    return arr;
  }, [leads, search, tempFilter, whatsappOnly, ownerFilter, statusFilter, phaseFilter, originFilter, quickStage, superOnly]);

  const desatendidosFiltered = filtered.filter((l) => l.status === "Desatendido");

  const hasActiveFilters = !!search || tempFilter !== "all" || whatsappOnly || ownerFilter !== "all" || statusFilter !== "all" || phaseFilter !== "all" || originFilter !== "all" || !!quickStage || superOnly;
  const clearFilters = () => { setSearch(""); setTempFilter("all"); setWhatsappOnly(false); setOwnerFilter("all"); setStatusFilter("all"); setPhaseFilter("all"); setOriginFilter("all"); setQuickStage(null); setSuperOnly(false); };

  const scrollToGrid = () => {
    setTimeout(() => document.getElementById("leads-grid")?.scrollIntoView({ behavior: "smooth", block: "start" }), 50);
  };

  const dayMeetings = meetings.filter((m) => isSameDay(m.date, agendaDate)).sort((a, b) => new Date(a.date) - new Date(b.date));
  const meetingCounts = {
    reuniao: dayMeetings.filter((m) => m.type === "reuniao").length,
    followup: dayMeetings.filter((m) => m.type === "followup").length,
    proposta: dayMeetings.filter((m) => m.type === "proposta").length,
    apresentacao: dayMeetings.filter((m) => m.type === "apresentacao").length,
  };

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Open+Sans:wght@400;500;600;700;800&display=swap');
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes slideUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes glowPulse { 0%, 100% { opacity: 0.55; transform: scale(1); } 50% { opacity: 0.85; transform: scale(1.08); } }
        @keyframes popIn { 0% { transform: scale(0.9); opacity: 0; } 60% { transform: scale(1.04); } 100% { transform: scale(1); opacity: 1; } }
        @keyframes stageBarFill { from { width: 0%; } }
        @keyframes celebrate { 0% { transform: scale(1); } 30% { transform: scale(1.12); } 60% { transform: scale(0.97); } 100% { transform: scale(1); } }
        @keyframes coinFloat { 0% { opacity: 0; transform: translate(-50%, 0) scale(0.5) rotate(0deg); } 20% { opacity: 1; transform: translate(-50%, -20px) scale(1.2) rotate(90deg); } 100% { opacity: 0; transform: translate(-50%, -90px) scale(1) rotate(360deg); } }
        @keyframes blob { 0%, 100% { transform: translate(0, 0) scale(1); } 33% { transform: translate(40px, -30px) scale(1.08); } 66% { transform: translate(-30px, 30px) scale(0.94); } }
        @keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }
        @keyframes pulseGlow { 0%, 100% { box-shadow: 0 8px 28px -8px rgba(99,102,241,0.35); } 50% { box-shadow: 0 12px 36px -6px rgba(99,102,241,0.55); } }
        @keyframes toastIn { from { opacity: 0; transform: translate(-50%, 10px); } to { opacity: 1; transform: translate(-50%, 0); } }
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        @keyframes ledSpin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        @keyframes typingDot { 0%, 60%, 100% { transform: translateY(0); opacity: 0.4; } 30% { transform: translateY(-4px); opacity: 1; } }
        @keyframes badgePop { 0% { opacity: 0; transform: scale(0.7) translateY(20px); } 100% { opacity: 1; transform: scale(1) translateY(0); } }
        @keyframes badgeBounce { 0% { transform: scale(0); } 60% { transform: scale(1.15); } 100% { transform: scale(1); } }
        @keyframes badgeGlow { 0%, 100% { opacity: 0.12; transform: translateX(-50%) scale(1); } 50% { opacity: 0.25; transform: translateX(-50%) scale(1.15); } }
        @keyframes menuSlideIn { from { transform: translateX(-100%); } to { transform: translateX(0); } }
        @keyframes coinFall {
          0% { transform: translateY(-40px) rotate(0deg); opacity: 0; }
          8% { opacity: 1; }
          90% { opacity: 1; }
          100% { transform: translateY(100vh) rotate(var(--rot)); opacity: 0.3; }
        }
        * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
        .leads-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
        @media (min-width: 720px) { .leads-grid { grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 14px; } }

        /* Card de lead compacto - 2 colunas no mobile, tamanho normal a partir de 720px */
        .lc-pad { padding: 12px 12px; }
        .lc-title { font-size: 14.5px; }
        .lc-owner { font-size: 11px; }
        .lc-pill { font-size: 9.5px; }
        .lc-label { font-size: 9px; }
        .lc-next { font-size: 11.5px; }
        .lc-status { font-size: 10.5px; }
        .lc-arrow { width: 24px; height: 24px; }
        .lc-superbadge { font-size: 9px; }
        .lc-footer .circle-btn { width: 28px; height: 28px; }
        .lc-footer .circle-btn svg { width: 12px; height: 12px; }
        .lc-footer .toggle-switch { width: 36px; height: 21px; }
        .lc-footer .toggle-switch .toggle-knob { width: 16px; height: 16px; top: 2.5px; }
        @media (min-width: 720px) {
          .lc-pad { padding: 16px 18px; }
          .lc-title { font-size: 18px; }
          .lc-owner { font-size: 12.5px; }
          .lc-pill { font-size: 11.5px; }
          .lc-label { font-size: 10.5px; }
          .lc-next { font-size: 13px; }
          .lc-status { font-size: 12px; }
          .lc-arrow { width: 30px; height: 30px; }
          .lc-superbadge { font-size: 10.5px; }
        }
        button, a, [role="button"] { -webkit-tap-highlight-color: transparent; outline: none; }
        button:focus, button:focus-visible { outline: none; }
        input:focus, select:focus, textarea:focus { border-color: rgba(99, 102, 241, 0.5) !important; box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.12); }
        ::-webkit-scrollbar { width: 8px; height: 8px; }
        ::-webkit-scrollbar-track { background: transparent; }
        ::-webkit-scrollbar-thumb { background: rgba(148, 163, 184, 0.3); border-radius: 4px; }
        .lead-card:hover { transform: translateY(-3px); box-shadow: 0 1px 0 rgba(255,255,255,0.95) inset, 0 16px 36px -10px rgba(76, 29, 149, 0.22) !important; }
        .glow-btn { position: relative; overflow: hidden; }
        .glow-btn::after { content: ""; position: absolute; inset: 0; background: linear-gradient(120deg, transparent 30%, rgba(255,255,255,0.35) 50%, transparent 70%); background-size: 200% 100%; animation: shimmer 3.5s ease-in-out infinite; }
      `}</style>

      <div style={{ minHeight: "100vh", background: "linear-gradient(135deg, #f5f3ff 0%, #eef2ff 35%, #fdf2f8 100%)", fontFamily: '"Open Sans", Arial, sans-serif', color: "#0f172a", position: "relative", overflow: "hidden" }}>
        <div style={{ position: "fixed", top: -150, right: -100, width: 420, height: 420, borderRadius: "50%", background: "radial-gradient(circle, rgba(139, 92, 246, 0.28), transparent 70%)", filter: "blur(50px)", animation: "blob 20s ease-in-out infinite", pointerEvents: "none" }} />
        <div style={{ position: "fixed", bottom: -120, left: -100, width: 380, height: 380, borderRadius: "50%", background: "radial-gradient(circle, rgba(99, 102, 241, 0.22), transparent 70%)", filter: "blur(50px)", animation: "blob 25s ease-in-out infinite reverse", pointerEvents: "none" }} />
        <div style={{ position: "fixed", top: "35%", left: "55%", width: 320, height: 320, borderRadius: "50%", background: "radial-gradient(circle, rgba(244, 114, 182, 0.2), transparent 70%)", filter: "blur(50px)", animation: "blob 22s ease-in-out infinite", pointerEvents: "none" }} />

        <div style={{ position: "relative", maxWidth: 1320, margin: "0 auto", padding: "24px 20px 100px" }}>

          {/* ── HEADER ESCURO (fixo no topo de todas as views internas do Home) ── */}
          {view === "dashboard" && (
            <div style={{
              backgroundImage: `linear-gradient(rgba(10,10,12,0.35), rgba(10,10,12,0.55)), url(${HEADER_BANNER_URI})`,
              backgroundSize: "cover", backgroundPosition: "center",
              borderRadius: 26, padding: "20px 22px 24px", marginBottom: 16, position: "relative", overflow: "hidden",
            }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18 }}>
                <button onClick={() => setShowMenu(true)} style={{ width: 44, height: 44, borderRadius: 13, border: "none", background: "#232327", color: "white", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}>
                  <Menu size={19} />
                </button>
                <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
                  <button onClick={() => setShowNotifications(true)} title="Notificações" style={{ width: 44, height: 44, borderRadius: 13, border: "none", background: "#232327", color: "white", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", position: "relative" }}>
                    <Bell size={18} />
                    {(stats.desatendidos.length + stats.hotNoContact.length + stats.weekList.length) > 0 && <span style={{ position: "absolute", top: 9, right: 10, width: 8, height: 8, borderRadius: "50%", background: DARK.lime, border: "2px solid " + DARK.card }} />}
                  </button>
                  <button onClick={() => setShowSdrManager(true)} title="Gerenciar SDRs" style={{ width: 44, height: 44, borderRadius: "50%", background: sdrs[0]?.avatarUrl ? "transparent" : "linear-gradient(135deg, #6366f1, #8b5cf6)", border: `2px solid ${DARK.lime}`, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", color: "white", fontWeight: 700, fontSize: 15, padding: 0, overflow: "hidden" }}>
                    {sdrs[0]?.avatarUrl
                      ? <img src={sdrs[0].avatarUrl} alt={sdrs[0].name} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                      : (sdrs[0]?.name || "U").charAt(0)}
                  </button>
                </div>
              </div>
              <div style={{ fontSize: 11, fontWeight: 400, letterSpacing: 1.5, textTransform: "uppercase", color: DARK.lime, marginBottom: 6 }}>Sales Intelligence · B2B</div>
              <h1 style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 24, fontWeight: 800, letterSpacing: -0.5, margin: 0, color: "white", lineHeight: 1.15, marginBottom: workspaceName ? 3 : 16 }}>Visão geral do funil</h1>
              {workspaceName && <div style={{ fontSize: 12, fontWeight: 400, color: "rgba(255,255,255,0.55)", marginBottom: 16 }}>{workspaceName}</div>}
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                <button onClick={createLead} className="glow-btn" style={{ display: "flex", alignItems: "center", gap: 5, padding: "7px 13px", borderRadius: 9, border: "none", background: DARK.lime, color: "#14141a", fontSize: 12, fontWeight: 800, cursor: "pointer" }}>
                  <Plus size={13} /> Novo lead
                </button>
                <button onClick={() => setShowImportModal(true)} style={{ display: "flex", alignItems: "center", gap: 5, padding: "7px 13px", borderRadius: 9, border: "1.5px solid rgba(255,255,255,0.25)", background: "rgba(255,255,255,0.08)", color: "white", fontSize: 12, fontWeight: 700, cursor: "pointer" }}>
                  <Upload size={13} /> Importar leads
                </button>
              </div>
            </div>
          )}

          {/* ═══════════════════ DASHBOARD ═══════════════════ */}
          {view === "dashboard" && (
            <>
              {/* KPI cards */}
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))", gap: 12, marginBottom: 12 }}>
                <div
                  onClick={() => { clearFilters(); scrollToGrid(); }}
                  style={{ borderRadius: 20, padding: "16px 18px", cursor: "pointer", backgroundImage: `linear-gradient(rgba(255,255,255,0.55), rgba(255,255,255,0.7)), url(${BG_GREEN_LIGHT})`, backgroundSize: "cover", backgroundPosition: "center", border: "1px solid #eef0f3" }}
                >
                  <HexIcon icon={Users} color="#d7fa3c" grad="linear-gradient(160deg, #e7ffa0, #d7fa3c)" size={38} iconSize={16} iconColor="#14141a" />
                  <div style={{ fontSize: 12.5, color: "#6b6b75", fontWeight: 600, marginTop: 10, marginBottom: 3 }}>Total de leads</div>
                  <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 30, fontWeight: 800, color: "#14141a" }}>{stats.total}</div>
                  <div style={{ height: 5, borderRadius: 3, background: "#eef0f3", marginTop: 8 }}><div style={{ height: "100%", width: "100%", borderRadius: 3, background: DARK.lime }} /></div>
                  <div style={{ fontSize: 10.5, color: "#9a9aa3", marginTop: 6 }}>toque para ver todos</div>
                </div>

                <div
                  onClick={() => { setQuickStage("ativo"); setSearch(""); setTempFilter("all"); setWhatsappOnly(false); setOwnerFilter("all"); setStatusFilter("all"); setPhaseFilter("all"); scrollToGrid(); }}
                  style={{
                    borderRadius: 20, padding: "16px 18px", color: "white", cursor: "pointer", position: "relative", overflow: "hidden",
                    backgroundImage: `linear-gradient(rgba(5,5,6,0.25), rgba(5,5,6,0.45)), url(${BG_EM_CONTATO})`,
                    backgroundSize: "cover", backgroundPosition: "center",
                  }}
                >
                  <HexIcon icon={EmContatoIcon} color="#d7fa3c" grad="linear-gradient(160deg, #eaff9c, #d7fa3c)" size={38} iconSize={16} iconColor="#14141a" />
                  <div style={{ fontSize: 12.5, opacity: 0.75, fontWeight: 600, marginTop: 10, marginBottom: 3 }}>Em contato</div>
                  <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 30, fontWeight: 800, color: DARK.lime }}>{stats.ativos}</div>
                  <div style={{ fontSize: 11, opacity: 0.75, marginTop: 8 }}>conversas ativas</div>
                  <div style={{ fontSize: 10.5, opacity: 0.6, marginTop: 3 }}>● {stats.total ? Math.round((stats.ativos / stats.total) * 100) : 0}% do funil</div>
                </div>
              </div>

              {quickStage && (
                <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 14, fontSize: 12, color: "#6366f1", fontWeight: 600 }}>
                  <SlidersHorizontal size={13} />
                  Filtro rápido: somente em contato
                  <button onClick={() => setQuickStage(null)} style={{ display: "flex", alignItems: "center", gap: 4, padding: "3px 9px", borderRadius: 7, border: "1px solid rgba(99,102,241,0.3)", background: "rgba(99,102,241,0.08)", color: "#6366f1", fontSize: 11, fontWeight: 600, cursor: "pointer" }}>
                    <X size={11} /> limpar
                  </button>
                </div>
              )}

              {/* Sugestão pro assistente de IA quando há leads quentes esfriando sem contato -
                  a legenda mostra o lead mais urgente de verdade, não um texto genérico */}
              {stats.hotNoContact.length > 0 && (() => {
                const sortedHot = [...stats.hotNoContact].sort((a, b) => (daysSince(b.lastContact) ?? 999) - (daysSince(a.lastContact) ?? 999));
                const mostUrgent = sortedHot[0];
                const urgentDays = daysSince(mostUrgent.lastContact);
                const urgentLabel = urgentDays === null ? "nunca contatado" : `há ${urgentDays} dias sem contato`;
                const extra = stats.hotNoContact.length - 1;
                return (
                  <div
                    onClick={() => { setChatInput(`Quais desses ${stats.hotNoContact.length} leads quentes sem contato eu deveria priorizar hoje?`); setView("assistente"); }}
                    style={{ display: "flex", alignItems: "center", gap: 10, padding: "12px 16px", borderRadius: 16, background: "rgba(109,94,248,0.08)", border: "1px solid rgba(109,94,248,0.25)", cursor: "pointer", marginBottom: 14 }}
                  >
                    <div style={{ width: 32, height: 32, borderRadius: "50%", padding: 2, boxSizing: "border-box", flexShrink: 0, background: "conic-gradient(from 0deg, transparent 0%, #6d5ef8 18%, transparent 36%, transparent 100%)", animation: "ledSpin 2.4s linear infinite" }}>
                      <img src="/funnio-icon-round.png" alt="" style={{ width: "100%", height: "100%", borderRadius: "50%", display: "block", objectFit: "cover" }} />
                    </div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 12.5, fontWeight: 700, color: "#14141a" }}>
                        {stats.hotNoContact.length} lead{stats.hotNoContact.length === 1 ? "" : "s"} quente{stats.hotNoContact.length === 1 ? "" : "s"} esfriando
                      </div>
                      <div style={{ fontSize: 11, color: "#6b6b75", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                        <strong style={{ color: "#6d5ef8" }}>{mostUrgent.company}</strong> está {urgentLabel}{extra > 0 ? ` · +${extra} outro${extra === 1 ? "" : "s"}` : ""}
                      </div>
                    </div>
                    <ChevronRight size={16} color="#6d5ef8" style={{ flexShrink: 0 }} />
                  </div>
                );
              })()}

              {/* Linha de campos pequenos: Conquistados, Reuniões agendadas, Negociações antigas, Super lead */}
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px, 1fr))", gap: 10, marginBottom: 14 }}>
                <div
                  onClick={() => setView("conquistados")}
                  style={{ borderRadius: 16, padding: "12px 14px", backgroundImage: `linear-gradient(rgba(255,255,255,0.5), rgba(255,255,255,0.65)), url(${BG_LAVENDER_LIGHT})`, backgroundSize: "cover", backgroundPosition: "center", border: "1px solid #eef0f3", cursor: "pointer" }}
                >
                  <HexIcon icon={CheckImgIcon} color="#6d5ef8" grad="linear-gradient(160deg, #a79bfc, #6d5ef8)" size={30} iconSize={13} />
                  <div style={{ fontSize: 11.5, color: "#6b6b75", fontWeight: 700, marginTop: 8 }}>Conquistados</div>
                  <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 22, fontWeight: 800, color: "#14141a" }}>{stats.vendidas}</div>
                </div>

                <div onClick={() => setView("agenda")} style={{ borderRadius: 16, padding: "12px 14px", backgroundImage: `linear-gradient(rgba(30,20,80,0.15), rgba(30,20,80,0.15)), url(${BG_PURPLE_VIVID})`, backgroundSize: "cover", backgroundPosition: "center", color: "white", cursor: "pointer" }}>
                  <HexIcon icon={ReunioesIcon} color="white" grad="rgba(255,255,255,0.22)" size={30} iconSize={13} iconColor="white" />
                  <div style={{ fontSize: 11.5, opacity: 0.9, fontWeight: 700, marginTop: 8 }}>Calendário</div>
                  <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 22, fontWeight: 800 }}>{stats.upcomingMeetings.length}</div>
                  <div style={{ fontSize: 10, opacity: 0.8, fontWeight: 600, marginTop: 3 }}>
                    {stats.upcomingMeetings.filter((m) => m.type !== "followup").length} reuniões · {stats.upcomingMeetings.filter((m) => m.type === "followup").length} retornos
                  </div>
                </div>

                <div onClick={() => setView("desatendidos")} style={{ borderRadius: 16, padding: "12px 14px", backgroundImage: `linear-gradient(rgba(255,255,255,0.45), rgba(255,255,255,0.6)), url(${BG_PINK_LIGHT})`, backgroundSize: "cover", backgroundPosition: "center", border: "1px solid #eef0f3", cursor: "pointer" }}>
                  <HexIcon icon={NegociacoesRedIcon} color="#e2483f" grad="linear-gradient(160deg, #f88a80, #e2483f)" size={30} iconSize={13} />
                  <div style={{ fontSize: 11.5, color: "#6b6b75", fontWeight: 700, marginTop: 8 }}>Negociações antigas</div>
                  <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 22, fontWeight: 800, color: "#14141a" }}>{stats.desatendidos.length}</div>
                </div>

                <div onClick={() => { setSuperOnly((v) => !v); scrollToGrid(); }} style={{ borderRadius: 16, padding: "12px 14px", backgroundImage: `linear-gradient(rgba(255,255,255,0.45), rgba(255,255,255,0.6)), url(${BG_ORANGE_LIGHT})`, backgroundSize: "cover", backgroundPosition: "center", border: `1px solid ${superOnly ? "#f5c94c" : "#eef0f3"}`, cursor: "pointer" }}>
                  <HexIcon icon={StarImgIcon} color="#f5c518" grad="linear-gradient(160deg, #ffe27a, #f5c518)" size={30} iconSize={13} />
                  <div style={{ fontSize: 11.5, color: "#6b6b75", fontWeight: 700, marginTop: 8 }}>Super lead</div>
                  <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 22, fontWeight: 800, color: "#14141a" }}>{stats.superLeads.length}</div>
                </div>

                <div onClick={() => setView("metas")} style={{ borderRadius: 13, padding: "9px 12px", backgroundImage: `linear-gradient(rgba(255,255,255,0.5), rgba(255,255,255,0.65)), url(${BG_PURPLE_GREEN})`, backgroundSize: "cover", backgroundPosition: "center", border: `1px solid ${almostThereGoals.length ? "#f5c94c" : "#eef0f3"}`, cursor: "pointer", position: "relative" }}>
                  {almostThereGoals.length > 0 && (
                    <div title={`${almostThereGoals[0].sdrName} está a ${Math.round((1 - almostThereGoals[0].pct) * 100)}% de bater a meta de ${almostThereGoals[0].metricLabel}`} style={{ position: "absolute", top: 6, right: 6, width: 8, height: 8, borderRadius: "50%", background: "#f5c518", boxShadow: "0 0 0 3px rgba(245,197,24,0.25)" }} />
                  )}
                  <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                    <div style={{ width: 24, height: 24, borderRadius: 7, background: "rgba(109,94,248,0.12)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><Flag size={11} color="#6d5ef8" /></div>
                    <div style={{ minWidth: 0 }}>
                      <div style={{ fontSize: 10, color: "#6b6b75", fontWeight: 700 }}>Metas</div>
                      <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 16, fontWeight: 800, color: "#14141a", lineHeight: 1.2 }}>{Object.values(goalsConfig).filter((c) => c.enabled).length} ativa{Object.values(goalsConfig).filter((c) => c.enabled).length === 1 ? "" : "s"}</div>
                    </div>
                  </div>
                  <div style={{ fontSize: 9.5, color: "#9a9aa3", marginTop: 5, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                    {almostThereGoals.length > 0
                      ? `${almostThereGoals[0].sdrName} quase batendo ${almostThereGoals[0].metricLabel}`
                      : (METRIC_KEYS.filter((k) => goalsConfig[k].enabled).map((k) => METRIC_DEFS[k].shortLabel).join(" · ") || "nenhuma configurada")}
                  </div>
                </div>

                <div onClick={() => setView("conquistas")} style={{ borderRadius: 13, padding: "9px 12px", backgroundImage: `linear-gradient(rgba(255,255,255,0.4), rgba(255,255,255,0.55)), url(${BG_CREAM_LIGHT})`, backgroundSize: "cover", backgroundPosition: "center", border: "1px solid #eef0f3", cursor: "pointer" }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                    <div style={{ width: 24, height: 24, borderRadius: 7, background: "rgba(184,134,11,0.12)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><Trophy size={11} color="#b8860b" /></div>
                    <div style={{ minWidth: 0 }}>
                      <div style={{ fontSize: 10, color: "#6b6b75", fontWeight: 700 }}>Conquistas</div>
                      <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 16, fontWeight: 800, color: "#14141a", lineHeight: 1.2 }}>{earnedBadges.length}</div>
                    </div>
                  </div>
                  <div style={{ fontSize: 9.5, color: "#9a9aa3", marginTop: 5, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                    {BADGE_TIERS.map((t) => `${t.shortLabel} ${earnedBadges.filter((b) => b.tier === t.key).length}`).join(" · ")}
                  </div>
                </div>
              </div>

              {(quickStage || superOnly) && (
                <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 14, fontSize: 12, color: "#6366f1", fontWeight: 600, flexWrap: "wrap" }}>
                  <SlidersHorizontal size={13} />
                  Filtro rápido: {[quickStage === "ativo" && "somente em contato", superOnly && "somente super atenção"].filter(Boolean).join(" · ")}
                  <button onClick={() => { setQuickStage(null); setSuperOnly(false); }} style={{ display: "flex", alignItems: "center", gap: 4, padding: "3px 9px", borderRadius: 7, border: "1px solid rgba(99,102,241,0.3)", background: "rgba(99,102,241,0.08)", color: "#6366f1", fontSize: 11, fontWeight: 600, cursor: "pointer" }}>
                    <X size={11} /> limpar
                  </button>
                </div>
              )}

              {/* Abordar essa semana - card único fundido: hero lima + progresso + estatísticas + alerta */}
              {(() => {
                const goalMet = stats.weekDoneCount >= weeklyGoal;
                const pct = Math.min(100, Math.round((stats.weekDoneCount / weeklyGoal) * 100));
                const remaining = Math.max(0, weeklyGoal - stats.weekDoneCount);
                // dias restantes na semana (segunda a domingo), incluindo hoje
                const dayIdx = (new Date().getDay() + 6) % 7;
                const daysLeftInWeek = Math.max(1, 7 - dayIdx);
                const avgPerDay = Math.ceil(remaining / daysLeftInWeek);

                return (
                  <div style={{ borderRadius: 22, overflow: "hidden", marginBottom: 20, boxShadow: "0 8px 28px -14px rgba(20,20,26,0.18)" }}>
                    {/* Topo: hero lima com imagem real de fundo */}
                    <div
                      onClick={() => setView("semana")}
                      style={{
                        padding: "34px 22px", color: "#14141a", cursor: "pointer", position: "relative",
                        backgroundImage: `url(${BG_WEEK_HERO})`, backgroundSize: "cover", backgroundPosition: "center",
                      }}
                    >
                      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 12 }}>
                        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                          <div style={{ width: 38, height: 38, borderRadius: 12, background: "rgba(20,20,26,0.14)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><Target size={19} /></div>
                          <div>
                            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                              <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 18, fontWeight: 800, lineHeight: 1.15 }}>Abordar essa semana</div>
                              <span style={{ fontSize: 11, fontWeight: 800, background: "rgba(20,20,26,0.14)", padding: "2px 8px", borderRadius: 20, lineHeight: 1.4 }}>{stats.weekList.length}</span>
                            </div>
                            <div style={{ fontSize: 12, fontWeight: 600, opacity: 0.75 }}>Foque nos leads da sua lista</div>
                          </div>
                        </div>
                        <button onClick={(e) => { e.stopPropagation(); setView("semana"); }} style={{ display: "flex", alignItems: "center", gap: 7, padding: "10px 18px", borderRadius: 12, border: "none", background: "#14141a", color: DARK.lime, fontSize: 13, fontWeight: 800, cursor: "pointer", flexShrink: 0 }}>
                          Ver lista <ChevronRight size={14} />
                        </button>
                      </div>
                      {stats.weekTotalTagged === 0 && <div style={{ fontSize: 12, fontWeight: 600, marginTop: 10 }}>Nenhum lead marcado ainda - abra um lead e adicione a tag "Hoje" ou "Esta semana".</div>}
                    </div>

                    {/* Baixo: progresso + estatísticas + alerta, fundo branco */}
                    <div style={{ background: "white", padding: "22px 24px" }}>
                      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 14, flexWrap: "wrap", gap: 8 }}>
                        <span style={{ fontSize: 15, fontWeight: 800, color: "#14141a" }}>Seu progresso semanal</span>
                        <button
                          onClick={() => setEditingGoal(true)}
                          title="Clique para definir a meta semanal a qualquer momento"
                          style={{ display: "flex", alignItems: "center", gap: 6, border: "none", background: "transparent", cursor: "pointer", padding: 0 }}
                        >
                          {editingGoal ? (
                            <input
                              type="number" min={1} autoFocus defaultValue={weeklyGoal}
                              onBlur={(e) => { const v = parseInt(e.target.value, 10); setWeeklyGoal(v > 0 ? v : DEFAULT_WEEKLY_GOAL); setEditingGoal(false); }}
                              onKeyDown={(e) => { if (e.key === "Enter") e.target.blur(); }}
                              onClick={(e) => e.stopPropagation()}
                              style={{ width: 60, padding: "3px 6px", borderRadius: 7, border: "1.5px solid #6d5ef8", fontSize: 13, fontWeight: 700, color: "#14141a", outline: "none" }}
                            />
                          ) : (
                            <span style={{ fontSize: 12, color: "#9a9aa3", fontWeight: 600, display: "flex", alignItems: "center", gap: 5 }}>
                              Meta: <span style={{ color: "#6d5ef8", fontWeight: 800 }}>{weeklyGoal} leads</span> <Pencil size={11} color="#6d5ef8" />
                            </span>
                          )}
                        </button>
                      </div>

                      <div style={{ display: "flex", alignItems: "center", gap: 18, marginBottom: 10 }}>
                        <div style={{ position: "relative", width: 90, height: 90, flexShrink: 0 }}>
                          <svg width="90" height="90" viewBox="0 0 90 90">
                            <circle cx="45" cy="45" r="38" fill="none" stroke="#eef0f3" strokeWidth="9" />
                            <circle cx="45" cy="45" r="38" fill="none" stroke={goalMet ? "#059669" : DARK.lime} strokeWidth="9" strokeDasharray={`${(pct / 100) * 238.8} 238.8`} strokeLinecap="round" transform="rotate(-90 45 45)" />
                          </svg>
                          <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
                            <span style={{ fontSize: 19, fontWeight: 800, color: "#14141a", lineHeight: 1 }}>{pct}%</span>
                            <span style={{ fontSize: 9, color: "#9a9aa3", fontWeight: 600 }}>da meta</span>
                          </div>
                        </div>

                        <div style={{ flex: 1, minWidth: 140 }}>
                          <div style={{ height: 12, borderRadius: 6, background: "#eef0f3", marginBottom: 8 }}>
                            <div style={{
                              height: "100%", borderRadius: 6, width: `${pct}%`,
                              background: goalMet ? "linear-gradient(90deg, #34d399, #059669)" : "linear-gradient(90deg, #c8e85a, #a8dc2e)",
                              transition: "width 0.3s ease",
                            }} />
                          </div>
                          <div>
                            <span style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 20, fontWeight: 800, color: goalMet ? "#059669" : "#8fae0e" }}>{stats.weekDoneCount}</span>
                            <span style={{ fontSize: 14, fontWeight: 700, color: "#c4c4cc" }}> / {weeklyGoal}</span>
                            <span style={{ fontSize: 12, color: "#9a9aa3", fontWeight: 600, marginLeft: 5 }}>leads</span>
                          </div>
                        </div>
                      </div>

                      <div style={{ borderTop: "1px solid #f1f2f5", paddingTop: 18, marginBottom: 18 }}>
                        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(140px, 1fr))", gap: 0 }}>
                          {[
                            { icon: Users2, value: stats.weekDoneCount, label: "abordados", sub: "esta semana", color: "#6d5ef8", bg: "rgba(109,94,248,0.1)" },
                            { icon: CalendarIcon, value: stats.meetingsThisWeek, label: "reuniões", sub: "esta semana", color: "#3b82f6", bg: "rgba(59,130,246,0.1)" },
                          ].map((stat, i) => (
                            <div key={i} style={{ display: "flex", alignItems: "center", gap: 12, padding: "4px 16px", borderLeft: i > 0 ? "1px solid #f1f2f5" : "none" }}>
                              <div style={{ width: 42, height: 42, borderRadius: 12, background: stat.bg, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                                <stat.icon size={19} color={stat.color} />
                              </div>
                              <div>
                                <div><span style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 22, fontWeight: 800, color: stat.color }}>{stat.value}</span> <span style={{ fontSize: 13, fontWeight: 700, color: "#14141a" }}>{stat.label}</span></div>
                                <div style={{ fontSize: 11.5, color: "#9a9aa3" }}>{stat.sub}</div>
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>

                      {!goalMet ? (
                        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, padding: "16px 18px", borderRadius: 16, background: "rgba(226,72,63,0.07)", flexWrap: "wrap" }}>
                          <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
                            <div style={{ width: 46, height: 46, borderRadius: "50%", background: "rgba(226,72,63,0.12)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                              <Target size={21} color="#e2483f" />
                            </div>
                            <div>
                              <div style={{ fontSize: 16, fontWeight: 800, color: "#e2483f", lineHeight: 1.2 }}>{remaining} lead{remaining === 1 ? "" : "s"} restante{remaining === 1 ? "" : "s"}</div>
                              <div style={{ fontSize: 13, fontWeight: 600, color: "#6b6b75" }}>para bater a meta semanal</div>
                            </div>
                          </div>
                          <button onClick={() => setView("semana")} style={{ display: "flex", alignItems: "center", gap: 7, padding: "10px 16px", borderRadius: 12, border: "1px solid #eef0f3", background: "white", color: "#14141a", fontSize: 12.5, fontWeight: 700, cursor: "pointer", flexShrink: 0 }}>
                            <BarChart3 size={13} /> Ver progresso <ChevronRight size={13} />
                          </button>
                        </div>
                      ) : (
                        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, padding: "16px 18px", borderRadius: 16, background: "rgba(31,169,113,0.07)", flexWrap: "wrap" }}>
                          <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
                            <div style={{ width: 46, height: 46, borderRadius: "50%", background: "rgba(31,169,113,0.14)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                              <Trophy size={21} color="#059669" />
                            </div>
                            <div>
                              <div style={{ fontSize: 16, fontWeight: 800, color: "#059669", lineHeight: 1.2 }}>Meta da semana batida! 🎉</div>
                              <div style={{ fontSize: 13, fontWeight: 600, color: "#6b6b75" }}>continue assim até o fim da semana</div>
                            </div>
                          </div>
                          <button onClick={() => setView("semana")} style={{ display: "flex", alignItems: "center", gap: 7, padding: "10px 16px", borderRadius: 12, border: "1px solid #eef0f3", background: "white", color: "#14141a", fontSize: 12.5, fontWeight: 700, cursor: "pointer", flexShrink: 0 }}>
                            <BarChart3 size={13} /> Ver progresso <ChevronRight size={13} />
                          </button>
                        </div>
                      )}
                    </div>
                  </div>
                );
              })()}

              {/* Busca - destacada, separada dos filtros */}
              <div style={{
                display: "flex", alignItems: "center", gap: 10, marginBottom: 12,
                padding: "13px 16px", borderRadius: 14,
                background: "white", border: "1.5px solid #dcdfe6",
                boxShadow: "0 2px 8px -4px rgba(20,20,26,0.08)",
              }}>
                <Search size={18} style={{ color: "#6d5ef8", flexShrink: 0 }} />
                <input
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  placeholder="Buscar por empresa, telefone, email, responsável..."
                  style={{ border: "none", background: "transparent", outline: "none", fontSize: 14.5, fontWeight: 500, flex: 1, color: "#14141a" }}
                />
                {search && (
                  <button onClick={() => setSearch("")} style={{ border: "none", background: "rgba(148,163,184,0.15)", color: "#64748b", width: 22, height: 22, borderRadius: "50%", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                    <X size={12} />
                  </button>
                )}
              </div>

              {/* Filtros */}
              <Glass style={{ borderRadius: 16, padding: "10px 14px", marginBottom: 10, display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
                <Chip active={tempFilter === "all"} onClick={() => setTempFilter("all")} color="#0f172a">Todos</Chip>
                <Chip active={tempFilter === "hot"} onClick={() => setTempFilter("hot")} color={TEMP_CONFIG.hot.color} dotColor={TEMP_CONFIG.hot.color}>Quentes</Chip>
                <Chip active={tempFilter === "warm"} onClick={() => setTempFilter("warm")} color={TEMP_CONFIG.warm.color} dotColor={TEMP_CONFIG.warm.color}>Mornos</Chip>
                <Chip active={tempFilter === "cold"} onClick={() => setTempFilter("cold")} color={TEMP_CONFIG.cold.color} dotColor={TEMP_CONFIG.cold.color}>Frios</Chip>
                <Chip active={superOnly} onClick={() => setSuperOnly((v) => !v)} color="#6d5ef8" dotColor="#6d5ef8">⭐ Super lead</Chip>
                <div style={{ width: 1, height: 22, background: "rgba(148, 163, 184, 0.25)" }} />
                <Chip active={whatsappOnly} onClick={() => setWhatsappOnly((v) => !v)} color="#16a34a" count={stats.withWhatsapp}><MessageCircle size={13} style={{ marginRight: -2 }} /> Com WhatsApp</Chip>
              </Glass>

              <div style={{
                borderRadius: 20, padding: "14px 18px", marginBottom: 20, display: "flex", gap: 14, alignItems: "center", flexWrap: "wrap",
                background: "rgba(255, 255, 255, 0.6)",
                backdropFilter: "blur(20px) saturate(150%)", WebkitBackdropFilter: "blur(20px) saturate(150%)",
                border: "1.5px solid #a8dc2e",
                boxShadow: "0 8px 20px -12px rgba(127, 197, 21, 0.35)",
              }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", maxWidth: "100%" }}>
                  <span style={{ fontSize: 11, color: "#94a3b8", fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.6 }}>SDR</span>
                  <div style={{ display: "flex", gap: 5, flexWrap: "wrap" }}>
                    <Chip active={ownerFilter === "all"} onClick={() => setOwnerFilter("all")} color="#14141a">Todos</Chip>
                    {sdrs.map((s) => (
                      <Chip key={s.name} active={ownerFilter === s.name} onClick={() => setOwnerFilter(s.name)} color={s.color}>{s.name}</Chip>
                    ))}
                  </div>
                  <button onClick={() => setShowSdrManager(true)} title="Criar ou editar SDRs" style={{ display: "flex", alignItems: "center", gap: 5, padding: "6px 10px", borderRadius: 9, border: "1.5px dashed rgba(148,163,184,0.4)", background: "transparent", color: "#94a3b8", fontSize: 11.5, fontWeight: 400, cursor: "pointer", whiteSpace: "nowrap" }}>
                    <Plus size={12} /> SDR
                  </button>
                </div>
                <div style={{ width: 1, height: 22, background: "rgba(148,163,184,0.25)" }} />
                <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", maxWidth: "100%" }}>
                  <span style={{ fontSize: 11, color: "#94a3b8", fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.6 }}>Status</span>
                  <div style={{ display: "flex", gap: 5, flexWrap: "wrap" }}>
                    <Chip active={statusFilter === "all"} onClick={() => setStatusFilter("all")} color="#14141a">Todos</Chip>
                    <Chip active={statusFilter === "Atendido"} onClick={() => setStatusFilter("Atendido")} color="#e08a1c">Em atendimento</Chip>
                    <Chip active={statusFilter === "Desatendido"} onClick={() => setStatusFilter("Desatendido")} color="#e2483f">Negociação antiga</Chip>
                  </div>
                </div>
                <div style={{ flex: 1 }} />
                {hasActiveFilters && <button onClick={clearFilters} style={{ display: "flex", alignItems: "center", gap: 5, padding: "6px 11px", borderRadius: 9, border: "1px solid rgba(148,163,184,0.3)", background: "white", color: "#64748b", fontSize: 12, fontWeight: 400, cursor: "pointer", whiteSpace: "nowrap" }}><X size={12} /> Limpar filtros</button>}
                <div style={{ fontSize: 12, color: "#64748b", fontWeight: 600 }}>{filtered.length} de {leads.length} leads</div>
              </div>

              <Glass style={{ borderRadius: 16, padding: "10px 14px", marginBottom: 20, display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
                <span style={{ fontSize: 11, color: "#94a3b8", fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.6 }}>Fase da conversa</span>
                <Chip active={phaseFilter === "all"} onClick={() => setPhaseFilter("all")} color="#0f172a">Todas</Chip>
                {CONVERSATION_PHASES.map((p) => (
                  <Chip key={p.key} active={phaseFilter === p.key} onClick={() => setPhaseFilter(p.key)} color={p.color} dotColor={p.color} count={leads.filter((l) => (l.phase || "none") === p.key).length}>{p.label}</Chip>
                ))}
              </Glass>

              <Glass style={{ borderRadius: 16, padding: "10px 14px", marginBottom: 20, position: "relative" }}>
                <div
                  onClick={() => setOriginDropdownOpen((v) => !v)}
                  style={{ display: "flex", alignItems: "center", gap: 10, cursor: "pointer" }}
                >
                  <span style={{ fontSize: 11, color: "#94a3b8", fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.6, flexShrink: 0 }}>Origem do lead</span>
                  <div style={{ flex: 1 }}>
                    {originFilter === "all" ? (
                      <span style={{ fontSize: 12.5, color: "#64748b", fontWeight: 600 }}>Todas as origens</span>
                    ) : (
                      <span style={{ display: "inline-flex", alignItems: "center", gap: 5, fontSize: 12.5, fontWeight: 700, color: ORIGIN_BY_KEY[originFilter].color }}>
                        {(() => { const OI = ORIGIN_BY_KEY[originFilter].icon; return <OI size={13} />; })()}
                        {ORIGIN_BY_KEY[originFilter].label}
                      </span>
                    )}
                  </div>
                  {originFilter !== "all" && (
                    <button onClick={(e) => { e.stopPropagation(); setOriginFilter("all"); }} title="Limpar" style={{ border: "none", background: "rgba(148,163,184,0.15)", color: "#64748b", width: 20, height: 20, borderRadius: "50%", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                      <X size={11} />
                    </button>
                  )}
                  <ChevronRight size={15} color="#94a3b8" style={{ transform: originDropdownOpen ? "rotate(90deg)" : "none", transition: "transform 0.15s ease", flexShrink: 0 }} />
                </div>

                {originDropdownOpen && (
                  <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 12, paddingTop: 12, borderTop: "1px solid rgba(148,163,184,0.15)" }}>
                    <Chip active={originFilter === "all"} onClick={() => { setOriginFilter("all"); setOriginDropdownOpen(false); }} color="#0f172a">Todas</Chip>
                    {ORIGIN_OPTIONS.map((o) => (
                      <Chip key={o.key} active={originFilter === o.key} onClick={() => { setOriginFilter(o.key); setOriginDropdownOpen(false); }} color={o.color} count={leads.filter((l) => l.origin === o.key).length}>
                        <o.icon size={12} style={{ marginRight: -2 }} /> {o.label}
                      </Chip>
                    ))}
                  </div>
                )}
              </Glass>

              {filtered.length === 0 ? (
                <Glass style={{ borderRadius: 18, padding: "60px 20px", textAlign: "center" }}>
                  <Users size={32} style={{ color: "#cbd5e1", marginBottom: 12 }} />
                  <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 20, color: "#475569", marginBottom: 4 }}>Nenhum lead encontrado</div>
                  <div style={{ fontSize: 13, color: "#94a3b8" }}>{leads.length === 0 ? "Comece adicionando seu primeiro lead" : "Tente ajustar os filtros"}</div>
                </Glass>
              ) : (
                <div id="leads-grid" className="leads-grid">
                  {filtered.map((lead) => <LeadCard key={lead.id} lead={lead} onOpen={setSelected} onQuickContact={(type, lead) => setQuickContactLead(lead)} onToggleWeekFlag={toggleWeekFlag} onToggleSuper={toggleSuperAttention} onMarkContacted={markContactedToday} inWaList={waSendList.some((x) => x.leadId === lead.id)} onToggleWaList={() => handlePaperPlaneClick(lead)} />)}
                </div>
              )}

              <div style={{ textAlign: "center", marginTop: 40, marginBottom: 90, fontSize: 11, color: "#b3b3ba" }}>Pipeline · CRM B2B · {leads.length} leads · Dados salvos automaticamente</div>
            </>
          )}

          {/* ═══════════════════ DESATENDIDOS ═══════════════════ */}
          {view === "desatendidos" && (
            <>
              <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 20 }}>
                <button onClick={() => setView("dashboard")} style={{ width: 40, height: 40, borderRadius: 12, border: "1px solid rgba(255,255,255,0.8)", background: "rgba(255,255,255,0.6)", color: "#64748b", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}><ArrowLeft size={18} /></button>
                <div>
                  <h1 style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 28, fontWeight: 500, margin: 0, color: "#0f172a" }}>Negociações antigas</h1>
                  <div style={{ fontSize: 13, color: "#8b5cf6", fontWeight: 600 }}>{desatendidosFiltered.length} de {leads.length} leads precisam de retorno</div>
                </div>
              </div>

              <div style={{ display: "flex", gap: 8, marginBottom: 20, flexWrap: "wrap" }}>
                <Chip active={tempFilter === "all"} onClick={() => setTempFilter("all")} color="#0f172a">Todos</Chip>
                <Chip active={tempFilter === "hot"} onClick={() => setTempFilter("hot")} color={TEMP_CONFIG.hot.color} dotColor={TEMP_CONFIG.hot.color}>Quentes</Chip>
                <Chip active={tempFilter === "warm"} onClick={() => setTempFilter("warm")} color={TEMP_CONFIG.warm.color} dotColor={TEMP_CONFIG.warm.color}>Mornos</Chip>
                <Chip active={tempFilter === "cold"} onClick={() => setTempFilter("cold")} color={TEMP_CONFIG.cold.color} dotColor={TEMP_CONFIG.cold.color}>Frios</Chip>
                <Chip active={whatsappOnly} onClick={() => setWhatsappOnly((v) => !v)} color="#16a34a" count={desatendidosFiltered.filter(l=>l.whatsapp||l.hasWhatsapp).length}><MessageCircle size={13} style={{ marginRight: -2 }} /> Com WhatsApp</Chip>
              </div>

              {desatendidosFiltered.length === 0 ? (
                <Glass style={{ borderRadius: 18, padding: "50px 20px", textAlign: "center" }}>
                  <CheckCircle2 size={32} style={{ color: "#34d399", marginBottom: 12 }} />
                  <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 19, color: "#475569" }}>Nenhuma negociação antiga por aqui 🎉</div>
                </Glass>
              ) : (
                desatendidosFiltered.map((lead) => <DesatendidoCard key={lead.id} lead={lead} onOpen={setSelected} onQuickContact={(type, lead) => setQuickContactLead(lead)} onToggleWeekDone={toggleWeekDone} onToggleSuper={toggleSuperAttention} />)
              )}
            </>
          )}

          {/* ═══════════════════ LISTA DA SEMANA (montada por tag manual) ═══════════════════ */}
          {view === "semana" && (
            <>
              <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 16 }}>
                <button onClick={() => setView("dashboard")} style={{ width: 40, height: 40, borderRadius: 12, border: "1px solid rgba(255,255,255,0.8)", background: "rgba(255,255,255,0.6)", color: "#64748b", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}><ArrowLeft size={18} /></button>
                <div style={{ flex: 1 }}>
                  <h1 style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 28, fontWeight: 500, margin: 0, color: "#0f172a" }}>Abordar essa semana</h1>
                  <div style={{ fontSize: 13, color: "#059669", fontWeight: 600 }}>{stats.weekList.length} pendentes · {stats.weekDoneCount} já feitos</div>
                </div>
                <button
                  onClick={() => setShowWeekHistory(true)}
                  title="Ver histórico de semanas e meses anteriores"
                  style={{ display: "flex", alignItems: "center", gap: 6, padding: "9px 13px", borderRadius: 12, border: "1px solid rgba(109,94,248,0.25)", background: "rgba(109,94,248,0.08)", color: "#6d5ef8", fontSize: 12, fontWeight: 700, cursor: "pointer", flexShrink: 0 }}
                >
                  <ClipboardList size={13} /> Histórico
                </button>
              </div>

              {stats.weekTotalTagged > 0 && (
                <Glass style={{ borderRadius: 16, padding: "12px 16px", marginBottom: 18 }}>
                  <ProgressDots total={stats.weekTotalTagged} done={stats.weekDoneCount} />
                </Glass>
              )}

              {stats.weekList.length === 0 ? (
                <Glass style={{ borderRadius: 18, padding: "50px 20px", textAlign: "center" }}>
                  <CheckCircle2 size={32} style={{ color: "#34d399", marginBottom: 12 }} />
                  <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 19, color: "#475569", marginBottom: 6 }}>Nenhum lead marcado pra semana</div>
                  <div style={{ fontSize: 13, color: "#94a3b8" }}>Abra um lead na lista principal e adicione a tag "Hoje" ou "Esta semana"</div>
                </Glass>
              ) : (
                <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))", gap: 10 }}>
                  {stats.weekList.map((lead) => <WeekSquareCard key={lead.id} lead={lead} onOpen={setSelected} onDone={() => toggleWeekDone(lead.id)} onToggleSuper={toggleSuperAttention} />)}
                </div>
              )}

              {/* Concluídos essa semana - agora mostra POR QUAL CANAL cada um foi resolvido */}
              {stats.weekCompleted.length > 0 && (
                <div style={{ marginTop: 24 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 10 }}>
                    <CheckCircle2 size={15} color="#059669" />
                    <span style={{ fontSize: 14, fontWeight: 700, color: "#0f172a" }}>Concluídos essa semana</span>
                    <span style={{ fontSize: 11, fontWeight: 700, color: "#059669", background: "rgba(16,185,129,0.12)", padding: "2px 8px", borderRadius: 7 }}>{stats.weekCompleted.length}</span>
                  </div>
                  <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                    {stats.weekCompleted.map((lead) => {
                      const via = WEEK_VIA_CONFIG[lead.weekDoneVia] || WEEK_VIA_CONFIG.manual;
                      return (
                        <div
                          key={lead.id}
                          onClick={() => setSelected(lead)}
                          style={{
                            display: "flex", alignItems: "center", gap: 12, padding: "12px 14px", cursor: "pointer",
                            background: "white", borderRadius: 16, border: `1px solid ${via.color}25`,
                            boxShadow: `0 2px 10px -6px ${via.color}30`,
                          }}
                        >
                          <div style={{ width: 34, height: 34, borderRadius: "50%", background: via.color + "18", color: via.color, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                            <via.icon size={15} />
                          </div>
                          <div style={{ flex: 1, minWidth: 0 }}>
                            <div style={{ fontSize: 13.5, fontWeight: 700, color: "#0f172a", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{lead.company}</div>
                            <div style={{ display: "flex", alignItems: "center", gap: 5, marginTop: 2 }}>
                              <span style={{ fontSize: 10, fontWeight: 800, color: via.color, background: via.color + "14", padding: "1.5px 7px", borderRadius: 20 }}>{via.label}</span>
                              <span style={{ fontSize: 11, color: "#94a3b8" }}>{lead.owner}</span>
                            </div>
                          </div>
                          <button
                            onClick={(e) => { e.stopPropagation(); toggleWeekDone(lead.id); }}
                            title="Reabrir - voltar para a lista de pendentes"
                            style={{ fontSize: 11, fontWeight: 700, color: "#6d5ef8", background: "rgba(109,94,248,0.1)", border: "none", borderRadius: 9, padding: "7px 11px", cursor: "pointer", flexShrink: 0 }}
                          >
                            Reabrir
                          </button>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}
            </>
          )}

          {/* ═══════════════════ AGENDA ═══════════════════ */}
          {view === "agenda" && (
            <>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 20, flexWrap: "wrap", gap: 12 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
                  <button onClick={() => setView("dashboard")} style={{ width: 40, height: 40, borderRadius: 12, border: "1px solid rgba(255,255,255,0.8)", background: "rgba(255,255,255,0.6)", color: "#64748b", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}><ArrowLeft size={18} /></button>
                  <div>
                    <h1 style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 28, fontWeight: 500, margin: 0, color: "#0f172a" }}>Agenda comercial</h1>
                    <div style={{ fontSize: 13, color: "#8b5cf6", fontWeight: 600, textTransform: "capitalize" }}>{agendaDate.toLocaleDateString("pt-BR", { weekday: "long", day: "2-digit", month: "long" })}</div>
                  </div>
                </div>
                <div style={{ display: "flex", gap: 8 }}>
                  <button onClick={createMeeting} style={{ display: "flex", alignItems: "center", gap: 7, padding: "10px 16px", borderRadius: 12, border: "1px solid rgba(148,163,184,0.25)", background: "white", color: "#6366f1", fontSize: 12.5, fontWeight: 700, cursor: "pointer" }}><Plus size={14} /> Nova reunião</button>
                  <button onClick={shareAgenda} className="glow-btn" style={{ display: "flex", alignItems: "center", gap: 7, padding: "10px 16px", borderRadius: 12, border: "none", background: "linear-gradient(135deg, #6366f1, #8b5cf6)", color: "white", fontSize: 12.5, fontWeight: 700, cursor: "pointer", boxShadow: "0 8px 22px -8px rgba(99,102,241,0.5)" }}><Share2 size={14} /> Compartilhar agenda</button>
                </div>
              </div>

              <Glass style={{ borderRadius: 20, padding: "16px 18px", marginBottom: 16 }}>
                <DayStrip selectedDate={agendaDate} onSelect={setAgendaDate} meetings={meetings} />
                <button onClick={() => setMonthExpanded((v) => !v)} style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 12, padding: "8px 4px", border: "none", background: "transparent", color: "#8b5cf6", fontSize: 12.5, fontWeight: 700, cursor: "pointer" }}>
                  <CalendarIcon size={14} /> {monthExpanded ? "Recolher calendário" : "Expandir calendário"} <ChevronRight size={14} style={{ transform: monthExpanded ? "rotate(90deg)" : "none", transition: "transform 0.2s ease" }} />
                </button>
                {monthExpanded && <div style={{ marginTop: 14, paddingTop: 14, borderTop: "1px solid rgba(148,163,184,0.15)" }}><MonthGrid selectedDate={agendaDate} onSelect={(d) => { setAgendaDate(d); }} meetings={meetings} /></div>}
              </Glass>

              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(110px, 1fr))", gap: 10, marginBottom: 20 }}>
                {[
                  { label: "Reuniões", count: meetingCounts.reuniao, color: "#6366f1", icon: Users2 },
                  { label: "Follow-ups", count: meetingCounts.followup, color: "#10b981", icon: Phone },
                  { label: "Propostas", count: meetingCounts.proposta, color: "#f59e0b", icon: FileText },
                  { label: "Apresentações", count: meetingCounts.apresentacao, color: "#8b5cf6", icon: Video },
                  { label: "Total hoje", count: dayMeetings.length, color: "#0f172a", icon: ClipboardList },
                ].map((s) => (
                  <Glass key={s.label} style={{ borderRadius: 14, padding: "12px 14px", textAlign: "center" }}>
                    <div style={{ width: 30, height: 30, borderRadius: 9, background: s.color + "15", color: s.color, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 8px" }}><s.icon size={14} /></div>
                    <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 20, fontWeight: 500, color: "#0f172a" }}>{s.count}</div>
                    <div style={{ fontSize: 10.5, color: "#94a3b8", fontWeight: 600 }}>{s.label}</div>
                  </Glass>
                ))}
              </div>

              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
                <span style={{ fontSize: 15, fontWeight: 700, color: "#0f172a", textTransform: "capitalize" }}>{isSameDay(agendaDate, today) ? "Hoje" : agendaDate.toLocaleDateString("pt-BR", { weekday: "long" })} • {agendaDate.toLocaleDateString("pt-BR", { day: "2-digit", month: "long" })}</span>
              </div>

              {dayMeetings.length === 0 ? (
                <Glass style={{ borderRadius: 18, padding: "40px 20px", textAlign: "center" }}>
                  <CalendarIcon size={28} style={{ color: "#c4b5fd", marginBottom: 10 }} />
                  <div style={{ fontSize: 14, color: "#94a3b8" }}>Nenhuma reunião marcada para este dia</div>
                </Glass>
              ) : (
                dayMeetings.map((m) => <MeetingListItem key={m.id} meeting={m} onOpen={setSelectedMeeting} />)
              )}
            </>
          )}

          {/* ═══════════════════ CONQUISTADOS (deals fechados) ═══════════════════ */}
          {view === "conquistados" && (
            <>
              <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 16 }}>
                <button onClick={() => setView("dashboard")} style={{ width: 40, height: 40, borderRadius: 12, border: "1px solid rgba(255,255,255,0.8)", background: "rgba(255,255,255,0.6)", color: "#64748b", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}><ArrowLeft size={18} /></button>
                <div>
                  <h1 style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 28, fontWeight: 800, margin: 0, color: "#14141a" }}>Conquistados</h1>
                  <div style={{ fontSize: 13, color: "#1fa971", fontWeight: 700 }}>
                    {wonLeads.length} negócios fechados
                    {wonTotalOnce > 0 && <> · {formatBRL(wonTotalOnce)} único</>}
                    {wonTotalMonthly > 0 && <> · {formatBRL(wonTotalMonthly)}<span style={{ fontWeight: 600 }}>/mês</span> recorrente</>}
                  </div>
                </div>
              </div>

              {/* Filtro de período por data de fechamento */}
              <Glass style={{ borderRadius: 16, padding: "10px 14px", marginBottom: 18, display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                <span style={{ fontSize: 11, color: "#94a3b8", fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.6 }}>Fechados em</span>
                {[
                  { key: "30", label: "Últimos 30 dias" },
                  { key: "90", label: "Últimos 90 dias" },
                  { key: "365", label: "Este ano" },
                  { key: "all", label: "Tudo" },
                ].map((p) => (
                  <Chip key={p.key} active={wonPeriod === p.key} onClick={() => setWonPeriod(p.key)} color="#1fa971">{p.label}</Chip>
                ))}
              </Glass>

              {wonLeads.length === 0 ? (
                <Glass style={{ borderRadius: 18, padding: "50px 20px", textAlign: "center" }}>
                  <CheckImgIcon size={32} style={{ marginBottom: 12 }} />
                  <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 19, color: "#475569", marginBottom: 6 }}>Nenhum negócio fechado nesse período</div>
                  <div style={{ fontSize: 13, color: "#94a3b8" }}>Tente ajustar o filtro ou feche seu primeiro negócio</div>
                </Glass>
              ) : (
                <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                  {wonLeads.map((lead) => (
                    <Glass
                      key={lead.id}
                      onClick={() => setSelected(lead)}
                      style={{ borderRadius: 16, padding: "14px 16px", cursor: "pointer", display: "flex", alignItems: "center", gap: 14, flexWrap: "wrap" }}
                    >
                      <div style={{ width: 38, height: 38, borderRadius: 12, background: "rgba(31,169,113,0.12)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                        <CheckImgIcon size={18} />
                      </div>
                      <div style={{ flex: 1, minWidth: 160 }}>
                        <div style={{ fontSize: 14.5, fontWeight: 700, color: "#14141a" }}>{lead.company}</div>
                        <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 2, flexWrap: "wrap" }}>
                          <OwnerAvatar name={lead.owner} size={16} />
                          <span style={{ fontSize: 11.5, color: "#9a9aa3" }}>{lead.owner}</span>
                          <span style={{
                            fontSize: 9.5, fontWeight: 700, padding: "1px 7px", borderRadius: 6,
                            background: lead.dealType === "mensal" ? "rgba(109,94,248,0.12)" : "rgba(148,163,184,0.15)",
                            color: lead.dealType === "mensal" ? "#6d5ef8" : "#64748b",
                          }}>
                            {lead.dealType === "mensal" ? "Fee mensal" : "Pagamento único"}
                          </span>
                          <span style={{ fontSize: 9.5, fontWeight: 700, padding: "1px 7px", borderRadius: 6, background: "rgba(31,169,113,0.12)", color: "#1fa971" }}>
                            {CONTRACT_PERIOD_OPTIONS.find((p) => p.key === (lead.contractPeriod || "mensal"))?.label || "Mensal"}
                          </span>
                        </div>
                      </div>
                      <div style={{ textAlign: "right" }}>
                        <div style={{ fontSize: 10.5, color: "#9a9aa3", fontWeight: 600 }}>Data de fechamento</div>
                        <div style={{ fontSize: 13, fontWeight: 700, color: "#14141a" }}>{lead.wonDate ? formatDateFull(lead.wonDate) : "não informada"}</div>
                      </div>
                      <div style={{ textAlign: "right", minWidth: 100 }}>
                        <div style={{ fontSize: 10.5, color: "#9a9aa3", fontWeight: 600 }}>Valor do contrato</div>
                        <div style={{ fontSize: 15, fontWeight: 800, color: "#1fa971" }}>{formatBRL(getDealValue(lead))}{lead.dealType === "mensal" && <span style={{ fontSize: 11, fontWeight: 600 }}>/mês</span>}</div>
                      </div>
                      <button
                        onClick={(e) => { e.stopPropagation(); toggleSuperAttention(lead.id); }}
                        title={lead.superAttention ? "Remover marcação de Super lead" : "Marcar como Super lead"}
                        style={{ border: "none", background: "transparent", cursor: "pointer", padding: 2, opacity: lead.superAttention ? 1 : 0.3 }}
                      >
                        <StarImgIcon size={16} />
                      </button>
                      <ChevronRight size={16} color="#c4c4cc" />
                    </Glass>
                  ))}
                </div>
              )}
            </>
          )}

          {/* ═══════════════════ ASSISTENTE IA (chat com contexto do funil) ═══════════════════ */}
          {view === "assistente" && (
            <>
              <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 14 }}>
                <button onClick={() => setView("dashboard")} style={{ width: 40, height: 40, borderRadius: 12, border: "1px solid rgba(255,255,255,0.8)", background: "rgba(255,255,255,0.6)", color: "#64748b", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><ArrowLeft size={18} /></button>
                <img src="/funnio-icon-round.png" alt="Funnio" style={{ width: 40, height: 40, borderRadius: "50%", flexShrink: 0, boxShadow: "0 4px 12px -4px rgba(215,250,60,0.4)" }} />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <h1 style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 17, fontWeight: 800, margin: 0, color: "#14141a" }}>Olá, sou o gestor IA do seu Funnio</h1>
                  <div style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 11.5, color: "#9a9aa3" }}>
                    <span style={{ width: 6, height: 6, borderRadius: "50%", background: "#1fa971", flexShrink: 0 }} />
                    Online · conhece seu funil em tempo real
                  </div>
                </div>
                {chatMessages.length > 0 && (
                  <button
                    onClick={() => { setChatMessages([]); setChatError(""); }}
                    title="Começar uma conversa nova"
                    style={{ display: "flex", alignItems: "center", gap: 6, padding: "8px 10px", borderRadius: 10, border: "1px solid #eef0f3", background: "white", color: "#64748b", fontSize: 11.5, fontWeight: 600, cursor: "pointer", flexShrink: 0 }}
                  >
                    <Sparkles size={12} /> Nova
                  </button>
                )}
              </div>

              <div
                style={{
                  display: "flex", flexDirection: "column", gap: 4, marginBottom: 12,
                  borderRadius: 20, padding: "16px 14px",
                  paddingBottom: 110,
                  backgroundImage: "radial-gradient(circle at 1px 1px, rgba(20,20,26,0.05) 1px, transparent 0)",
                  backgroundSize: "16px 16px",
                  background: "rgba(255,255,255,0.4)",
                  border: "1px solid rgba(255,255,255,0.7)",
                }}
              >
                {chatMessages.length === 0 && (
                  <div style={{ display: "flex", alignItems: "flex-start", gap: 8, marginBottom: 6 }}>
                    <img src="/funnio-icon-round.png" alt="Funnio" style={{ width: 28, height: 28, borderRadius: "50%", flexShrink: 0, marginTop: 2 }} />
                    <div style={{
                      maxWidth: "85%", padding: "13px 16px", borderRadius: "4px 16px 16px 16px",
                      background: "white", border: "1px solid #eef0f3", boxShadow: "0 2px 8px -4px rgba(20,20,26,0.08)",
                    }}>
                      <div style={{ fontSize: 13.5, fontWeight: 700, color: "#14141a", marginBottom: 6 }}>Oi! Pergunte qualquer coisa sobre seu funil 👋</div>
                      <div style={{ fontSize: 12.5, color: "#6b6b75", lineHeight: 1.5, marginBottom: 12 }}>
                        Já sei quais leads estão parados, quais estão quentes sem retorno, o que tem marcado pra semana e as reuniões que vêm por aí. Não precisa me explicar nada, é só perguntar.
                      </div>
                      <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                        {[
                          "Crie script de abordagem",
                          "O que eu preciso fazer essa semana?",
                          "Quais leads estão esquecidos há mais tempo?",
                          "Quem eu deveria priorizar hoje?",
                        ].map((suggestion) => (
                          <button
                            key={suggestion}
                            onClick={() => sendChatMessage(suggestion)}
                            style={{ textAlign: "left", padding: "9px 13px", borderRadius: 10, border: "1px solid #eef0f3", background: "#fafbfc", color: "#14141a", fontSize: 12.5, fontWeight: 600, cursor: "pointer" }}
                          >
                            {suggestion}
                          </button>
                        ))}
                      </div>
                    </div>
                  </div>
                )}

                {chatMessages.map((m, i) => {
                  const isUser = m.role === "user";
                  const prevSameRole = i > 0 && chatMessages[i - 1].role === m.role;
                  const time = m.ts ? new Date(m.ts).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" }) : null;
                  return (
                    <div key={i} style={{ display: "flex", justifyContent: isUser ? "flex-end" : "flex-start", alignItems: "flex-end", gap: 8, marginTop: prevSameRole ? 3 : 12 }}>
                      {!isUser && (
                        <img src="/funnio-icon-round.png" alt="Funnio" style={{ width: 24, height: 24, borderRadius: "50%", flexShrink: 0, visibility: prevSameRole ? "hidden" : "visible" }} />
                      )}
                      <div style={{ display: "flex", flexDirection: "column", alignItems: isUser ? "flex-end" : "flex-start", maxWidth: "78%" }}>
                        <div style={{
                          padding: "10px 14px",
                          borderRadius: isUser
                            ? (prevSameRole ? "16px 4px 4px 16px" : "16px 16px 4px 16px")
                            : (prevSameRole ? "4px 16px 16px 4px" : "4px 16px 16px 16px"),
                          background: isUser ? "linear-gradient(135deg, #d7fa3c, #c4e82a)" : "white",
                          color: isUser ? "#14141a" : "#14141a",
                          border: isUser ? "none" : "1px solid #eef0f3",
                          fontSize: 13.5, lineHeight: 1.55, whiteSpace: "pre-wrap",
                          boxShadow: isUser ? "0 4px 12px -6px rgba(215,250,60,0.5)" : "0 2px 8px -4px rgba(20,20,26,0.08)",
                        }}>
                          {m.content}
                        </div>
                        {time && <span style={{ fontSize: 9.5, color: "#b4b6bc", marginTop: 3, padding: "0 4px" }}>{time}</span>}
                      </div>
                    </div>
                  );
                })}

                {chatLoading && (
                  <div style={{ display: "flex", justifyContent: "flex-start", alignItems: "flex-end", gap: 8, marginTop: 12 }}>
                    <img src="/funnio-icon-round.png" alt="Funnio" style={{ width: 24, height: 24, borderRadius: "50%", flexShrink: 0 }} />
                    <div style={{ padding: "12px 16px", borderRadius: "4px 16px 16px 16px", background: "white", border: "1px solid #eef0f3", display: "flex", alignItems: "center", gap: 4 }}>
                      {[0, 1, 2].map((d) => (
                        <span key={d} style={{ width: 6, height: 6, borderRadius: "50%", background: "#c4c4cc", animation: `typingDot 1.1s ease-in-out ${d * 0.15}s infinite` }} />
                      ))}
                    </div>
                  </div>
                )}

                {chatError && (
                  <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "10px 14px", borderRadius: 12, background: "rgba(226,72,63,0.08)", border: "1px solid rgba(226,72,63,0.25)", marginTop: 12 }}>
                    <AlertCircle size={14} color="#e2483f" />
                    <span style={{ fontSize: 12, color: "#7f1d1d" }}>{chatError}</span>
                  </div>
                )}
              </div>

              {/* Barra inferior fixa: chips de sugestão + campo de digitar, sempre grudados
                  no fundo da tela (acima do menu), nunca soltos no meio de espaço vazio. */}
              <div style={{ position: "fixed", bottom: 76, left: 0, right: 0, zIndex: 80, padding: "0 16px" }}>
                <div style={{ maxWidth: 480, margin: "0 auto" }}>
                  {chatMessages.length > 0 && (
                    <div style={{ display: "flex", gap: 6, overflowX: "auto", paddingBottom: 8 }}>
                      {[
                        "Crie script de abordagem",
                        "O que eu preciso fazer essa semana?",
                        "Quem eu deveria priorizar hoje?",
                        "Resumo das negociações antigas",
                      ].map((suggestion) => (
                        <button
                          key={suggestion}
                          onClick={() => sendChatMessage(suggestion)}
                          disabled={chatLoading}
                          style={{ flexShrink: 0, whiteSpace: "nowrap", padding: "7px 13px", borderRadius: 20, border: "1px solid #e2e4e9", background: "white", color: "#6d5ef8", fontSize: 11.5, fontWeight: 500, cursor: chatLoading ? "default" : "pointer", opacity: chatLoading ? 0.5 : 1, boxShadow: "0 4px 14px -6px rgba(20,20,26,0.15)" }}
                        >
                          {suggestion}
                        </button>
                      ))}
                    </div>
                  )}

                  <div style={{ display: "flex", gap: 8, alignItems: "flex-end", background: "rgba(245,243,255,0.95)", backdropFilter: "blur(10px)", padding: "8px", borderRadius: 20, boxShadow: "0 10px 30px -10px rgba(20,20,26,0.25)" }}>
                    <textarea
                      value={chatInput}
                      onChange={(e) => setChatInput(e.target.value)}
                      onKeyDown={(e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendChatMessage(chatInput); } }}
                      placeholder="Escreva uma mensagem..."
                      disabled={chatLoading}
                      rows={2}
                      style={{ flex: 1, padding: "14px 16px", borderRadius: 16, border: "1.5px solid #dcdfe6", background: "white", fontSize: 14, outline: "none", color: "#14141a", resize: "none", fontFamily: "inherit", lineHeight: 1.4, maxHeight: 110 }}
                    />
                    <button
                      onClick={() => sendChatMessage(chatInput)}
                      disabled={!chatInput.trim() || chatLoading}
                      style={{ width: 52, height: 52, borderRadius: 16, border: "none", background: chatInput.trim() && !chatLoading ? "linear-gradient(135deg, #6d5ef8, #8b7bfa)" : "#eef0f3", color: chatInput.trim() && !chatLoading ? "white" : "#b4b6bc", cursor: chatInput.trim() && !chatLoading ? "pointer" : "not-allowed", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}
                    >
                      <ChevronRight size={20} />
                    </button>
                  </div>
                </div>
              </div>
            </>
          )}

          {/* ═══════════════════ METAS (configuração) ═══════════════════ */}
          {view === "metas" && (
            <>
              <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 16 }}>
                <button onClick={() => setView("dashboard")} style={{ width: 40, height: 40, borderRadius: 12, border: "1px solid rgba(255,255,255,0.8)", background: "rgba(255,255,255,0.6)", color: "#64748b", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}><ArrowLeft size={18} /></button>
                <div>
                  <h1 style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 28, fontWeight: 800, margin: 0, color: "#14141a" }}>Configurar metas</h1>
                  <div style={{ fontSize: 13, color: "#9a9aa3" }}>Ative só as metas que quiser acompanhar - cada uma gera badges automáticas</div>
                </div>
              </div>

              <div style={{ display: "flex", flexDirection: "column", gap: 12, marginBottom: 20 }}>
                {METRIC_KEYS.map((metricKey) => {
                  const metric = METRIC_DEFS[metricKey];
                  const cfg = goalsConfig[metricKey];
                  const MetricIcon = metric.icon;
                  const updateCfg = (patch) => setGoalsConfig((prev) => ({ ...prev, [metricKey]: { ...prev[metricKey], ...patch } }));
                  return (
                    <Glass key={metricKey} style={{ borderRadius: 18, padding: "18px 20px", border: cfg.enabled ? `1.5px solid ${metric.color}55` : undefined }}>
                      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, marginBottom: cfg.enabled ? 16 : 0 }}>
                        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                          <div style={{ width: 40, height: 40, borderRadius: 12, background: metric.color + "18", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                            <MetricIcon size={19} color={metric.color} />
                          </div>
                          <div>
                            <div style={{ fontSize: 15, fontWeight: 700, color: "#14141a" }}>{metric.label}</div>
                            <div style={{ fontSize: 11.5, color: "#9a9aa3" }}>{cfg.enabled ? `Meta: ${cfg.target} por ${periodNoun(cfg.period)}` : "Desativada"}</div>
                          </div>
                        </div>
                        <ToggleSwitch on={cfg.enabled} onClick={() => updateCfg({ enabled: !cfg.enabled })} activeColor={metric.color} />
                      </div>

                      {cfg.enabled && (
                        <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "flex-end" }}>
                          <div>
                            <label style={{ ...labelStyle, marginBottom: 4 }}>Período</label>
                            <div style={{ display: "flex", gap: 5, flexWrap: "wrap" }}>
                              {PERIOD_OPTIONS.map((p) => (
                                <button
                                  key={p.key}
                                  onClick={() => updateCfg({ period: p.key })}
                                  style={{
                                    padding: "8px 14px", borderRadius: 9,
                                    border: `1.5px solid ${cfg.period === p.key ? metric.color : "rgba(148,163,184,0.3)"}`,
                                    background: cfg.period === p.key ? metric.color + "15" : "white",
                                    color: cfg.period === p.key ? metric.color : "#64748b",
                                    fontSize: 12.5, fontWeight: cfg.period === p.key ? 700 : 500, cursor: "pointer",
                                  }}
                                >
                                  {p.label}
                                </button>
                              ))}
                            </div>
                          </div>
                          <div>
                            <label style={{ ...labelStyle, marginBottom: 4 }}>Meta (quantidade)</label>
                            <input
                              type="number"
                              min={1}
                              value={cfg.target}
                              onChange={(e) => updateCfg({ target: Math.max(1, parseInt(e.target.value, 10) || 1) })}
                              style={{ ...inputStyle, width: 100 }}
                            />
                          </div>
                          <div style={{ flex: 1, minWidth: 160, fontSize: 11, color: "#9a9aa3", lineHeight: 1.5 }}>
                            🏅 Badge 50% aos {Math.round(cfg.target * 0.5)} · ⭐ Super Badge aos {cfg.target} · 👑 Badge Lendária aos {Math.round(cfg.target * 1.5)}
                          </div>
                        </div>
                      )}
                    </Glass>
                  );
                })}
              </div>

              <Glass style={{ borderRadius: 16, padding: "14px 18px", marginBottom: 90, display: "flex", alignItems: "center", gap: 10 }}>
                <Trophy size={18} color="#b8860b" />
                <div style={{ fontSize: 12.5, color: "#6b6b75" }}>
                  Toda vez que um SDR chega na metade da meta ele ganha a <strong>Badge 50%</strong>, quando bate a meta ganha a <strong>Super Badge</strong>, e se passar bem além ganha a <strong>Badge Lendária</strong> - tudo automático.{" "}
                  <span onClick={() => setView("conquistas")} style={{ color: "#6d5ef8", fontWeight: 700, cursor: "pointer" }}>Ver conquistas →</span>
                </div>
              </Glass>
            </>
          )}

          {/* ═══════════════════ CONQUISTAS (badges acumuladas) ═══════════════════ */}
          {view === "conquistas" && (
            <>
              <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 16 }}>
                <button onClick={() => setView("dashboard")} style={{ width: 40, height: 40, borderRadius: 12, border: "1px solid rgba(255,255,255,0.8)", background: "rgba(255,255,255,0.6)", color: "#64748b", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}><ArrowLeft size={18} /></button>
                <div>
                  <h1 style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 28, fontWeight: 800, margin: 0, color: "#14141a" }}>Conquistas</h1>
                  <div style={{ fontSize: 13, color: "#9a9aa3" }}>{earnedBadges.length} badge{earnedBadges.length === 1 ? "" : "s"} conquistada{earnedBadges.length === 1 ? "" : "s"} no total</div>
                </div>
              </div>

              <Glass style={{ borderRadius: 16, padding: "10px 14px", marginBottom: 18, display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                <span style={{ fontSize: 11, color: "#94a3b8", fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.6 }}>SDR</span>
                <Chip active={achievementsFilterSdr === "all"} onClick={() => setAchievementsFilterSdr("all")} color="#14141a">Todos</Chip>
                {sdrs.map((s) => (
                  <Chip key={s.name} active={achievementsFilterSdr === s.name} onClick={() => setAchievementsFilterSdr(s.name)} color={s.color}>{s.name}</Chip>
                ))}
                <button onClick={() => setView("metas")} style={{ marginLeft: "auto", display: "flex", alignItems: "center", gap: 6, padding: "6px 11px", borderRadius: 9, border: "1px dashed rgba(148,163,184,0.4)", background: "transparent", color: "#94a3b8", fontSize: 11.5, fontWeight: 600, cursor: "pointer" }}>
                  <Settings2 size={12} /> Configurar metas
                </button>
              </Glass>

              {/* Uma fileira de conquistas para cada tipo de meta - colorida só se a meta estiver ativa */}
              <div style={{ display: "flex", flexDirection: "column", gap: 16, marginBottom: 20 }}>
                {METRIC_KEYS.map((metricKey) => {
                  const metric = METRIC_DEFS[metricKey];
                  const MetricIcon = metric.icon;
                  const cfg = goalsConfig[metricKey];
                  const isActive = cfg.enabled;
                  const iconColor = isActive ? metric.color : "#9a9aa3";
                  const iconBg = isActive ? metric.color + "18" : "rgba(148,163,184,0.12)";
                  const metricHistory = earnedBadges
                    .filter((b) => b.metric === metricKey && (achievementsFilterSdr === "all" || b.sdrName === achievementsFilterSdr))
                    .sort((a, b) => new Date(b.earnedAt) - new Date(a.earnedAt));
                  const isExpanded = expandedHistoryMetric === metricKey;
                  return (
                    <Glass key={metricKey} style={{ borderRadius: 20, padding: "18px 20px", opacity: isActive ? 1 : 0.75 }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 16, flexWrap: "wrap" }}>
                        <div style={{ width: 42, height: 42, borderRadius: 12, background: iconBg, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, filter: isActive ? "none" : "grayscale(1)" }}>
                          <MetricIcon size={19} color={iconColor} />
                        </div>
                        <div>
                          <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                            <span style={{ fontSize: 15, fontWeight: 800, color: isActive ? "#14141a" : "#6b6b75" }}>{metric.label}</span>
                            {isActive && (
                              <span style={{ fontSize: 10, fontWeight: 700, color: metric.color, background: metric.color + "15", padding: "2px 8px", borderRadius: 6 }}>
                                {PERIOD_OPTIONS.find((p) => p.key === cfg.period)?.label || "Semanal"} · meta {cfg.target}
                              </span>
                            )}
                            {!isActive && (
                              <span style={{ fontSize: 10, fontWeight: 700, color: "#64748b", background: "rgba(148,163,184,0.15)", padding: "2px 8px", borderRadius: 6 }}>
                                Meta não ativa
                              </span>
                            )}
                          </div>
                          <div style={{ fontSize: 12, color: "#9a9aa3" }}>{metric.description}</div>
                        </div>
                      </div>
                      <div className="ach-grid3" style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 8, filter: isActive ? "none" : "grayscale(1)" }}>
                        {BADGE_TIERS.map((tier) => {
                          const count = earnedBadges.filter((b) => b.metric === metricKey && b.tier === tier.key && (achievementsFilterSdr === "all" || b.sdrName === achievementsFilterSdr)).length;
                          return (
                            <div key={tier.key} style={{ display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center", gap: 6 }}>
                              <AchievementHex tier={tier} metric={metric} active={isActive} size={56} />
                              <div style={{ fontSize: 17, fontWeight: 800, color: isActive ? "#14141a" : "#6b6b75", lineHeight: 1 }}>{count}</div>
                              <div>
                                <div className="ach-tier-label" style={{ fontSize: 11, fontWeight: 700, color: isActive ? tier.color : "#9a9aa3" }}>{tier.label}</div>
                                <div className="ach-tier-desc" style={{ fontSize: 9, color: "#9a9aa3", lineHeight: 1.25, marginTop: 1 }}>{tier.description}</div>
                              </div>
                            </div>
                          );
                        })}
                      </div>

                      {/* Histórico expandível - mostra as conquistas passadas dessa meta, período por período */}
                      <div style={{ marginTop: 14, paddingTop: 14, borderTop: "1px solid rgba(148,163,184,0.15)" }}>
                        <button
                          onClick={() => metricHistory.length > 0 && setExpandedHistoryMetric(isExpanded ? null : metricKey)}
                          disabled={metricHistory.length === 0}
                          style={{ display: "flex", alignItems: "center", gap: 6, border: "none", background: "transparent", color: metricHistory.length > 0 ? "#6d5ef8" : "#b4b6bc", fontSize: 12, fontWeight: 700, cursor: metricHistory.length > 0 ? "pointer" : "default", padding: 0, width: "100%" }}
                        >
                          <ChevronRight size={13} style={{ transform: isExpanded ? "rotate(90deg)" : "none", transition: "transform 0.15s ease" }} />
                          {isExpanded ? "Esconder" : "Ver"} histórico ({metricHistory.length})
                        </button>
                        {isExpanded && metricHistory.length > 0 && (
                          <div style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 10 }}>
                            {metricHistory.map((b) => {
                              const bTier = BADGE_TIERS.find((t) => t.key === b.tier);
                              return (
                                <div key={b.id} style={{ display: "flex", alignItems: "center", gap: 8, padding: "7px 10px", borderRadius: 9, background: "rgba(248,248,250,0.7)" }}>
                                  <span style={{ width: 8, height: 8, borderRadius: "50%", background: bTier.color, flexShrink: 0 }} />
                                  <span style={{ fontSize: 11.5, fontWeight: 700, color: "#14141a" }}>{b.sdrName}</span>
                                  <span style={{ fontSize: 11, color: bTier.color, fontWeight: 600 }}>{bTier.label}</span>
                                  <span style={{ flex: 1 }} />
                                  <span style={{ fontSize: 10.5, color: "#9a9aa3" }}>{PERIOD_OPTIONS.find((p) => p.key === b.period)?.label || b.period} · {formatDateShort(b.earnedAt)}</span>
                                </div>
                              );
                            })}
                          </div>
                        )}
                      </div>
                    </Glass>
                  );
                })}
              </div>

              {(() => {
                const filtered = earnedBadges
                  .filter((b) => achievementsFilterSdr === "all" || b.sdrName === achievementsFilterSdr)
                  .sort((a, b) => new Date(b.earnedAt) - new Date(a.earnedAt));
                if (filtered.length === 0) {
                  return (
                    <Glass style={{ borderRadius: 18, padding: "50px 20px", textAlign: "center" }}>
                      <Trophy size={32} color="#d7d9de" style={{ marginBottom: 12 }} />
                      <div style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 19, color: "#475569", marginBottom: 6 }}>Nenhuma badge conquistada ainda</div>
                      <div style={{ fontSize: 13, color: "#94a3b8" }}>Ative uma meta e comece a bater os números pra desbloquear</div>
                    </Glass>
                  );
                }
                return (
                  <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 90 }}>
                    {filtered.map((b) => {
                      const tier = BADGE_TIERS.find((t) => t.key === b.tier);
                      const metric = METRIC_DEFS[b.metric];
                      const isActive = goalsConfig[b.metric]?.enabled;
                      return (
                        <Glass key={b.id} style={{ borderRadius: 14, padding: "12px 16px", display: "flex", alignItems: "center", gap: 14, opacity: isActive ? 1 : 0.7 }}>
                          <AchievementHex tier={tier} metric={metric} active={isActive} size={38} />
                          <div style={{ flex: 1, minWidth: 0 }}>
                            <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
                              <span style={{ fontSize: 13.5, fontWeight: 700, color: isActive ? "#14141a" : "#6b6b75" }}>{b.sdrName}</span>
                              <span style={{ fontSize: 10, fontWeight: 700, color: isActive ? tier.color : "#94a3b8", background: isActive ? tier.color + "15" : "rgba(148,163,184,0.15)", padding: "2px 7px", borderRadius: 6 }}>{tier.label}</span>
                              {!isActive && <span style={{ fontSize: 10, fontWeight: 700, color: "#64748b", background: "rgba(148,163,184,0.15)", padding: "2px 7px", borderRadius: 6 }}>Meta não ativa</span>}
                            </div>
                            <div style={{ fontSize: 12, color: "#9a9aa3" }}>{metric.label} · {b.value}/{b.target} · {formatDateFull(b.earnedAt)}</div>
                          </div>
                        </Glass>
                      );
                    })}
                  </div>
                );
              })()}
            </>
          )}

          {/* ═══════════════════ RELATÓRIOS (automático) ═══════════════════ */}
          {view === "relatorios" && (
            <>
              <div style={{ marginBottom: 20 }}>
                <div style={{ fontSize: 11, fontWeight: 400, letterSpacing: 1.5, textTransform: "uppercase", color: "#6d5ef8", marginBottom: 6 }}>Sales Intelligence · B2B</div>
                <h1 style={{ fontFamily: '"Open Sans", Arial, sans-serif', fontSize: 28, fontWeight: 800, margin: 0, color: "#14141a" }}>Relatórios</h1>
                <div style={{ fontSize: 13, color: "#9a9aa3", marginTop: 4 }}>Calculado automaticamente a partir dos seus leads e reuniões</div>
              </div>

              {/* Filtro de período */}
              <Glass style={{ borderRadius: 16, padding: "10px 14px", marginBottom: 16, display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                <span style={{ fontSize: 11, color: "#94a3b8", fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.6 }}>Período</span>
                {[
                  { key: "7", label: "7 dias" },
                  { key: "30", label: "30 dias" },
                  { key: "90", label: "90 dias" },
                  { key: "all", label: "Tudo" },
                ].map((p) => (
                  <Chip key={p.key} active={reportPeriod === p.key} onClick={() => setReportPeriod(p.key)} color="#6d5ef8">{p.label}</Chip>
                ))}
                <div style={{ flex: 1 }} />
                <span style={{ fontSize: 11, color: "#9a9aa3" }}>Reuniões e contatos no período · leads e SDR são totais acumulados</span>
              </Glass>

              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px, 1fr))", gap: 12, marginBottom: 20 }}>
                <Glass style={{ borderRadius: 16, padding: "14px 16px" }}>
                  <div style={{ fontSize: 11, color: "#9a9aa3", fontWeight: 700 }}>Taxa de conversão</div>
                  <div style={{ fontSize: 24, fontWeight: 800, color: "#14141a", marginTop: 4 }}>{stats.total ? Math.round((stats.vendidas / stats.total) * 100) : 0}%</div>
                </Glass>
                <Glass style={{ borderRadius: 16, padding: "14px 16px" }}>
                  <div style={{ fontSize: 11, color: "#9a9aa3", fontWeight: 700 }}>Ticket médio</div>
                  <div style={{ fontSize: 24, fontWeight: 800, color: "#14141a", marginTop: 4 }}>{formatBRL(stats.vendidas ? stats.receita / stats.vendidas : 0)}</div>
                </Glass>
                <Glass style={{ borderRadius: 16, padding: "14px 16px" }}>
                  <div style={{ fontSize: 11, color: "#9a9aa3", fontWeight: 700 }}>Reuniões ({reportStats.label})</div>
                  <div style={{ fontSize: 24, fontWeight: 800, color: "#14141a", marginTop: 4 }}>{reportStats.meetingsInPeriod}</div>
                </Glass>
                <Glass style={{ borderRadius: 16, padding: "14px 16px" }}>
                  <div style={{ fontSize: 11, color: "#9a9aa3", fontWeight: 700 }}>Contatos ({reportStats.label})</div>
                  <div style={{ fontSize: 24, fontWeight: 800, color: "#14141a", marginTop: 4 }}>{reportStats.contactedInPeriod}</div>
                </Glass>
              </div>

              {/* Receita com meta editável */}
              <Glass style={{ borderRadius: 18, padding: "18px 20px", marginBottom: 16 }}>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 8, marginBottom: 10 }}>
                  <div style={{ fontSize: 14, fontWeight: 800, color: "#14141a" }}>Receita</div>
                  <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                    <span style={{ fontSize: 11, color: "#9a9aa3", fontWeight: 600 }}>Meta:</span>
                    {editingRevenueGoal ? (
                      <input
                        type="number"
                        min={1}
                        autoFocus
                        defaultValue={revenueGoal}
                        onBlur={(e) => { const v = parseInt(e.target.value, 10); setRevenueGoal(v > 0 ? v : DEFAULT_REVENUE_GOAL); setEditingRevenueGoal(false); }}
                        onKeyDown={(e) => { if (e.key === "Enter") e.target.blur(); }}
                        style={{ width: 90, padding: "3px 6px", borderRadius: 7, border: "1.5px solid #6d5ef8", fontSize: 12.5, fontWeight: 700, color: "#14141a", outline: "none" }}
                      />
                    ) : (
                      <button
                        onClick={() => setEditingRevenueGoal(true)}
                        title="Clique para definir a meta de receita"
                        style={{ display: "flex", alignItems: "center", gap: 5, padding: "3px 9px", borderRadius: 7, border: "1px dashed rgba(109,94,248,0.4)", background: "rgba(109,94,248,0.08)", color: "#6d5ef8", fontSize: 12.5, fontWeight: 700, cursor: "pointer" }}
                      >
                        {formatBRL(revenueGoal)} <Pencil size={11} />
                      </button>
                    )}
                  </div>
                </div>
                <div style={{ fontSize: 30, fontWeight: 800, color: "#14141a", marginBottom: 8 }}>{formatBRL(stats.receita)}</div>
                <div style={{ height: 8, borderRadius: 4, background: "#eef0f3" }}>
                  <div style={{
                    height: "100%", borderRadius: 4,
                    width: `${Math.min(100, Math.round((stats.receita / revenueGoal) * 100))}%`,
                    background: stats.receita >= revenueGoal ? "linear-gradient(90deg, #34d399, #059669)" : "linear-gradient(90deg, #a79bfc, #6d5ef8)",
                    transition: "width 0.3s ease",
                  }} />
                </div>
                <div style={{ fontSize: 11.5, color: "#9a9aa3", marginTop: 6 }}>{Math.round((stats.receita / revenueGoal) * 100)}% da meta de {formatBRL(revenueGoal)}</div>
              </Glass>

              <Glass style={{ borderRadius: 18, padding: "18px 20px", marginBottom: 16 }}>
                <div style={{ fontSize: 14, fontWeight: 800, color: "#14141a", marginBottom: 12 }}>Leads por estágio</div>
                {STAGE_OPTIONS.map((s) => {
                  const count = leads.filter((l) => l.stage === s).length;
                  const pct = stats.total ? Math.round((count / stats.total) * 100) : 0;
                  return (
                    <div
                      key={s}
                      onClick={() => { setQuickStage(null); setSearch(""); setTempFilter("all"); setWhatsappOnly(false); setOwnerFilter("all"); setStatusFilter("all"); setPhaseFilter("all"); setSuperOnly(false); setView("dashboard"); scrollToGrid(); }}
                      style={{ marginBottom: 10, cursor: "pointer" }}
                      title={`Ver leads em ${s}`}
                    >
                      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, marginBottom: 4 }}>
                        <span style={{ color: "#6b6b75", fontWeight: 600 }}>{s}</span>
                        <span style={{ color: "#14141a", fontWeight: 700 }}>{count}</span>
                      </div>
                      <div style={{ height: 7, borderRadius: 4, background: "#eef0f3" }}>
                        <div style={{ height: "100%", width: `${pct}%`, borderRadius: 4, background: STAGE_COLORS[s] }} />
                      </div>
                    </div>
                  );
                })}
              </Glass>

              <Glass style={{ borderRadius: 18, padding: "18px 20px", marginBottom: 90 }}>
                <div style={{ fontSize: 14, fontWeight: 800, color: "#14141a", marginBottom: 12 }}>Performance por SDR</div>
                {sdrs.map((s) => {
                  const own = leads.filter((l) => l.owner === s.name);
                  const won = own.filter((l) => l.stage === "Conquistado").length;
                  const revenue = own.filter((l) => l.stage === "Conquistado").reduce((sum, l) => sum + getDealValue(l), 0);
                  return (
                    <div
                      key={s.name}
                      onClick={() => { setOwnerFilter(s.name); setSearch(""); setTempFilter("all"); setWhatsappOnly(false); setStatusFilter("all"); setPhaseFilter("all"); setSuperOnly(false); setQuickStage(null); setView("dashboard"); scrollToGrid(); }}
                      title={`Ver leads de ${s.name}`}
                      style={{ display: "flex", alignItems: "center", gap: 12, padding: "10px 0", borderTop: "1px solid #f1f2f5", cursor: "pointer" }}
                    >
                      <OwnerAvatar name={s.name} size={32} />
                      <div style={{ flex: 1 }}>
                        <div style={{ fontSize: 13.5, fontWeight: 700, color: "#14141a" }}>{s.name}</div>
                        <div style={{ fontSize: 11, color: "#9a9aa3" }}>{own.length} leads · {won} conquistados</div>
                      </div>
                      <div style={{ fontSize: 14, fontWeight: 800, color: "#1fa971" }}>{formatBRL(revenue)}</div>
                      <ChevronRight size={15} color="#c4c4cc" />
                    </div>
                  );
                })}
                <button
                  onClick={() => setShowSdrManager(true)}
                  style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 12, padding: "8px 12px", borderRadius: 9, border: "1px dashed rgba(148,163,184,0.4)", background: "transparent", color: "#94a3b8", fontSize: 12, fontWeight: 600, cursor: "pointer" }}
                >
                  <Pencil size={12} /> Gerenciar SDRs
                </button>
              </Glass>
            </>
          )}
        </div>

        {selected && <LeadDetail lead={selected} onClose={() => setSelected(null)} onSave={updateLead} onDelete={deleteLead} onQuickContact={handleQuickContact} sdrs={sdrs} onSetWeekTag={setWeekTag} onToggleSuper={toggleSuperAttention} />}
        {quickContactLead && <QuickContactModal lead={quickContactLead} onClose={() => setQuickContactLead(null)} onDispatch={handleQuickContact} />}
        {showWaSendScreen && (
          <WaSendListScreen
            leadsInList={waSendList.map((item) => {
              const lead = leads.find((l) => l.id === item.leadId);
              return lead ? { ...lead, waMessage: item.message } : null;
            }).filter(Boolean)}
            history={waSendHistory}
            onClose={() => setShowWaSendScreen(false)}
            onRemove={(id) => setWaSendList((prev) => prev.filter((x) => x.leadId !== id))}
            onClear={() => setWaSendList([])}
            onLogSent={logWaListSend}
            onEditMessage={editWaListMessage}
          />
        )}
        {scriptPickerLead && (
          <ScriptPickerModal
            lead={scriptPickerLead}
            onClose={() => setScriptPickerLead(null)}
            onSelect={addToWaListWithScript}
          />
        )}
        {showWeekHistory && (
          <WeekHistoryScreen
            history={weekHistory}
            leads={leads}
            onClose={() => setShowWeekHistory(false)}
            onOpenLead={(lead) => { setShowWeekHistory(false); setSelected(lead); }}
          />
        )}
        {selectedMeeting && <MeetingDetail meeting={selectedMeeting} leads={leads} onClose={() => setSelectedMeeting(null)} onSave={saveMeeting} onDelete={deleteMeeting} sdrs={sdrs} />}
        {showSdrManager && (
          <SdrManager
            sdrs={sdrs} leads={leads} meetings={meetings}
            onAdd={addSdr} onRemove={removeSdr} onUpdateAvatar={updateSdrAvatar}
            onClose={() => setShowSdrManager(false)}
            authMembers={authMembers} onSync={syncSdrsWithAuthMembers}
          />
        )}
        {showImportModal && <ImportModal sdrs={sdrs} existingLeads={leads} onClose={() => setShowImportModal(false)} onConfirm={confirmImport} />}
        {showBulkPhoneModal && <BulkPhoneModal leads={leads} onClose={() => setShowBulkPhoneModal(false)} onApply={applyBulkPhones} />}
        {showNotifications && (
          <NotificationsPanel
            stats={stats}
            onClose={() => setShowNotifications(false)}
            onNavigate={(v) => { setShowNotifications(false); setView(v); }}
          />
        )}
        {showMenu && (
          <MenuPanel
            view={view}
            onNavigate={(v) => { setView(v); setShowMenu(false); }}
            onClose={() => setShowMenu(false)}
            onManageSdrs={() => { setShowMenu(false); setShowSdrManager(true); }}
            onImport={() => { setShowMenu(false); setShowImportModal(true); }}
            onBulkPhones={() => { setShowMenu(false); setShowBulkPhoneModal(true); }}
            onNewLead={() => { setShowMenu(false); createLead(); }}
            onSwitchWorkspace={onSwitchWorkspace ? () => { setShowMenu(false); onSwitchWorkspace(); } : undefined}
            workspaceName={workspaceName}
          />
        )}
        {badgeQueue.length > 0 && <BadgePopup badge={badgeQueue[0]} onClose={() => setBadgeQueue((prev) => prev.slice(1))} />}

        {/* ── BOTÃO FLUTUANTE: LISTA DE ENVIO WHATSAPP (só aparece com itens na lista) ── */}
        {waSendList.length > 0 && view !== "assistente" && (
          <button
            onClick={() => setShowWaSendScreen(true)}
            title="Lista de envio WhatsApp"
            style={{
              position: "fixed", right: 84, bottom: 90, width: 50, height: 50, borderRadius: "50%",
              border: "none", background: "linear-gradient(135deg, #25d366, #128c4a)", color: "white",
              display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer",
              boxShadow: "0 10px 26px -8px rgba(37,211,102,0.6)", zIndex: 85, animation: "popIn 0.25s cubic-bezier(0.34, 1.56, 0.64, 1)",
            }}
          >
            <Send size={19} />
            <span style={{ position: "absolute", top: -4, right: -4, minWidth: 20, height: 20, borderRadius: 10, background: "#f59e0b", color: "white", fontSize: 10.5, fontWeight: 800, display: "flex", alignItems: "center", justifyContent: "center", padding: "0 5px", border: "2px solid white" }}>
              {waSendList.length}
            </span>
          </button>
        )}

        {/* ── BOTÃO FLUTUANTE: ASSISTENTE DE IA (logo com anel de LED girando) ── */}
        {view !== "assistente" && (
          <button
            onClick={() => setView("assistente")}
            title="Assistente de vendas com IA"
            style={{
              position: "fixed", right: 18, bottom: 90, width: 58, height: 58, borderRadius: "50%",
              border: "none", background: "transparent", padding: 0, cursor: "pointer",
              boxShadow: "0 10px 28px -8px rgba(215,250,60,0.55)", zIndex: 85,
            }}
          >
            <div style={{
              width: "100%", height: "100%", borderRadius: "50%", padding: 3, boxSizing: "border-box",
              background: "conic-gradient(from 0deg, transparent 0%, #d7fa3c 14%, transparent 30%, transparent 100%)",
              animation: "ledSpin 2.4s linear infinite",
            }}>
              <img src="/funnio-icon-round.png" alt="Assistente Funnio" style={{ width: "100%", height: "100%", borderRadius: "50%", display: "block", objectFit: "cover" }} />
            </div>
          </button>
        )}

        {/* ── BARRA DE NAVEGAÇÃO INFERIOR FIXA ── */}
        <div style={{ position: "fixed", bottom: 0, left: 0, right: 0, background: "white", borderTop: "1px solid #eef0f3", padding: "10px 12px calc(10px + env(safe-area-inset-bottom))", display: "flex", justifyContent: "space-around", zIndex: 90, boxShadow: "0 -8px 24px -12px rgba(20,20,26,0.12)" }}>
          {[
            { key: "dashboard", label: "Home", icon: HomeIcon },
            { key: "leads-tab", label: "Leads", icon: Users },
            { key: "agenda", label: "Calendário", icon: CalendarIcon },
            { key: "relatorios", label: "Relatórios", icon: PieChart },
          ].map((t) => {
            const active = view === t.key || (t.key === "leads-tab" && view === "dashboard" && false);
            return (
              <button
                key={t.key}
                onClick={() => { if (t.key === "leads-tab") { setView("dashboard"); scrollToGrid(); } else setView(t.key); }}
                style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 3, border: "none", background: "transparent", cursor: "pointer", padding: "4px 14px", borderRadius: 12 }}
              >
                <div style={{ width: 34, height: 34, borderRadius: 10, background: active ? DARK.limeSoft : "transparent", display: "flex", alignItems: "center", justifyContent: "center" }}>
                  <t.icon size={18} color={active ? "#8fae0e" : "#9a9aa3"} strokeWidth={2.2} />
                </div>
                <span style={{ fontSize: 10.5, fontWeight: 700, color: active ? "#14141a" : "#9a9aa3" }}>{t.label}</span>
              </button>
            );
          })}
        </div>

        {toast && (
          <div style={{ position: "fixed", bottom: 90, left: "50%", transform: "translateX(-50%)", background: "#0f172a", color: "white", padding: "12px 20px", borderRadius: 12, fontSize: 13, fontWeight: 600, boxShadow: "0 12px 32px -8px rgba(0,0,0,0.4)", zIndex: 200, animation: "toastIn 0.25s ease", display: "flex", alignItems: "center", gap: 8 }}>
            <Sparkles size={14} /> {toast}
          </div>
        )}
      </div>
    </>
  );
}
